315. void cublas_gemm(const Tensor *inputA, const Tensor *inputB, Tensor *outputD,
316.                  const Tensor *inputBias, Tensor *outputPreGelu, cublasOperation_t transa,
317.                  cublasOperation_t transb, bool grad, void *workspace, size_t workspaceSize,
318.                  const void *alpha, const void *beta, bool use_split_accumulator, int math_sm_count,
319.                  int m_split, int n_split, bool gemm_producer, const Tensor *inputCounter,
320.                  cudaStream_t stream) {
321.   NVTE_CHECK(!inputA->row_scaled_nvfp4 && !inputB->row_scaled_nvfp4,
322.              "cuBLAS GEMM does not support row-scaled NVFP4 inputs.");
323. 
324.   // Tensor dims in row-major order
325.   const int A0 = inputA->flat_first_dim();
326.   const int A1 = inputA->flat_last_dim();
327.   const int B0 = inputB->flat_first_dim();
328.   const int B1 = inputB->flat_last_dim();
329. 
330.   // GEMM dims in column-major order
331.   const int m = transa == CUBLAS_OP_T ? A0 : A1;
332.   const int n = transb == CUBLAS_OP_T ? B1 : B0;
333.   const int k = transa == CUBLAS_OP_T ? A1 : A0;
334.   NVTE_CHECK((transb == CUBLAS_OP_T ? B0 : B1) == k,
335.              "GEMM inputs have incompatible dimensions (A is ", A0, "x", A1, ", B is ", B0, "x", B1,
336.              ")");
337.   const int ldd = m;
338. 
339.   // Return immediately if GEMM is trivial
340.   if (m <= 0 || n <= 0) {
341.     return;
342.   }
343.   NVTE_CHECK(k > 0);
344. 
345.   const GemmParam param = CanonicalizeGemmInput(*inputA, transa, *inputB, transb, m, n, k);
346. 
347.   void *C = outputD->data.dptr;
348.   void *D = outputD->data.dptr;
349.   void *D_scale = outputD->scale.dptr;
350.   void *D_amax = outputD->amax.dptr;

