16. template <uint32_t HIDDEN_SIZE_, typename weight_t_, typename input_t_, typename output_t_,
17.           typename compute_t_, typename index_t_, uint32_t THREADS_PER_CTA_>
18. struct Kernel_traits_base {
19.   using weight_t = weight_t_;
20.   using input_t = input_t_;
21.   using output_t = output_t_;
22.   using compute_t = compute_t_;
23.   using index_t = index_t_;
24. 
25.   enum { HIDDEN_SIZE = HIDDEN_SIZE_ };
26.   enum { THREADS_PER_CTA = THREADS_PER_CTA_ };
27.   enum { THREADS_PER_WARP = 32 };
28. };
29. 
30. template <uint32_t HIDDEN_SIZE_, typename weight_t_, typename input_t_, typename output_t_,
31.           typename compute_t_, typename index_t_, uint32_t THREADS_PER_CTA_,
32.           uint32_t BYTES_PER_LDG_,
33.           typename Base = Kernel_traits_base<HIDDEN_SIZE_, weight_t_, input_t_, output_t_,
34.                                              compute_t_, index_t_, THREADS_PER_CTA_> >
35. struct Kernel_traits_finalize : public Base {
36.   enum { ROWS_PER_CTA = Base::THREADS_PER_CTA / Base::THREADS_PER_WARP };
37.   static_assert(static_cast<int>(ROWS_PER_CTA) <= static_cast<int>(Base::THREADS_PER_WARP));
38.   // Bytes per global load from the input.
39.   enum { BYTES_PER_LDG = BYTES_PER_LDG_ };
40.   // Number of elements fetched by a global load.
41.   enum { ELTS_PER_LDG = BYTES_PER_LDG / sizeof(compute_t_) };
42.   // Bytes per global store of the weights.
43.   enum { BYTES_PER_STG = ELTS_PER_LDG * sizeof(weight_t_) };
44.   static_assert(sizeof(BYTES_PER_LDG) == 4,
45.                 "Conflict-free smem transpose only implemented for 4B compute type!");
46.   static_assert(Base::THREADS_PER_CTA == ROWS_PER_CTA * Base::THREADS_PER_WARP,
47.                 "We assume one warp per row!");
48.   // The total number of BYTES_PER_LDG-wide words in a hidden vector.
49.   enum { COLS = HIDDEN_SIZE_ * sizeof(compute_t_) / BYTES_PER_LDG };
50.   static_assert(COLS * BYTES_PER_LDG == HIDDEN_SIZE_ * sizeof(compute_t_));
51. 
52.   // Shared memory size to transpose the CTA result.
53.   enum { SMEM_BYTES_TRANSPOSE = Base::THREADS_PER_CTA * BYTES_PER_LDG };
54.   // Shared memory size to coalsece the CTA result.
55.   enum { SMEM_BYTES_OUTPUT = Base::THREADS_PER_WARP * BYTES_PER_LDG };
56.   // Shared memory requirement per CTA.
57.   enum { SMEM_BYTES_PER_CTA = 2 * SMEM_BYTES_TRANSPOSE + 2 * SMEM_BYTES_OUTPUT };
58. 
59.   // The type of the reducer.
60.   using Reducer = transformer_engine::Reducer<compute_t_, 1, 1, 1>;
61. 
62.   // Condition for the whole CTA to participate in syncthreads.
63.   static_assert(COLS % Base::THREADS_PER_WARP == 0);
64.   enum { CTAS = COLS / Base::THREADS_PER_WARP };
65. };
66. 
67. template <typename weight_t_, typename input_t_, typename output_t_, typename compute_t_,
68.           typename index_t_, uint32_t HIDDEN_SIZE_, uint32_t CTAS_PER_ROW_, uint32_t WARPS_M_,
69.           uint32_t WARPS_N_, uint32_t BYTES_PER_LDG_ = 16,
70.           typename Base =
71.               Kernel_traits_base<HIDDEN_SIZE_, weight_t_, input_t_, output_t_, compute_t_, index_t_,
72.                                  WARPS_M_ * WARPS_N_ * THREADS_PER_WARP> >
73. struct Kernel_traits : public Base {
74.   using input_t = typename Base::input_t;
75.   using weight_t = typename Base::weight_t;
76.   using compute_t = typename Base::compute_t;
77.   using output_t = typename Base::output_t;
78.   using index_t = typename Base::index_t;
79. 
80.   enum { CTAS_PER_ROW = CTAS_PER_ROW_ };
81.   enum { WARPS_M = WARPS_M_ };
82.   enum { WARPS_N = WARPS_N_ };
83.   enum { COLS = HIDDEN_SIZE_ };
84.   enum { HIDDEN_SIZE = HIDDEN_SIZE_ };
85.   enum { BYTES_PER_LDG = BYTES_PER_LDG_ };
86.   enum { NUM_ELTS = BYTES_PER_LDG / sizeof(input_t) };
87. 
88.   enum { THREADS_PER_ROW = WARPS_N * THREADS_PER_WARP };
89.   enum { THREADS_PER_CTA = WARPS_M * THREADS_PER_ROW };
90.   enum { ROWS_PER_CTA = WARPS_M };
91. 
92.   enum { BYTES_PER_ROW = COLS * sizeof(input_t) };
93.   enum { BYTES_PER_ROW_PER_CTA = THREADS_PER_ROW * BYTES_PER_LDG };
94.   // Multi-row per CTA not supported for multi-CTA => no smem for WGRAD needed
95.   enum { SMEM_BYTES_WGRAD = CTAS_PER_ROW > 1 ? 0 : ROWS_PER_CTA* COLS * sizeof(compute_t) };
96.   static_assert(WARPS_M == 1 || CTAS_PER_ROW == 1);
97. 
98.   using reduce_t = typename transformer_engine::TypeToVec2<compute_t>::Type;
99.   using Reducer = transformer_engine::Reducer<reduce_t, CTAS_PER_ROW, WARPS_M, WARPS_N>;
100. 
101.   enum { SMEM_BYTES_DGRAD = Reducer::SMEM_BYTES };
102.   enum { SMEM_BYTES = SMEM_BYTES_DGRAD + SMEM_BYTES_WGRAD };
103. 
104.   using Ivec = transformer_engine::Vec<input_t, NUM_ELTS>;
105.   using Ovec = transformer_engine::Vec<output_t, NUM_ELTS>;
106.   using Wvec = transformer_engine::Vec<weight_t, NUM_ELTS>;
107.   using Cvec = transformer_engine::Vec<compute_t, NUM_ELTS>;
108.   enum { ELTS_PER_LDG = BYTES_PER_LDG / sizeof(input_t) };
109. 
110.   // Assume that each thread can handle the same number of elements
111.   // in the output and weights as in the input.
112.   static_assert(sizeof(input_t) >= sizeof(output_t));
113.   static_assert(sizeof(input_t) >= sizeof(weight_t));
114.   // The number of columns fetched per load from input: one per thread.
115.   enum { VEC_COLS_PER_LDG = CTAS_PER_ROW * THREADS_PER_ROW };
116.   // The total number of vectorized loads/stores per hidden vector.
117.   enum { VEC_COLS = COLS / ELTS_PER_LDG };
118.   // The number of loads per thread for the input.
119.   enum { LDGS = VEC_COLS / VEC_COLS_PER_LDG };
120.   static_assert(LDGS * VEC_COLS_PER_LDG == VEC_COLS);
121.   // static_assert(LDGS * BYTES_PER_ROW_PER_CTA * CTAS_PER_ROW == BYTES_PER_ROW, "");
122. 
123.   using Stats = transformer_engine::Stats<compute_t, CTAS_PER_ROW, WARPS_M, WARPS_N>;
124.   enum { SMEM_BYTES_FWD = Stats::SMEM_BYTES };
125. };
126. 
