84. // Dropout forward with FP16/BF16 input and output.
85. template <typename T>
86. __global__ void __launch_bounds__(block_size)
87.     dropout_kernel_fwd_f16(const T *__restrict__ input_ptr, T *__restrict__ output_ptr,
88.                            uint8_t *__restrict__ mask_ptr,
89.                            const uint64_t *__restrict__ rng_state_ptr, size_t num_chunks,
90.                            uint32_t bytewise_drop_prob, float scale) {
91.   static_assert(sizeof(T) == 2);
92. 
93.   // Each thread processes a chunk of 16 entries
94.   const size_t gid = threadIdx.x + blockIdx.x * block_size;
95.   const size_t nthreads = gridDim.x * block_size;
96.   for (size_t chunk_idx = gid; chunk_idx < num_chunks; chunk_idx += nthreads) {
97.     // Generate dropout mask
98.     auto local_mask =
99.         make_16bit_mask(chunk_idx, rng_state_ptr[0], rng_state_ptr[1], bytewise_drop_prob);
100.     reinterpret_cast<uint16_t *>(mask_ptr)[chunk_idx] = local_mask;
101. 
102.     // Read input data
103.     using VectorType = Vector<T, rng_chunk_size>;
104.     VectorType local_data;
105.     local_data = reinterpret_cast<const VectorType *>(input_ptr)[chunk_idx];
106. 
107.     // Apply dropout based on mask
108. #pragma unroll
109.     for (size_t i = 0; i < rng_chunk_size; i++) {
110.       float val = static_cast<float>(local_data.entries[i]);
111.       if ((local_mask & 0x1) == 0) {
112.         val = 0;
113.       }
114.       val *= scale;
115.       local_data.entries[i] = static_cast<T>(val);
116.       local_mask >>= 1;
117.     }
118. 
119.     // Write output data
120.     reinterpret_cast<VectorType *>(output_ptr)[chunk_idx] = local_data;

