192.   return (int64_t)(ROUND_UP(num_gemms * sizeof(ProblemShapeType), 128UL));
193. }
194. 
195. int64_t inline getPtrSize(int64_t num_gemms) {
196.   return (int64_t)(ROUND_UP(num_gemms * sizeof(half*), 128UL));
197. }
198. 
199. int64_t inline getLddSize(int64_t num_gemms) {
200.   return (int64_t)(ROUND_UP(num_gemms * sizeof(int64_t), 128UL));
201. }
202. 
203. // cpu workspace size is 4MB
204. static constexpr size_t kCPUWorkSpaceSize = 4 * 1024 * 1024;
205. 
206. static char* getHostWorkspace() {
207.   static std::once_flag flag;
208.   static std::shared_ptr<char> workspace;
209. 
210.   std::call_once(flag, [&]() {
211.     workspace =
212.         std::shared_ptr<char>(reinterpret_cast<char*>(std::malloc(kCPUWorkSpaceSize)), [](char* p) {
213.           if (p) std::free(p);
214.         });
215. 
216.     if (!workspace) {
217.       throw std::bad_alloc();
218.     }
219.   });
220. 
221.   return workspace.get();
222. }
