224. template <bool trans_a, bool trans_b, typename Element>
225. void CutlassGroupedGemm(const NVTETensor* A, const NVTETensor* B, NVTETensor* D,
226.                         NVTETensor* workspace, float alpha, float beta, int num_gemms,
227.                         cudaStream_t stream, int device, int math_sm_count) {
228.   using Gemm = GemmGrouped<Element, trans_a, trans_b>;
229.   using LayoutA = typename Gemm::LayoutA;
230.   using LayoutB = typename Gemm::LayoutB;
231.   using LayoutC = typename Gemm::LayoutC;
232. 
233.   using ElementA = typename Gemm::ElementA;
234.   using ElementB = typename Gemm::ElementB;
235.   using ElementC = typename Gemm::ElementC;
236. 
237.   using StrideA = typename Gemm::GemmKernel::InternalStrideA;
238.   using StrideB = typename Gemm::GemmKernel::InternalStrideB;
239.   using StrideC = typename Gemm::GemmKernel::InternalStrideC;
240. 
241.   typename Gemm::Arguments arguments;
242.   size_t kernel_workspace_size = Gemm::get_workspace_size(arguments);
243.   auto gemm_coord_size = getGemmCoordSize(num_gemms);
244.   auto ptr_size = getPtrSize(num_gemms);
245.   auto ldd_size = getLddSize(num_gemms);
246.   auto param_workspace_size = 3 * ptr_size + 3 * ldd_size + gemm_coord_size;
247. 
248.   NVTE_CHECK(
249.       param_workspace_size < kCPUWorkSpaceSize,
250.       "Insufficient kCPUWorkSpaceSize size: required=", static_cast<int64_t>(param_workspace_size),
251.       ", available=", static_cast<int64_t>(kCPUWorkSpaceSize), " for CUTLASS grouped GEMM.");
252. 
253.   auto total_workspace_size = param_workspace_size + kernel_workspace_size;
254.   transformer_engine::Tensor* wspace = transformer_engine::convertNVTETensor(workspace[0]);
255. 
256.   NVTE_CHECK(total_workspace_size < wspace->numel(), "Insufficient workspace[0] size: required=",
257.              static_cast<int64_t>(total_workspace_size),
258.              ", available=", static_cast<int64_t>(wspace->numel()), " for CUTLASS grouped GEMM.");
259. 
260.   char* workspace_ptr = reinterpret_cast<char*>(wspace->data.dptr);
261. 
262.   char* kernel_workspace_ptr = nullptr;
263. 
264.   char* host_workspace = getHostWorkspace();
265. 
266.   ProblemShapeType* problem_sizes_host = reinterpret_cast<ProblemShapeType*>(host_workspace);
267. 
268.   ElementA** ptr_A_host = reinterpret_cast<ElementA**>(host_workspace + gemm_coord_size);
269.   ElementB** ptr_B_host = reinterpret_cast<ElementB**>(host_workspace + gemm_coord_size + ptr_size);
270.   ElementC** ptr_C_host =
271.       reinterpret_cast<ElementC**>(host_workspace + gemm_coord_size + 2 * ptr_size);
272.   int64_t* lda_host =
273.       reinterpret_cast<int64_t*>(host_workspace + gemm_coord_size + 3 * ptr_size + 0 * ldd_size);
274.   int64_t* ldb_host =
275.       reinterpret_cast<int64_t*>(host_workspace + gemm_coord_size + 3 * ptr_size + 1 * ldd_size);
276.   int64_t* ldc_host =
277.       reinterpret_cast<int64_t*>(host_workspace + gemm_coord_size + 3 * ptr_size + 2 * ldd_size);
278. 
279.   for (size_t i = 0; i < num_gemms; i++) {
280.     const transformer_engine::Tensor* inputA = transformer_engine::convertNVTETensorCheck(A[i]);
281.     const transformer_engine::Tensor* inputB = transformer_engine::convertNVTETensorCheck(B[i]);
282.     transformer_engine::Tensor* outputD = transformer_engine::convertNVTETensor(D[i]);
283. 
284.     const int m = trans_a ? inputA->data.shape[1] : inputA->data.shape[0];
285.     const int k = trans_a ? inputA->data.shape[0] : inputA->data.shape[1];
286.     const int n = trans_b ? inputB->data.shape[0] : inputB->data.shape[1];
287. 
288.     auto problem = ProblemShapeType(m, n, k);
289.     problem_sizes_host[i] = problem;
290. 
291.     ptr_A_host[i] = reinterpret_cast<ElementA*>(inputA->data.dptr);
292.     ptr_B_host[i] = reinterpret_cast<ElementB*>(inputB->data.dptr);
293.     ptr_C_host[i] = reinterpret_cast<ElementC*>(outputD->data.dptr);
294. 
295.     lda_host[i] = LayoutA::packed({m, k}).stride(0);
296.     ldb_host[i] = LayoutB::packed({k, n}).stride(0);
297.     ldc_host[i] = LayoutC::packed({m, n}).stride(0);
298.   }
299. 
300.   cudaMemcpyAsync(workspace_ptr, host_workspace, param_workspace_size, cudaMemcpyHostToDevice,

150.       static_assert(std::is_same<compute_t, float>::value);
151.       atomicMaxFloat(reinterpret_cast<compute_t *>(params.amax), amax);
152.     }
153.   }
154. 
155.   if (params.fp8_out) {
156.     // Update scale-inverse
157.     if (blockIdx.x == 0 && threadIdx.x == 0 && params.scale_inv != nullptr) {
158.       reciprocal<compute_t>(reinterpret_cast<compute_t *>(params.scale_inv), scale);
159.     }
160.   }
161. }
