163. template <typename Ktraits>
164. __global__ __launch_bounds__(Ktraits::THREADS_PER_CTA) void ln_fwd_general_kernel(
165.     ForwardKernelParams params) {
166.   enum { LDGS = Ktraits::LDGS };
167.   enum { NUM_ELTS = Ktraits::NUM_ELTS };
168.   enum { WARPS_M = Ktraits::WARPS_M };
169.   enum { WARPS_N = Ktraits::WARPS_N };
170. 
171.   using input_t = typename Ktraits::input_t;
172.   using weight_t = typename Ktraits::weight_t;
173.   using output_t = typename Ktraits::output_t;
174.   using index_t = typename Ktraits::index_t;
175.   using compute_t = typename Ktraits::compute_t;
176.   using Ivec = typename Ktraits::Ivec;
177.   using Ovec = typename Ktraits::Ovec;
178.   using Wvec = typename Ktraits::Wvec;
179.   using Cvec = typename Ktraits::Cvec;
180. 
181.   const index_t tidx = threadIdx.x;
182.   const index_t lane = tidx % THREADS_PER_WARP;
183.   const index_t warp = tidx / THREADS_PER_WARP;
184.   const index_t warp_m = warp / WARPS_N;
185.   const index_t warp_n = warp % WARPS_N;
186. 
187.   const index_t bdimm = WARPS_M;
188.   const index_t bdimn = WARPS_N * THREADS_PER_WARP;
189.   const index_t bidm = blockIdx.x / params.ctas_per_row;
190.   const index_t bidn = blockIdx.x % params.ctas_per_row;
191. 
192.   const index_t gdimm = bdimm * params.ctas_per_col;
193.   const index_t gdimn = bdimn * params.ctas_per_row;
194.   const index_t gidm = bidm * bdimm + warp_m;
195.   const index_t gidn = (bidn * THREADS_PER_WARP + warp_n * params.ctas_per_row * THREADS_PER_WARP +
196.                         lane);  // Order threads by warp x cta x lane
197. 
198.   // Objects for stats reductions
199.   using Reducer = DynamicReducer<compute_t, WARPS_M, WARPS_N>;
200.   constexpr int SMEM_BYTES = Reducer::SMEM_BYTES > 0 ? Reducer::SMEM_BYTES : 1;
201.   __shared__ char smem_[SMEM_BYTES];
202.   Reducer reducer(params, bidm, bidn, warp_m, warp_n, lane, smem_);
203.   Sum<compute_t> sum;
204.   const compute_t rn = 1.f / static_cast<compute_t>(params.cols);
205. 
206.   // Load weights
207.   Cvec gamma[LDGS];
208.   Cvec beta[LDGS];
209. #pragma unroll
210.   for (int it = 0, col = gidn * NUM_ELTS; it < LDGS && col < params.cols;
211.        ++it, col += gdimn * NUM_ELTS) {
212.     Wvec gamma_in, beta_in;
213.     gamma_in.load_from_elts(params.gamma, col, params.cols - col);
214.     beta_in.load_from_elts(params.beta, col, params.cols - col);
215.     gamma_in.to(gamma[it]);
216.     beta_in.to(beta[it]);
217.   }
218. 
219.   // fp8 factors
220.   compute_t scale;
221.   if (params.fp8_out) {
222.     scale = *reinterpret_cast<compute_t *>(params.scale);
223.   }
224.   compute_t amax = 0;
225.   const bool requires_amax = params.amax != nullptr;
226. 
227.   for (int cta_row = bidm * bdimm; cta_row < params.rows; cta_row += gdimm) {
228.     const int row = cta_row + warp_m;
229. 
230.     // Load input
231.     Cvec x[LDGS];
232. #pragma unroll
233.     for (int it = 0, col = gidn * NUM_ELTS; it < LDGS && row < params.rows && col < params.cols;
234.          it++, col += gdimn * NUM_ELTS) {
235.       Ivec x_in;
236.       x_in.load_from_elts(params.x, row * params.cols + col, params.cols - col);
237.       x_in.to(x[it]);
238.     }
239. 
240.     // Compute mean
241.     compute_t mu = 0.f;
242. #pragma unroll
243.     for (int it = 0, col = gidn * NUM_ELTS; it < LDGS && row < params.rows && col < params.cols;
244.          it++, col += gdimn * NUM_ELTS) {
245. #pragma unroll
246.       for (int jt = 0; jt < NUM_ELTS; jt++) {
247.         mu += x[it].data.elt[jt];
248.       }
249.     }
250.     mu = reducer.allreduce(mu, sum) * rn;

