195.     compute_t *dbeta_part = static_cast<compute_t *>(params.dbeta_part) + bidm * COLS + tidx;
196.     for (int jt = 0; jt < NUM_RES; jt++) {
197.       *dbeta_part = cta_dz_sum[jt];
198.       dbeta_part += Ktraits::THREADS_PER_CTA;
199.     }
200.   }
201. }
