17. struct LseCorrectionFunctor {
18.   __forceinline__ __device__ static void run(float *lse, float *half_lse, size_t idx,
19.                                              size_t half_idx) {
20.     float val = lse[idx];
21.     float val_per_step = half_lse[half_idx];
22.     float max_scale = max(val, val_per_step);
23.     float min_scale = min(val, val_per_step);
24.     lse[idx] = max_scale + log1pf(expf(min_scale - max_scale));
25.   }
26. };
