39. struct CopyFunctor {
40.   __forceinline__ __device__ static void run(void *token, void *token_per_step, int idx) {
41.     reinterpret_cast<float4 *>(token)[idx] = reinterpret_cast<float4 *>(token_per_step)[idx];
42.   }
