45. template <typename dtype>
46. struct AddFunctor {
47.   __forceinline__ __device__ static void run(dtype *token, dtype *token_per_step, int idx) {
48.     float4 d_ = reinterpret_cast<float4 *>(token)[idx];
49.     dtype *p_ = reinterpret_cast<dtype *>(&d_);
50. 
51.     float4 d = reinterpret_cast<float4 *>(token_per_step)[idx];
52.     dtype *p = reinterpret_cast<dtype *>(&d);
53. 
54. #pragma unroll
55.     for (int i = 0; i < sizeof(float4) / sizeof(dtype); i++) {
56.       p_[i] = p_[i] + p[i];
57.     }
58. 
59.     reinterpret_cast<float4 *>(token)[idx] = d_;
60.   }
61. };
