63. /***************************************************************************************************
64.  * Support THD format for Context Parallel: Binary search an array for a target value
65.  **************************************************************************************************/
66. 
67. __forceinline__ __device__ int binary_search(int target, int *array, int len) {
68.   int left = 1, right = len - 1;
69.   while (left < right) {
70.     int mid = (left + right) / 2;
71.     if (array[mid] <= target) {
72.       left = mid + 1;
73.     } else {
74.       right = mid;
75.     }
76.   }
77.   return left - 1;
78. }
