80. /***************************************************************************************************
81.  * Support THD format for Context Parallel: Generate partitioned indices for input tokens
82.  **************************************************************************************************/
83. __global__ void thd_partition_indices_kernel(int *output, int *cu_seqlens, int batch,
84.                                              int total_tokens, int world_size, int rank) {
85.   extern __shared__ int cu_seqlens_s[];
86.   for (int i = threadIdx.x; i <= batch; i += blockDim.x) {
87.     int seqlen = cu_seqlens[i];
88.     // Currently we assume that each sequence length is divisible by (world_size*2) since we have
89.     // to distribute each sequence evenly to different GPUs.
90.     assert(seqlen % (world_size * 2) == 0);
91.     cu_seqlens_s[i] = seqlen / world_size;
92.   }
93.   __syncthreads();
94. 
95.   int tid = blockIdx.x * blockDim.x + threadIdx.x;
96.   int num_threads = blockDim.x * gridDim.x;
97. 
98.   for (int token_id = tid; token_id < total_tokens / world_size; token_id += num_threads) {
99.     int seq_id = binary_search(token_id, cu_seqlens_s, batch + 1);
100.     int seq_len = cu_seqlens_s[seq_id + 1] - cu_seqlens_s[seq_id];
101.     int index = token_id - cu_seqlens_s[seq_id];
102.     int offset = index < seq_len / 2 ? rank : (world_size - 1) * 2 - rank;
103.     index += cu_seqlens_s[seq_id] * world_size + seq_len / 2 * offset;
104.     output[token_id] = index;
105.   }
106. }
