108. /***************************************************************************************************
109.  * Support THD format for Context Parallel: Read the half of a THD tensor
110.  **************************************************************************************************/
111. 
112. __global__ void thd_read_half_tensor_kernel(void *half, void *tensor, int *cu_seqlens, int batch,
113.                                             int hidden_size_in_bytes, int half_idx,
114.                                             int dim_size_of_token) {
115.   extern __shared__ int cu_seqlens_s[];
116.   for (int i = threadIdx.x; i <= batch; i += blockDim.x) {
117.     cu_seqlens_s[i] = cu_seqlens[i] / 2;
118.   }
119.   __syncthreads();
120. 
121.   int warpid = (blockIdx.x * blockDim.x + threadIdx.x) / 32;
122.   int laneid = threadIdx.x % 32;
123.   int num_warps = (blockDim.x * gridDim.x) / 32;
124.   int num_total_tokens = cu_seqlens_s[batch];
125.   int num_float4s_per_token = hidden_size_in_bytes / sizeof(float4);
126. 
127.   size_t offset = static_cast<size_t>(dim_size_of_token) * hidden_size_in_bytes;
128.   half = reinterpret_cast<void *>(reinterpret_cast<char *>(half) + offset / 2 * blockIdx.y);
129.   tensor = reinterpret_cast<void *>(reinterpret_cast<char *>(tensor) + offset * blockIdx.y);
130. 
131.   for (int token_id = warpid; token_id < num_total_tokens; token_id += num_warps) {
132.     int seqid = binary_search(token_id, cu_seqlens_s, batch + 1);
133. 
134.     size_t offset_in_bytes = static_cast<size_t>(token_id) * hidden_size_in_bytes;
135.     float4 *cur_half_token =
136.         reinterpret_cast<float4 *>(reinterpret_cast<char *>(half) + offset_in_bytes);
137. 
138.     offset_in_bytes =
139.         (static_cast<size_t>(token_id) + cu_seqlens_s[seqid + half_idx]) * hidden_size_in_bytes;
140.     float4 *cur_token =
141.         reinterpret_cast<float4 *>(reinterpret_cast<char *>(tensor) + offset_in_bytes);
142. 
143.     for (int idx = laneid; idx < num_float4s_per_token; idx += 32) {
144.       cur_half_token[idx] = cur_token[idx];
145.     }
146.   }
147. }
