149. /***************************************************************************************************
150.  * Support THD format for Context Parallel: softmax_lse related operations
151.  **************************************************************************************************/
152. 
153. template <bool lse_packed, typename Functor>
154. __global__ void thd_lse_kernel(float *lse, float *half_lse, int *cu_seqlens, int batch,
155.                                int num_heads, int lse_seqlen, int second_half_lse_seqlen) {
156.   extern __shared__ int cu_seqlens_s[];
157.   for (int i = threadIdx.x; i <= batch; i += blockDim.x) {
158.     cu_seqlens_s[i] = cu_seqlens[i] / 2;
159.   }
160.   __syncthreads();
161. 
162.   int tid = blockIdx.x * blockDim.x + threadIdx.x;
163.   int num_threads = blockDim.x * gridDim.x;
164.   int num_total_tokens = cu_seqlens_s[batch];
165. 
166.   for (int token_id = tid; token_id < num_total_tokens; token_id += num_threads) {
167.     int seq_id = binary_search(token_id, cu_seqlens_s, batch + 1);
168.     for (int head_id = blockIdx.y; head_id < num_heads; head_id += gridDim.y) {
169.       size_t idx, half_idx;
170.       if constexpr (lse_packed) {
171.         idx = head_id * lse_seqlen + token_id + cu_seqlens_s[seq_id + 1];
172.         half_idx = head_id * second_half_lse_seqlen + token_id;
173.       } else {
174.         size_t row = static_cast<size_t>(seq_id) * num_heads + head_id;
175.         int col = token_id - cu_seqlens_s[seq_id];
176.         int seq_len = cu_seqlens_s[seq_id + 1] - cu_seqlens_s[seq_id];
177. 
178.         idx = row * lse_seqlen + col + seq_len;
179.         half_idx = row * second_half_lse_seqlen + col;
180.       }
181. 
182.       Functor::run(lse, half_lse, idx, half_idx);
183.     }
184.   }
185. }
