190. 
191. template <typename dtype, int only_second_half, int tile_size, bool lse_packed>
192. __global__ void thd_out_correction_kernel(dtype *out, dtype *out_per_step, float *lse,
193.                                           float *lse_per_step, int *cu_seqlens, int batch,
