240. constexpr size_t CHUNKS_PER_BLOCK = 128;
241. constexpr size_t THREADS_PER_BLOCK = FP8_THREADS_PER_CHUNK;
242. constexpr size_t CHUNK_SIZE = THREADS_PER_BLOCK;
243. constexpr size_t ELEMS_PER_BLOCK = CHUNKS_PER_BLOCK * CHUNK_SIZE;
244. constexpr size_t CHUNKS_PER_ITERATION = 32;
245. constexpr size_t SHMEM_DIM = CHUNKS_PER_ITERATION * CHUNK_SIZE;
246. constexpr size_t ITERATIONS = CHUNKS_PER_BLOCK / CHUNKS_PER_ITERATION;
247. constexpr size_t SHMEM_BUFFERS = 2;
248. static_assert(CHUNKS_PER_BLOCK % CHUNKS_PER_ITERATION == 0);
249. 
250. template <bool IS_ACT, typename ParamOP, float (*OP)(float, const ParamOP &), typename IType,
251.           typename OType>
252. __global__ void __launch_bounds__(THREADS_PER_BLOCK)
253.     cast_fp8_1D_kernel(const IType *input_ptr, OType *output_ptr, float *const amax_ptr,
254.                        float *const scale_inv_ptr, const float *const scale_ptr, const size_t N) {
255. #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
256. 
257.   const size_t block_offset = blockIdx.x * ELEMS_PER_BLOCK;
258.   const IType *input = input_ptr + block_offset;
259.   OType *output = output_ptr + block_offset;
260. 
261.   float amax = 0;
262.   const float scale = (scale_ptr != nullptr) ? *scale_ptr : 1;
263. 
264.   // The destination shared memory buffer of a bulk tensor operation should be 128-byte aligned
265.   __shared__ alignas(TMA_SHMEM_ALIGNMENT) IType in_sh[SHMEM_BUFFERS][SHMEM_DIM];
266.   __shared__ alignas(TMA_SHMEM_ALIGNMENT) OType out_sh[SHMEM_BUFFERS][SHMEM_DIM];
267. 
268.   constexpr size_t transaction_size_IN = sizeof(in_sh) / SHMEM_BUFFERS;
269.   constexpr size_t transaction_size_OUT = sizeof(out_sh) / SHMEM_BUFFERS;
270. 
271.   const bool is_master_thread = (threadIdx.x == 0);
272. 
273. // Initialize shared memory barrier with the number of threads participating in the barrier.
274. #pragma nv_diag_suppress static_var_with_dynamic_init
275.   __shared__ alignas(8) uint64_t mbar[ITERATIONS];
276. 
277.   initialize_barriers<ITERATIONS, THREADS_PER_BLOCK>(mbar, is_master_thread);
278. 
279.   int parity = 0;
280. 
281.   copy_1d_to_shared(&(in_sh[0]), input, transaction_size_IN, &(mbar[0]), is_master_thread);
282. 
283. #pragma unroll
284.   for (int iter = 0; iter < ITERATIONS; ++iter) {
285.     const size_t buff = iter % SHMEM_BUFFERS;
286.     const size_t it_offset = iter * SHMEM_DIM;
287. 
288.     const size_t next_iter = iter + 1;
289.     const size_t next_buff = next_iter % SHMEM_BUFFERS;
290.     const size_t next_iter_offset = next_iter * SHMEM_DIM;
291. 
292.     if (next_iter < ITERATIONS) {
293.       copy_1d_to_shared(&(in_sh[next_buff]), input + next_iter_offset, transaction_size_IN,
294.                         &(mbar[next_iter]), is_master_thread);
295.     }
296. 
297.     ptx::fence_proxy_async_shared_cta();
298. 
299.     // Wait for the data to have arrived
300.     ptx::mbarrier_wait_parity(&mbar[iter], parity);

