139.     flagptr[physgpu] = reduce_id;
140.     volatile int *flag = (volatile int *)&myptr[targetgpu];
141.     clock_t s = clock64();
142.     while (CHECK_IDS(*flag, reduce_id)) {
143.       if (CHECK_TIMEOUT(s, ub_timeout)) {
144.         UB_PRINT("[%d] Allreduce Gather: SM %d [%d]: expecting %d got %d", myrank, blockIdx.x,
145.                  threadIdx.x, reduce_id, *flag);
146.         break;
147.       }
148.     }
149.   }
150.   if (threadIdx.x == 0 && blockIdx.x == 0) *reduceidptr = reduce_id;
151. }  // fp16 inplace reduce kernel (Volta,Hopper)
152. 
153. template <int RANKS>
154. __global__ void __launch_bounds__(MAX_THREADS)
155.     userbuffers_fp16_sum_inplace_gpu_rr(const int op, const int flagoffset, const int firstrank,
156.                                         const int myrank, const int gpustep, const int lineoffset,
157.                                         const int numlines, void **commbuff, const int handleridx,
158.                                         const uint64_t ub_timeout) {
159.   __shared__ int4 *userptr[RANKS];
160.   int *flagptr, physgpu, targetgpu, *myptr;
161.   int *reduceidptr, reduce_id;
162.   if (threadIdx.x < RANKS) {
163.     physgpu = myrank * gpustep + firstrank;
164.     targetgpu = threadIdx.x * gpustep + firstrank;
165.     const int blockflagoffset = NVTE_MAX_NVLINK * 2 * blockIdx.x;
166.     myptr = (reinterpret_cast<int *>(commbuff[physgpu])) + flagoffset;
167.     reduceidptr = myptr - NVTE_MAX_OPS;  // +op;
168.     reduce_id = (*reduceidptr) + 1;
169.     flagptr = (reinterpret_cast<int *>(commbuff[targetgpu])) + flagoffset + blockflagoffset;
170.     myptr += blockflagoffset;
171. 
172.     flagptr[physgpu] = reduce_id;
173.     volatile int *flag = (volatile int *)&(myptr[targetgpu]);
174.     userptr[threadIdx.x] = reinterpret_cast<int4 *>(commbuff[targetgpu + handleridx]);
175.     clock_t s = clock64();
176.     while (CHECK_IDS(*flag, reduce_id)) {
177.       if (CHECK_TIMEOUT(s, ub_timeout)) {
178.         UB_PRINT("[%d ]Allreduce reduce-scatter:SM %d [%d]: expecting %d got %d", myrank,
179.                  blockIdx.x, threadIdx.x, reduce_id, *flag);
180.         break;
181.       }
182.     }
183.     reduce_id++;
184.   }
185.   __syncthreads();
186. 
187.   int warp = blockIdx.x + (threadIdx.x >> 5);
188.   int dest[RANKS];
189. #pragma unroll
190.   for (int i = 0; i < RANKS; i++) dest[i] = (i + myrank + warp) & (RANKS - 1);
191. 
192.   __syncthreads();
193.   for (int line = threadIdx.x + blockDim.x * (myrank + RANKS * blockIdx.x); line < numlines;
194.        line += blockDim.x * gridDim.x * RANKS) {
195.     int4 val[RANKS];
196. 
197. #pragma unroll
198.     for (int i = 0; i < RANKS; i++) {
199.       val[i] = userptr[dest[i]][lineoffset + line];
200.     }

200.   __syncthreads();
201. 
202.   int tile_id = (blockIdx.x * blockDim.x + threadIdx.x) / tile_size;
203.   int lane_id = threadIdx.x % tile_size;
204.   int num_tiles = (blockDim.x * gridDim.x) / tile_size;
205.   int num_total_tokens = cu_seqlens_s[batch];
206.   int num_loops_per_head = dim_per_head * sizeof(dtype) / sizeof(float4);
207. 
208.   for (int token_id = tile_id; token_id < num_total_tokens; token_id += num_tiles) {
209.     int seq_id = binary_search(token_id, cu_seqlens_s, batch + 1);
210.     for (int head_id = blockIdx.y; head_id < num_heads; head_id += gridDim.y) {
211.       size_t idx, idx_per_step;
212. 
213.       if constexpr (lse_packed) {
214.         idx = head_id * lse_seqlen + token_id + cu_seqlens_s[seq_id + 1] * only_second_half;
215.         idx_per_step = head_id * lse_per_step_seqlen + token_id;
216.       } else {
217.         size_t row = static_cast<size_t>(seq_id) * num_heads + head_id;
218.         int col = token_id - cu_seqlens_s[seq_id];
219.         int seq_len = cu_seqlens_s[seq_id + 1] - cu_seqlens_s[seq_id];
220.         idx = row * lse_seqlen + col + seq_len * only_second_half;
221.         idx_per_step = row * lse_per_step_seqlen + col;
222.       }
223.       float lse_corrected_exp = expf(lse_per_step[idx_per_step] - lse[idx]);
224. 
225.       idx = token_id + cu_seqlens_s[seq_id + 1] * only_second_half;
226.       idx = (idx * num_heads + head_id) * dim_per_head;
227.       idx_per_step = (static_cast<size_t>(token_id) * num_heads + head_id) * dim_per_head;
228.       dtype *cur_out = out + idx;
229.       dtype *cur_out_per_step = out_per_step + idx_per_step;
230. 
231.       for (int j = lane_id; j < num_loops_per_head; j += tile_size) {
232.         float4 data_per_step = reinterpret_cast<float4 *>(cur_out_per_step)[j];
233.         float4 data = reinterpret_cast<float4 *>(cur_out)[j];
234.         dtype *p_per_step = reinterpret_cast<dtype *>(&data_per_step);
235.         dtype *p = reinterpret_cast<dtype *>(&data);
236.         for (int k = 0; k < sizeof(float4) / sizeof(dtype); k++) {
237.           p[k] = p[k] +
238.                  (p_per_step[k] == static_cast<dtype>(0.f)
239.                       ? static_cast<dtype>(0.f)
240.                       : static_cast<dtype>(static_cast<float>(p_per_step[k]) * lse_corrected_exp));
241.         }
242.         reinterpret_cast<float4 *>(cur_out)[j] = data;
243.       }
244.     }
245.   }
246. }
