248. /***************************************************************************************************
249.  * Support THD format for Context Parallel: Gradients correction in backward
250.  **************************************************************************************************/
251. 
252. template <typename dtype, typename Functor_0, typename Functor_1, int functor_idx, int group_size>
253. __global__ void thd_grad_correction_kernel(dtype *grad, dtype *grad_per_step, int *cu_seqlens,
254.                                            int batch, int hidden_size, int dim_size_of_token) {
255.   extern __shared__ int cu_seqlens_s[];
256.   for (int i = threadIdx.x; i <= batch; i += blockDim.x) {
257.     if constexpr (functor_idx < 2) {
258.       cu_seqlens_s[i] = cu_seqlens[i] / 2;
259.     } else {
260.       cu_seqlens_s[i] = cu_seqlens[i];
261.     }
262.   }
263.   __syncthreads();
264. 
265.   int group_id = (blockIdx.x * blockDim.x + threadIdx.x) / group_size;
266.   int lane_id = threadIdx.x % group_size;
267.   int num_groups = (blockDim.x * gridDim.x) / group_size;
268.   int num_total_tokens = cu_seqlens_s[batch];
269.   int num_inner_loops = hidden_size * sizeof(dtype) / sizeof(float4);
270. 
271.   size_t offset = static_cast<size_t>(dim_size_of_token) * hidden_size;
272.   if constexpr (functor_idx < 2) {
273.     grad_per_step = grad_per_step + offset / 2 * blockIdx.y;
274.   } else {
275.     grad_per_step = grad_per_step + offset * blockIdx.y;
276.   }
277.   grad = grad + offset * blockIdx.y;
278. 
279.   for (int token_id = group_id; token_id < num_total_tokens; token_id += num_groups) {
280.     int seq_id = binary_search(token_id, cu_seqlens_s, batch + 1);
281. 
282.     int token_offset;
283.     bool is_first_half;
284.     if constexpr (functor_idx < 2) {
285.       token_offset = cu_seqlens_s[seq_id + functor_idx];
286.       is_first_half = (functor_idx == 0);
287.     } else {
288.       token_offset = 0;
289.       int len = cu_seqlens_s[seq_id + 1] - cu_seqlens_s[seq_id];
290.       is_first_half = (token_id - cu_seqlens_s[seq_id]) < (len / 2);
291.     }
292. 
293.     dtype *token = &grad[(token_id + token_offset) * static_cast<size_t>(hidden_size)];
294.     dtype *token_per_step = &grad_per_step[token_id * static_cast<size_t>(hidden_size)];
295.     for (int idx = lane_id; idx < num_inner_loops; idx += group_size) {
296.       if (is_first_half) {
297.         Functor_0::run(token, token_per_step, idx);
298.       } else {
299.         Functor_1::run(token, token_per_step, idx);
300.       }
301.     }
302.   }
303. }
