305. /***************************************************************************************************
306.  * Support THD format for Context Parallel: Read the half of a THD tensor
307.  **************************************************************************************************/
308. 
309. void thd_read_half_tensor(const Tensor &tensor, const Tensor &cu_seqlens, Tensor &half,
310.                           int half_idx, cudaStream_t stream) {
311.   using namespace transformer_engine;
312.   NVTE_CHECK(tensor.dim() == 3 || tensor.dim() == 4);
313.   NVTE_CHECK(cu_seqlens.dtype() == DType::kInt32);
314. 
315.   auto cu_seqlens_shape = cu_seqlens.shape();
316.   auto tensor_shape = tensor.shape();
317. 
318.   NVTE_CHECK(cu_seqlens.dim() == 1);
319.   NVTE_CHECK(cu_seqlens_shape[0] >= 2);
320. 
321.   // Shapes of q and dq are [t, h, d], so the dimension of "t" is 0
322.   // Shapes of kv and dkv are [2, t, h, d], so the dimension of "t" is 1
323.   int seq_dim = tensor.dim() == 3 ? 0 : 1;
324. 
325.   int batch = cu_seqlens_shape[0] - 1;
326.   int num_heads = tensor_shape[seq_dim + 1];
327.   int dim_per_head = tensor_shape[seq_dim + 2];
328.   int hidden_size_in_bytes = (num_heads * dim_per_head * typeToNumBits(tensor.dtype())) / 8;
329. 
330.   // For 128-bits load/store
331.   NVTE_CHECK(hidden_size_in_bytes % 16 == 0);
332. 
333.   // Launch Kernel
334.   constexpr unsigned int block = 256;
335.   unsigned int grid_x = (tensor_shape[seq_dim] / 2 * 32 + block - 1) / block;
336.   unsigned int grid_y = 1;
337.   for (int i = 0; i < seq_dim; i++) {
338.     grid_y *= tensor_shape[i];
339.   }
340.   dim3 grid = {grid_x, grid_y};
341.   thd_read_half_tensor_kernel<<<grid, block, sizeof(int) * (batch + 1), stream>>>(
342.       half.data.dptr, tensor.data.dptr, reinterpret_cast<int *>(cu_seqlens.data.dptr), batch,
343.       hidden_size_in_bytes, half_idx, tensor_shape[seq_dim]);
344.   NVTE_CHECK_CUDA(cudaGetLastError());
345. }
