15. template <typename dtype>
16. __global__ void reindex_kv_cache_kernel(dtype *k_cache, dtype *v_cache, int *batch_indices,
17.                                         int *cu_new_lens, int *cu_cached_lens, int h_kv, int d_k,
18.                                         int d_v, int b, int max_seq_len) {
19.   // k_cache, v_cache: bshd
20.   // batch_indices: [b]; cu_new_lens, cu_cached_lens: [b + 1]
21.   int actual_b = b;
22.   for (int i = 0; i < b - 1; i++) {
23.     if (batch_indices[i + 1] < batch_indices[i]) {
24.       actual_b = i + 1;
25.     }
26.   }
27.   bool flag = (batch_indices[0] != 0);
28.   for (int batch_idx = 0; batch_idx < actual_b; batch_idx++) {
29.     if (flag || ((batch_indices[batch_idx] - batch_indices[0]) != batch_idx)) {
30.       int num_tokens = (cu_cached_lens[batch_idx + 1] - cu_cached_lens[batch_idx]) -
31.                        (cu_new_lens[batch_idx + 1] - cu_new_lens[batch_idx]);
32.       int num_elts_k = h_kv * d_k;
33.       int num_elts_v = h_kv * d_v;
34.       int num_elts = max(num_elts_k, num_elts_v);
35.       for (int token_idx = blockIdx.x; token_idx < num_tokens; token_idx += gridDim.x) {
36.         int src_offset = batch_indices[batch_idx] * max_seq_len + token_idx;
37.         int des_offset = batch_idx * max_seq_len + token_idx;
38.         dtype *k_cache_src_offset = k_cache + src_offset * num_elts_k;
39.         dtype *k_cache_des_offset = k_cache + des_offset * num_elts_k;
40.         dtype *v_cache_src_offset = v_cache + src_offset * num_elts_v;
41.         dtype *v_cache_des_offset = v_cache + des_offset * num_elts_v;
42.         for (int i = threadIdx.x; i < num_elts; i += blockDim.x) {
43.           if (i < num_elts_k) {
44.             *(k_cache_des_offset + i) = *(k_cache_src_offset + i);
45.           }
46.           if (i < num_elts_v) {
47.             *(v_cache_des_offset + i) = *(v_cache_src_offset + i);
48.           }
49.         }
50.       }
51.     }
52.   }
53. }
