55. template <typename dtype>
56. __global__ void copy_to_kv_cache_kernel(dtype *new_k, dtype *new_v, dtype *k_cache, dtype *v_cache,
57.                                         int *page_table, int *cu_new_lens, int *cu_cached_lens,
58.                                         NVTE_QKV_Format qkv_format, int h_kv, int d_k, int d_v,
59.                                         int b, int max_ctx_len, int max_seq_len,
60.                                         int max_pages_per_seq, bool is_non_paged) {
61.   // new_k, new_v: qkv_format; k_cache, v_cache: bshd
62.   // cu_new_lens, cu_cached_lens: [b + 1]
63.   // page_table: [b, max_pages_per_seq]
64.   int page_size = max_seq_len / max_pages_per_seq;
65.   if (qkv_format == NVTE_QKV_Format::NVTE_BSHD) {
66.     for (int batch_idx = blockIdx.x; batch_idx < b; batch_idx += gridDim.x) {
67.       int *page_list = is_non_paged ? nullptr : page_table + batch_idx * max_pages_per_seq;
68.       int cached_len = cu_cached_lens[batch_idx + 1] - cu_cached_lens[batch_idx];
69.       int new_len = cu_new_lens[batch_idx + 1] - cu_new_lens[batch_idx];
70.       int num_elts_k = h_kv * d_k;
71.       int num_elts_v = h_kv * d_v;
72.       int hd = h_kv * max(d_k, d_v);
73.       for (int i = blockIdx.y; i < new_len; i += gridDim.y) {
74.         int page_idx = is_non_paged ? batch_idx : page_list[(cached_len - new_len + i) / page_size];
75.         dtype *new_token_id_k = new_k + (batch_idx * max_ctx_len + i) * num_elts_k;
76.         dtype *new_token_id_v = new_v + (batch_idx * max_ctx_len + i) * num_elts_v;
77.         dtype *token_id_k =
78.             k_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_k;
79.         dtype *token_id_v =
80.             v_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_v;
81.         for (int j = threadIdx.x; j < hd; j += blockDim.x) {
82.           if (j < num_elts_k) {
83.             *(token_id_k + j) = *(new_token_id_k + j);
84.           }
85.           if (j < num_elts_v) {
86.             *(token_id_v + j) = *(new_token_id_v + j);
87.           }
88.         }
89.       }
90.     }
91.   } else if (qkv_format == NVTE_QKV_Format::NVTE_SBHD) {
92.     for (int batch_idx = blockIdx.x; batch_idx < b; batch_idx += gridDim.x) {
93.       int *page_list = is_non_paged ? nullptr : page_table + batch_idx * max_pages_per_seq;
94.       int cached_len = cu_cached_lens[batch_idx + 1] - cu_cached_lens[batch_idx];
95.       int new_len = cu_new_lens[batch_idx + 1] - cu_new_lens[batch_idx];
96.       int num_elts_k = h_kv * d_k;
97.       int num_elts_v = h_kv * d_v;
98.       int hd = h_kv * max(d_k, d_v);
99.       for (int i = blockIdx.y; i < new_len; i += gridDim.y) {
100.         int page_idx = is_non_paged ? batch_idx : page_list[(cached_len - new_len + i) / page_size];
101.         dtype *new_token_id_k = new_k + (i * b + batch_idx) * num_elts_k;
102.         dtype *new_token_id_v = new_v + (i * b + batch_idx) * num_elts_v;
103.         dtype *token_id_k =
104.             k_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_k;
105.         dtype *token_id_v =
106.             v_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_v;
107.         for (int j = threadIdx.x; j < hd; j += blockDim.x) {
108.           if (j < num_elts_k) {
109.             *(token_id_k + j) = *(new_token_id_k + j);
110.           }
111.           if (j < num_elts_v) {
112.             *(token_id_v + j) = *(new_token_id_v + j);
113.           }
114.         }
115.       }
116.     }
117.   } else if (qkv_format == NVTE_QKV_Format::NVTE_THD) {
118.     for (int batch_idx = blockIdx.x; batch_idx < b; batch_idx += gridDim.x) {
119.       int *page_list = is_non_paged ? nullptr : page_table + batch_idx * max_pages_per_seq;
120.       int cached_len = cu_cached_lens[batch_idx + 1] - cu_cached_lens[batch_idx];
121.       int new_len = cu_new_lens[batch_idx + 1] - cu_new_lens[batch_idx];
122.       int num_elts_k = h_kv * d_k;
123.       int num_elts_v = h_kv * d_v;
124.       int hd = h_kv * max(d_k, d_v);
125.       for (int i = blockIdx.y; i < new_len; i += gridDim.y) {
126.         int page_idx = is_non_paged ? batch_idx : page_list[(cached_len - new_len + i) / page_size];
127.         dtype *new_token_id_k = new_k + (cu_new_lens[batch_idx] + i) * num_elts_k;
128.         dtype *new_token_id_v = new_v + (cu_new_lens[batch_idx] + i) * num_elts_v;
129.         dtype *token_id_k =
130.             k_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_k;
131.         dtype *token_id_v =
132.             v_cache + (page_idx * page_size + (cached_len - new_len + i) % page_size) * num_elts_v;
133.         for (int j = threadIdx.x; j < hd; j += blockDim.x) {
134.           if (j < num_elts_k) {
135.             *(token_id_k + j) = *(new_token_id_k + j);
136.           }
137.           if (j < num_elts_v) {
138.             *(token_id_v + j) = *(new_token_id_v + j);
139.           }
140.         }
141.       }
142.     }
143.   }
144. }
