146. template <typename dtype>
147. void copy_to_kv_cache_launcher(Tensor new_k, Tensor new_v, Tensor k_cache, Tensor v_cache,
148.                                Tensor page_table, Tensor cu_new_lens, Tensor cu_cached_lens,
149.                                NVTE_QKV_Format qkv_format, int h_kv, int d_k, int d_v, int b,
150.                                int max_ctx_len, int max_seq_len, int max_pages_per_seq,
151.                                bool is_non_paged, cudaStream_t stream) {
152.   if (new_k.has_data() && new_v.has_data() && k_cache.has_data() && v_cache.has_data()) {
153.     if (is_non_paged) {
154.       reindex_kv_cache_kernel<<<max_seq_len, block_size, 0, stream>>>(
155.           reinterpret_cast<dtype *>(k_cache.data.dptr),
156.           reinterpret_cast<dtype *>(v_cache.data.dptr),
157.           reinterpret_cast<int *>(page_table.data.dptr),
158.           reinterpret_cast<int *>(cu_new_lens.data.dptr),
159.           reinterpret_cast<int *>(cu_cached_lens.data.dptr), h_kv, d_k, d_v, b, max_seq_len);
160.       NVTE_CHECK_CUDA(cudaGetLastError());
161.     }
162.     dim3 grid_size(b, max_ctx_len);
163.     copy_to_kv_cache_kernel<<<grid_size, block_size, 0, stream>>>(
164.         reinterpret_cast<dtype *>(new_k.data.dptr), reinterpret_cast<dtype *>(new_v.data.dptr),
165.         reinterpret_cast<dtype *>(k_cache.data.dptr), reinterpret_cast<dtype *>(v_cache.data.dptr),
166.         reinterpret_cast<int *>(page_table.data.dptr),
167.         reinterpret_cast<int *>(cu_new_lens.data.dptr),
168.         reinterpret_cast<int *>(cu_cached_lens.data.dptr), qkv_format, h_kv, d_k, d_v, b,
169.         max_ctx_len, max_seq_len, max_pages_per_seq, is_non_paged);
170.     NVTE_CHECK_CUDA(cudaGetLastError());
171.   }
172. }
