174. void copy_to_kv_cache(Tensor new_k, Tensor new_v, Tensor k_cache, Tensor v_cache, Tensor page_table,
175.                       Tensor cu_new_lens, Tensor cu_cached_lens, NVTE_QKV_Format qkv_format, int b,
176.                       int max_ctx_len, int max_seq_len, int max_pages_per_seq, bool is_non_paged,
177.                       cudaStream_t stream) {
178.   int h_kv = new_k.shape()[new_k.dim() - 2];
179.   int d_k = new_k.shape()[new_k.dim() - 1];
180.   int d_v = new_v.shape()[new_v.dim() - 1];
181.   NVTE_CHECK(k_cache.dtype() == v_cache.dtype() && new_k.dtype() == new_v.dtype() &&
182.                  new_k.dtype() == k_cache.dtype(),
183.              "new_k, new_v, k_cache and v_cache must be of the same data type.");
184.   NVTE_CHECK(qkv_format == NVTE_QKV_Format::NVTE_BSHD || qkv_format == NVTE_QKV_Format::NVTE_SBHD ||
185.                  qkv_format == NVTE_QKV_Format::NVTE_THD,
186.              "qkv_format must be {BSHD, SBHD, THD}.");
187. 
188.   TRANSFORMER_ENGINE_TYPE_SWITCH_FLOAT(
189.       k_cache.dtype(), dtype,
