78. // Compute the global encode scale factor for a given global amax
79. __device__ __forceinline__ float compute_global_encode_scaling_factor_FP4(const float global_amax) {
80.   using namespace detail;
81.   constexpr float fp8_max = TypeExtrema<fp8e4m3>::max;  // 448.0f;
82.   constexpr float fp4_max = TypeExtrema<fp4e2m1>::max;  // 6.0f;
83.   float global_encode_scale = fp8_max * fp4_max / global_amax;
84.   // If scale is infinity, return max value of float32
85.   global_encode_scale = fminf(global_encode_scale, TypeExtrema<float>::max);
86.   // If global amax is 0 or infinity, return 1
87.   if (global_amax == 0.0f || global_encode_scale == 0.0f) {
88.     return 1.0f;
89.   }
90.   return global_encode_scale;
91. }
