80. template <typename IType>
81. __global__ void __launch_bounds__(kThreadsPerBlock)
82.     nvfp4_2d_compute_partial_amax_kernel(const IType *input, float *amax_ptr,
83.                                          const size_t amax_stride_h, const size_t amax_stride_w,
84.                                          const size_t h, const size_t w, const size_t start_offset,
85.                                          const size_t len) {
86.   constexpr int kThreadsPerWarp = 32;
87.   constexpr int kNumWarps = kThreadsPerBlock / kThreadsPerWarp;
88.   static_assert(kTileDim * kTileDim == kThreadsPerBlock);
89. 
90.   const size_t tile_col = blockIdx.x;
91.   const size_t tile_row = blockIdx.y;
92.   const size_t end_offset = start_offset + len;
93.   const IType *input_minus_offset = input - start_offset;
94. 
95.   __shared__ float smem[kNumWarps];
96.   float amax = 0.0f;
97. 
98.   size_t r = tile_row * kTileDim + threadIdx.x / kTileDim;
99.   size_t c = tile_col * kTileDim + threadIdx.x % kTileDim;
100.   size_t idx = r * w + c;
101.   if (r < h && c < w && idx >= start_offset && idx < end_offset) {
102.     amax = fabs(static_cast<float>(input_minus_offset[idx]));
103.   }
104. 
105.   for (int delta = kThreadsPerWarp / 2; delta > 0; delta /= 2) {
106.     float other_amax = __shfl_down_sync(0xFFFFFFFF, amax, delta);
107.     __builtin_assume(amax >= 0);
108.     __builtin_assume(other_amax >= 0);
109.     amax = fmaxf(amax, other_amax);
110.   }
111. 
112.   if (threadIdx.x % kThreadsPerWarp == 0) {
113.     smem[threadIdx.x / kThreadsPerWarp] = amax;
114.   }
115. 
116.   __syncthreads();
117. 
118.   if (threadIdx.x == 0) {
119.     for (int i = 0; i < kNumWarps; ++i) {
120.       float other_amax = smem[i];
121.       __builtin_assume(amax >= 0);
122.       __builtin_assume(other_amax >= 0);
123.       amax = fmaxf(amax, other_amax);
124.     }
125.     amax_ptr[tile_row * amax_stride_h + tile_col * amax_stride_w] = amax;
126.   }
127. }
