129. template <typename IType, bool kWidthAligned>
130. __global__ void __launch_bounds__(kThreadsPerBlock)
131.     nvfp4_2d_partial_cast_kernel(const IType *input, uint8_t *output, const float *decode_scale_ptr,
132.                                  const size_t scale_stride_h, const size_t scale_stride_w,
133.                                  const float *global_scale_ptr, const size_t h, const size_t w,
134.                                  const size_t start_offset, const size_t len) {
135.   constexpr int kNumOutputElemsPerBank = 4;
136.   constexpr int kThreadsPerWarp = 32;
137.   constexpr int kLoopsPerRow = (kTileDim + kThreadsPerWarp - 1) / kThreadsPerWarp;
138.   constexpr int kNumWarps = kThreadsPerBlock / kThreadsPerWarp;
139.   constexpr int kRowsPerWarp = (kTileDim + kNumWarps - 1) / kNumWarps;
140. 
141.   __shared__ float smem[kTileDim][kTileDim + kNumOutputElemsPerBank];
142. 
143.   const int tile_w = blockIdx.x;
144.   const int tile_h = blockIdx.y;
145.   const size_t shard_end = start_offset + len;
146.   const IType *input_minus_offset = input - start_offset;
147. 
148.   float global_encode_scale = global_scale_ptr[0];
149.   if (global_encode_scale <= 0.f) {
150.     global_encode_scale = 1.f;

150.     global_encode_scale = 1.f;
151.   }
152.   const float global_decode_scale = 1.0f / global_encode_scale;
153. 
154.   float tile_decode_scale = decode_scale_ptr[tile_h * scale_stride_h + tile_w * scale_stride_w];
155.   tile_decode_scale = static_cast<float>(static_cast<fp8e4m3>(tile_decode_scale));
156.   constexpr float kFp32Max = 3.402823466e+38F;
157.   float tile_encode_val =
158.       (tile_decode_scale > 0.f) ? 1.0f / (tile_decode_scale * global_decode_scale) : kFp32Max;
159.   tile_encode_val = fminf(tile_encode_val, kFp32Max);
160.   const float2 scale_vec = make_float2(tile_encode_val, tile_encode_val);
161. 
162.   bool skip_store = true;
163.   for (int i = 0; i < kRowsPerWarp; ++i) {
164.     for (int j = 0; j < kLoopsPerRow; ++j) {
165.       const int h_in_smem = threadIdx.x / kThreadsPerWarp * kRowsPerWarp + i;
166.       const int w_in_smem = threadIdx.x % kThreadsPerWarp + kThreadsPerWarp * j;
167.       if (h_in_smem >= kTileDim || w_in_smem >= kTileDim) {
168.         continue;
169.       }
170.       const int h_in_input = tile_h * kTileDim + h_in_smem;
171.       const int w_in_input = tile_w * kTileDim + w_in_smem;
172.       const size_t idx_in_input = static_cast<size_t>(h_in_input) * w + w_in_input;
173.       if (h_in_input < h && w_in_input < w && idx_in_input >= start_offset &&
174.           idx_in_input < shard_end) {
175.         smem[h_in_smem][w_in_smem] = static_cast<float>(input_minus_offset[idx_in_input]);
176.         skip_store = false;
177.       }
178.     }
179.   }
180. 
181.   for (int delta = kThreadsPerWarp / 2; delta > 0; delta /= 2) {
182.     bool other = __shfl_down_sync(0xFFFFFFFF, skip_store, delta);
183.     skip_store = skip_store && other;
184.   }
185.   skip_store = __shfl_sync(0xFFFFFFFF, skip_store, 0);
186.   if (skip_store) {
187.     return;
188.   }
189. 
190.   for (int i = 0; i < kRowsPerWarp; ++i) {
191.     const int row_in_smem = threadIdx.x / kThreadsPerWarp * kRowsPerWarp + i;
192.     const int row_in_output = tile_h * kTileDim + row_in_smem;
193.     if (row_in_output >= h) {
194.       continue;
195.     }
196.     const int col_in_smem = threadIdx.x % kThreadsPerWarp * kNumOutputElemsPerBank;
197.     if (col_in_smem >= kTileDim) {
198.       continue;
199.     }
200.     const int col_in_output = tile_w * kTileDim + col_in_smem;
201. 
202.     float vals[kNumOutputElemsPerBank];
203.     bool mask[kNumOutputElemsPerBank];
204.     size_t elem_idx[kNumOutputElemsPerBank];
205.     bool any_valid = false;
206. 
207.     for (int j = 0; j < kNumOutputElemsPerBank; ++j) {
208.       const int col = col_in_output + j;
209.       const bool in_width = col < w;
210.       const size_t idx = static_cast<size_t>(row_in_output) * w + col;
211.       elem_idx[j] = idx;
212.       const bool in_shard = in_width && idx >= start_offset && idx < shard_end;
213.       mask[j] = in_shard;
214.       const bool in_tile = (col_in_smem + j) < kTileDim;
215.       const float tile_val = in_tile ? smem[row_in_smem][col_in_smem + j] : 0.0f;
216.       vals[j] = in_shard ? tile_val : 0.0f;
217.       any_valid |= in_shard;
218.     }
219. 
220.     if (!any_valid) {
221.       continue;
222.     }
223. 
224.     const float2 in01 = make_float2(vals[0], vals[1]);
225.     const float2 in23 = make_float2(vals[2], vals[3]);
226.     const auto packed =
227.         transformer_engine::ptx::mul_cvt_fp32_to_fp4_4x<false>(in01, in23, scale_vec, 0);
228.     const uint16_t packed_bits = reinterpret_cast<const uint16_t &>(packed);
229. 
230.     for (int pair = 0; pair < 2; ++pair) {
231.       const int first = pair * 2;
232.       const int second = first + 1;
233.       if (!mask[first] && !mask[second]) {
234.         continue;
235.       }
236.       const size_t ref_idx = mask[first] ? elem_idx[first] : elem_idx[second];
237.       const size_t byte_idx = (ref_idx - start_offset) >> 1;
238.       uint8_t byte = output[byte_idx];
239. 
240.       if (mask[first]) {
241.         const uint8_t nibble = static_cast<uint8_t>((packed_bits >> (4 * first)) & 0xF);
242.         if ((elem_idx[first] & 1u) == 0) {
243.           byte = static_cast<uint8_t>((byte & 0xF0u) | nibble);
244.         } else {
245.           byte = static_cast<uint8_t>((byte & 0x0Fu) | (nibble << 4));
246.         }
247.       }
248. 
249.       if (mask[second]) {
250.         const uint8_t nibble = static_cast<uint8_t>((packed_bits >> (4 * second)) & 0xF);
251.         if ((elem_idx[second] & 1u) == 0) {
252.           byte = static_cast<uint8_t>((byte & 0xF0u) | nibble);
253.         } else {
254.           byte = static_cast<uint8_t>((byte & 0x0Fu) | (nibble << 4));
255.         }
256.       }
257. 
258.       output[byte_idx] = byte;
259.     }
260.   }
261. }
