53.   size_t elements_per_load = 0;       // Elements per L1 cache load
54.   size_t elements_per_load_dact = 0;  // Elements per L1 cache load dact
55.   size_t elements_per_store_c = 0;    // Elements per L1 cache store to cast output
56.   size_t elements_per_store_t = 0;    // Elements per L1 cache store to transposed output
