64.         return;
65.       }
66.     }
67. 
68.     // Check that tiles are correctly aligned
69.     constexpr size_t cache_line_size = 128;
70.     if (load_size % itype_size != 0 || store_size % otype_size != 0 ||
71.         cache_line_size % itype_size != 0 || cache_line_size % otype_size != 0) {
72.       return;
73.     }
74.     /* row_tile_elements */
75.     const size_t tile_size_x = (load_size * THREADS_PER_WARP) / itype_size;
76.     /* col_tile_elements */
77.     const size_t tile_size_y = (store_size * THREADS_PER_WARP) / otype_size;
78.     const size_t num_tiles_x = row_length / tile_size_x;
79.     const size_t num_tiles_y = num_rows / tile_size_y;
80. 
81.     valid = (row_length % tile_size_x == 0 && num_rows % tile_size_y == 0);
82.     if (!valid) {
83.       return;
84.     }
85. 
86.     // Number of CUDA blocks
87.     num_blocks = num_tiles_x * num_tiles_y;
88. 
89.     // Parameters for performance model
90.     constexpr size_t warps_per_sm = 16;  // Rough estimate for saturated SMs
91.     active_sm_count = std::min(DIVUP(num_blocks * n_warps_per_tile, warps_per_sm), sm_count);
92.     elements_per_load = (std::min(cache_line_size, tile_size_x * itype_size) / itype_size);
93.     elements_per_load_dact = (std::min(cache_line_size, tile_size_x * itype2_size) / itype2_size);
94.     elements_per_store_c = (std::min(cache_line_size, tile_size_x * otype_size) / otype_size);
95.     elements_per_store_t = (std::min(cache_line_size, tile_size_y * otype_size) / otype_size);
96.   }
