98.   /* Compare by estimated cost */
99.   bool operator<(const KernelConfig &other) const {
100.     if (this->valid && other.valid) {
101.       // cost ~ (1/elements_per_load
102.       //         + 1/elements_per_load_dact
103.       //         + 1/elements_per_store_c
104.       //         + 1/elements_per_store_t) / active_sms
105.       // Note: Integer arithmetic ensures stable ordering
106.       const auto &l1 = this->elements_per_load;
107.       const auto &la1 = this->elements_per_load_dact;
108.       const auto &sc1 = this->elements_per_store_c;
109.       const auto &st1 = this->elements_per_store_t;
110.       const auto &p1 = this->active_sm_count;
111.       const auto &l2 = other.elements_per_load;
112.       const auto &la2 = other.elements_per_load_dact;
113.       const auto &sc2 = other.elements_per_store_c;
114.       const auto &st2 = other.elements_per_store_t;
115.       const auto &p2 = other.active_sm_count;
116.       const auto scale1 = l1 * sc1 * st1 * p1 * (is_dact ? la1 : 1);
117.       const auto scale2 = l2 * sc2 * st2 * p2 * (is_dact ? la2 : 1);
118.       const auto scale = scale1 * scale2;
119.       const auto cost1 =
120.           (scale / l1 + scale / sc1 + scale / st1 + (is_dact ? (scale / la1) : 0)) / p1;
121.       const auto cost2 =
122.           (scale / l2 + scale / sc2 + scale / st2 + (is_dact ? (scale / la2) : 0)) / p2;
123. 
124.       return cost1 < cost2;
125.     } else {
126.       return this->valid && !other.valid;
127.     }
128.   }
