int register_user_buffer_collective(void **gpubuff, size_t bytes, 
                                     communicator *comm, bool alloc) {
  // 步骤1: 检查是否已注册
  // 步骤2: 调用 cuMemCreate 分配 Unified Memory (若 alloc==true)
  CUmemGenericAllocationHandle handle;
  CU_CHECK(cuMemCreate(&handle, bytes, &prop, 0));

  // 步骤3: 在所有 GPU 上映射虚拟地址
  for (int rank = 0; rank < comm->nranks; rank++) {
    CUdeviceptr va;
    cuMemAddressReserve(&va, bytes, 0, 0);
    // 步骤4: 使用 cuMemMap 建立映射（支持 Peer Access）
    cuMemMap(va, bytes, 0, handle, 0);
    // 步骤5: IPC 注册（Allgather 同步 VA）
    comm->_allgather(&va, sizeof(CUdeviceptr), 
                     &comm->ucbase_ptr[handler], sizeof(CUdeviceptr) * nranks, 
                     comm->comm_world);
  }

  // 返回 handler ID（用于后续 userbuffers_*() 调用）
  return handler;
}
```

**关键点:**
- **Unified Memory + cuMemMap:** 绕过 PCI-E，使用 NVLink 直接访问
- **IPC Allgather:** 每个 GPU 需要知道所有其他 GPU 的虚拟地址
- **Handler ID:** 用于多个并发通信操作的复用

