void CommOverlapCore::initialize(int tp_size, int num_splits, int num_max_streams,
                                 int comm_cga_size, int gemm_priority, int comm_priority,
                                 int num_comm_sm, bool set_sm_margin, bool use_ce,
                                 bool atomic_gemm) {
  // 行1-3: 设置通信参数
  _use_ce = static_cast<int>(use_ce);  // 是否使用 Copy Engine
  _num_comm_sm = num_comm_sm;           // 通信保留的 SM 数量
  _cga_size = comm_cga_size;            // Cooperative Group Array 大小

  // 行5-9: 流优先级设置（用于控制 GEMM vs Comm 的调度）
  if (gemm_priority == 0 && comm_priority == 0) {
    // 0 表示让驱动自动分配
    transformer_engine::cuda::stream_priority_range(&_gemm_priority, &_comm_priority);
  } else {
    _gemm_priority = gemm_priority;
    _comm_priority = comm_priority;
  }

  // 行11-15: 为每个 split 创建 GEMM 流
  for (int i = 0; i < std::min(num_max_streams, num_splits); i++) {
    cudaStream_t stream;
    // cudaStreamNonBlocking 避免 Host 线程阻塞
    // _gemm_priority 确保 GEMM 优先于 Comm 发射
    NVTE_CHECK_CUDA(cudaStreamCreateWithPriority(&stream, cudaStreamNonBlocking, _gemm_priority));
    _stream_compute.push_back(std::move(stream));
  }

  // 行17-25: 计算 GEMM 可用的 SM 数量
  _num_splits = num_splits;
  _rank = _ub_comm->myrank;
  _tp_size = tp_size;
  _tp_id = _rank % _tp_size;

  int sm_count = transformer_engine::cuda::sm_count();  // 总 SM 数
  // set_sm_margin 为 true 时：math_sms = sm_count - num_comm_sm
  // 这确保通信 kernel 有 num_comm_sm 个专用 SM
  _math_sms = (set_sm_margin) ? sm_count - num_comm_sm : sm_count;
  // 减去额外的外部预留 SM（环境变量可配置）
  _math_sms -= transformer_engine::getenv<int>("NVTE_EXT_MARGIN_SM", 0);

  // 行27-33: Atomic GEMM 计数器初始化（用于 split overlap）
  _atomic_gemm = atomic_gemm;
  if (_atomic_gemm) {
    void *counter_ptr;
    size_t counter_bytes = _num_splits * 2 * sizeof(int32_t);  // 每个 split 2 个计数器
    NVTE_CHECK_CUDA(cudaMalloc(&counter_ptr, counter_bytes));
    NVTE_CHECK_CUDA(cudaMemset(counter_ptr, 0, counter_bytes));
    NVTE_CHECK_CUDA(cudaMemset(counter_ptr, 1, counter_bytes / 2));  // 一半初始化为 1
    _counter = TensorWrapper(counter_ptr, 
                             std::vector<size_t>{static_cast<size_t>(_num_splits * 2)},
                             DType::kInt32);
  }
```

**关键参数：**
- **`num_comm_sm`**: 预留给通信的 SM 数（如 32 GPU 上设 4-8）
- **`cga_size`**: 合作线程组大小，影响 kernel 内的 sync 粒度
- **`atomic_gemm`**: 启用时使用原子操作同步 GEMM 完成（vs. event-based）

