104.     compute_t rs = rsqrtf(rn * m2 + params.epsilon);
105. 
106.     if (bidn == 0 && warp_n == 0 && lane == 0) {
107.       rs_ptr[row] = rs;
108.     }
109. 
110.     Ovec z[LDGS];
111.     idx = row * Ktraits::VEC_COLS + c;
112. #pragma unroll
113.     for (int it = 0; it < LDGS; it++) {
114. #pragma unroll
115.       for (int jt = 0; jt < NUM_ELTS; jt++) {
116.         compute_t y_ij = rs * (xf[it * NUM_ELTS + jt] - mu);
117.         compute_t g_ij = gamma[it].data.elt[jt];
118.         if (params.zero_centered_gamma) {
119.           g_ij += 1;
120.         }
121.         compute_t b_ij = beta[it].data.elt[jt];
122.         compute_t temp_output = g_ij * y_ij + b_ij;
123. 
124.         if (requires_amax) {
125.           __builtin_assume(amax >= 0);
126.           if (params.fp8_out) {
127.             // For fp8_out, keep amax on pre-scale compute_t
128.             amax = fmaxf(amax, fabsf(temp_output));
129.           } else {
130.             // Otherwise compute amax on the value converted to output_t (e.g., bf16)
131.             output_t out_t_val = output_t(temp_output);
132.             amax = fmaxf(amax, fabsf(compute_t(out_t_val)));
133.           }
134.         }
135.         if (params.fp8_out) {
136.           temp_output = temp_output * scale;
137.         }
138. 
139.         z[it].data.elt[jt] = output_t(temp_output);
140.       }
141.       z[it].store_to(params.z, idx);
142.       idx += VEC_COLS_PER_LDG;
143.     }
144.   }
145. 
146.   // Reduce amax over block
147.   if (requires_amax) {
148.     amax = reduce_max<WARPS_M * WARPS_N>(amax, warp);
149.     if (threadIdx.x == 0) {
