53. /* Generate dropout mask with 16 bits.
54.  *
55.  * 1 corresponds to keep and 0 to drop.
56.  *
57.  * Consumes 4 values from cuRAND Philox generator.
58.  */
59. __device__ __forceinline__ uint16_t make_16bit_mask(uint64_t chunk_idx, uint64_t rng_seed,
60.                                                     uint64_t rng_offset,
61.                                                     uint32_t bytewise_drop_prob) {
62.   // Generate random bits
63.   curandStatePhilox4_32_10_t state;
64.   curand_init(rng_seed, chunk_idx, rng_offset, &state);
65.   const uint4 rand_bits = curand4(&state);
66. 
67.   // Compute mask
68.   // Note: bytewise_less_than fills MSBs (bits 7, 15, 23, 31). By
69.   // shifting 2 bits after every call, every other bit will be filled.
70.   uint32_t result = bytewise_less_than(rand_bits.x, bytewise_drop_prob);
71.   result = (result >> 2) | bytewise_less_than(rand_bits.y, bytewise_drop_prob);
72.   result = (result >> 2) | bytewise_less_than(rand_bits.z, bytewise_drop_prob);
73.   result = (result >> 2) | bytewise_less_than(rand_bits.w, bytewise_drop_prob);
74. 
75.   // Consolidate mask in lowest 16 bits
76.   result |= result >> 17;
77. 
78.   // Flip bits so 0 corresponds to drop
79.   result = ~result;
80. 
81.   return result;
82. }
