18. __device__ void fused_rope_block_forward(const scalar_t *src, const float *freqs, scalar_t *dst,
19.                                          const bool interleaved, const int s_id,
20.                                          const int offset_block, const int offset_block_dst,
21.                                          const int h, const int d, const int d2, const int stride_h,
22.                                          const int stride_d, const int o_stride_h,
23.                                          const int o_stride_d) {
24.   extern __shared__ float shared_mem_cos_sin[];
25.   float *shared_mem_cos = shared_mem_cos_sin;
26.   float *shared_mem_sin = shared_mem_cos_sin + d2;
27.   int tid = threadIdx.x * blockDim.y + threadIdx.y;
28.   for (int i = tid; i < d2; i += blockDim.x * blockDim.y) {
29.     sincosf(freqs[s_id * d2 + i], &shared_mem_sin[i], &shared_mem_cos[i]);
30.   }
31.   __syncthreads();
32. 
33. #pragma unroll
34.   for (int h_id = threadIdx.y; h_id < h; h_id += blockDim.y) {
35. #pragma unroll
36.     for (int d_id = threadIdx.x; d_id < d2; d_id += blockDim.x) {
37.       float v_cos = shared_mem_cos[d_id];
38.       float v_sin = shared_mem_sin[d_id];
39.       int offset_src = offset_block + h_id * stride_h + d_id * stride_d;
40.       int offset_dst = offset_block_dst + h_id * o_stride_h + d_id * o_stride_d;
41.       float v_src = src[offset_src];
42.       float v_src_rotate;
43.       if (!interleaved) {
44.         v_src_rotate = (d_id + d2 / 2 < d2)
45.                            ? -static_cast<float>(src[offset_src + (d2 / 2) * stride_d])
46.                            : static_cast<float>(src[offset_src + (d2 / 2 - d2) * stride_d]);
47.       } else {
48.         v_src_rotate = (d_id % 2 == 0)
49.                            // d_id + 1
50.                            ? -static_cast<float>(src[offset_src + stride_d])
51.                            // d_id - 1
52.                            : static_cast<float>(src[offset_src - stride_d]);
53.       }
54.       dst[offset_dst] = v_src * v_cos + v_src_rotate * v_sin;
55.     }
56.   }
57. 
58.   // copy the rest
59.   if (d > d2) {
60. #pragma unroll
61.     for (int d_id = d2 + threadIdx.x; d_id < d; d_id += blockDim.x) {
62. #pragma unroll
63.       for (int h_id = threadIdx.y; h_id < h; h_id += blockDim.y) {
64.         int offset_src = offset_block + h_id * stride_h + d_id * stride_d;
65.         int offset_dst = offset_block_dst + h_id * o_stride_h + d_id * o_stride_d;
66.         dst[offset_dst] = src[offset_src];
67.       }
68.     }
69.   }
70. }
