47.   void alignWorkspace(size_t alignment = 16) {
48.     workspace_bytes = DIVUP(workspace_bytes, alignment) * alignment;
49.     barrier_bytes = DIVUP(barrier_bytes, alignment) * alignment;
50.     dgamma_part_bytes = DIVUP(dgamma_part_bytes, alignment) * alignment;
51.   }
52. };
