26.      * - Each warp is responsible for one token, and has own shared memory buffer.
27.      *   Then __syncwarp() is used instead of __syncthreads()
28.      */
29.   // Used variables/addresses init
30.   int num_token_per_block = blockDim.x / kThreadsPerWarp;
31.   int warp_id = threadIdx.x / kThreadsPerWarp;
32.   int lane_id = threadIdx.x % kThreadsPerWarp;
33.   extern __shared__ float shmem[];
34.   CompType *scores_buf = reinterpret_cast<CompType *>(shmem);
35.   CompType *topk_scores_buf = scores_buf + num_experts * num_token_per_block;
36.   CompType *group_scores_buf = nullptr, *masked_scores_buf = nullptr;
37.   int *topk_indices_buf = nullptr;
38.   if (group_topk > 0) {
39.     masked_scores_buf = topk_scores_buf + topk * num_token_per_block;
40.     group_scores_buf = masked_scores_buf + num_experts * num_token_per_block;
41.     topk_indices_buf = reinterpret_cast<int *>(group_scores_buf + num_groups * num_token_per_block);
42.   } else {
43.     topk_indices_buf = reinterpret_cast<int *>(topk_scores_buf + topk * num_token_per_block);
44.   }
45.   // The address of buffers on the current warp
46.   CompType *scores = scores_buf + warp_id * num_experts;
47.   CompType *topk_scores = topk_scores_buf + warp_id * topk;
48.   CompType *masked_scores = masked_scores_buf + warp_id * num_experts;
49.   CompType *group_scores = group_scores_buf + warp_id * num_groups;
50.   int *topk_indices = topk_indices_buf + warp_id * topk;
51. 
52.   /***
53.      * Section: Main Loop
54.      * - Each warp is responsible for one token
55.      */
56.   int total_round = (num_tokens + num_token_per_block - 1) / num_token_per_block;
57.   for (int round = blockIdx.x; round < total_round; round += gridDim.x) {
58.     int token_offset_cur_warp = round * num_token_per_block + warp_id;
59.     // Each warp is responsible for one token
60.     if (token_offset_cur_warp >= num_tokens) break;
61. 
62.     /***
63.          * Section: Init buffer
64.          * - Clear the global buffer which will accept the result of this round
65.          * - Clear/Init the shmem buffer used by current warp this round
66.          * - Load the logits to shmem
67.          */
68.     int pos_offset = token_offset_cur_warp * num_experts;
69.     // Clear the probs/routing_map (num_experts)
70.     for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
71.       probs[pos_offset + i] = 0.0;
72.       routing_map[pos_offset + i] = false;
73.       if (score_function == 1) {
74.         intermediate_output[pos_offset + i] = -std::numeric_limits<CompType>::infinity();
75.       }
76.     }
77.     // Load the logits to shmem
78.     for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
79.       scores[i] = logits[pos_offset + i];
80.     }
81.     // If group_topk > 0, init the masked_scores to -inf
82.     if (group_topk > 0) {
83.       for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
84.         masked_scores[i] = -std::numeric_limits<CompType>::infinity();
85.       }
86.     }
87.     __threadfence_block();
88.     __syncwarp();
