102.       __syncwarp();
103.       // Save the softmax output for backward
104.       for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
105.         intermediate_output[pos_offset + i] = scores[i];
106.       }
107.     } else if (score_function == 0) {  // score_function == 0 means sigmoid
108.       // Apply sigmoid to the logits
