21. /*
22.  * ---------------------------------------------------------------------------
23.  * NVFP4 2D PARTIAL-SHARD KERNEL DESIGN
24.  *
25.  * These kernels mirror the FP8 block-scaling helpers but operate on shard-local
26.  * slices and nibble-packed FP4 rowwise buffers. One CUDA block covers a logical
27.  * 16x16 tile (grid = ceil(W/16) x ceil(H/16), blockDim = 256 threads).
28.  *
29.  * 1) Partial Amax (`nvfp4_2d_compute_partial_amax_kernel`)
30.  *    - Warps sweep the tile using nested loops, accumulating local maxima only
31.  *      for elements in [start_offset, start_offset + len).
32.  *    - Shared memory reduces the 8 warp maxima; the block writes a float into
33.  *      `amax_ptr[tile_row * stride_h + tile_col * stride_w]`.
34.  *
35.  *      Tile/warp mapping (each '#' = elements visited by that warp):
36.  *
37.  *          +------------------+
38.  *          |########..........|  Warp 0
39.  *          |########..........|  Warp 1
40.  *          |   ...            |
41.  *          |########..........|  Warp 7
42.  *          +------------------+
43.  *
44.  * 2) Partial Cast (`nvfp4_2d_partial_cast_kernel`)
45.  *    - Stage the tile into shared memory (same pattern as FP8).
46.  *    - For each 4-value group, build float2 pairs and call
47.  *      `ptx::mul_cvt_fp32_to_fp4_4x`, producing packed FP4 nibbles.
48.  *    - Compute a shard-local byte index and update only the owned nibble(s)
49.  *      using read-modify-write:
50.  *
51.  *          packed_bits = [mw3 | mw2 | mw1 | mw0]
52.  *          byte_idx    = (ref_elem_idx - start_offset) >> 1
53.  *          if elem_idx % 2 == 0:  // low nibble
54.  *              byte = (byte & 0xF0) | nibble
55.  *          else:                  // high nibble
56.  *              byte = (byte & 0x0F) | (nibble << 4)
57.  *
58.  *      Thread coverage inside a tile:
59.  *
60.  *          rows:   16           columns: 16
61.  *          Warp 0 -> rows 0-1   lanes sweep cols 0..3, 4..7, ...
62.  *          Warp 1 -> rows 2-3   (groups of 4 elements per thread)
63.  *          ...
64.  *          Warp 7 -> rows 14-15
65.  * ---------------------------------------------------------------------------
66.  */
67. 
68. // constexpr float factor = 6.0 * 6.0 * 448.0 * 448.0;
69. constexpr float factor_inv = 1.0 / (6.0 * 6.0 * 448.0 * 448.0);
70. constexpr int kTileDim = 16;
71. constexpr int kThreadsPerBlock = 256;
72. 
73. // Kernel to compute alpha *= amax_A * amax_B / factor
74. __global__ void compute_nvfp4_per_tensor_scale_kernel(float alpha_in, const float *amax_A,
75.                                                       const float *amax_B, float *alpha_out) {
76.   // factor is defined in the enclosing namespace
77.   *alpha_out = alpha_in * (*amax_A) * (*amax_B) * factor_inv;
78. }
79. 
80. template <typename IType>
81. __global__ void __launch_bounds__(kThreadsPerBlock)
82.     nvfp4_2d_compute_partial_amax_kernel(const IType *input, float *amax_ptr,
83.                                          const size_t amax_stride_h, const size_t amax_stride_w,
84.                                          const size_t h, const size_t w, const size_t start_offset,
85.                                          const size_t len) {
86.   constexpr int kThreadsPerWarp = 32;
87.   constexpr int kNumWarps = kThreadsPerBlock / kThreadsPerWarp;
88.   static_assert(kTileDim * kTileDim == kThreadsPerBlock);
89. 
90.   const size_t tile_col = blockIdx.x;
91.   const size_t tile_row = blockIdx.y;
92.   const size_t end_offset = start_offset + len;
93.   const IType *input_minus_offset = input - start_offset;
94. 
95.   __shared__ float smem[kNumWarps];
96.   float amax = 0.0f;
97. 
98.   size_t r = tile_row * kTileDim + threadIdx.x / kTileDim;
99.   size_t c = tile_col * kTileDim + threadIdx.x % kTileDim;
100.   size_t idx = r * w + c;
101.   if (r < h && c < w && idx >= start_offset && idx < end_offset) {
102.     amax = fabs(static_cast<float>(input_minus_offset[idx]));
103.   }
104. 
105.   for (int delta = kThreadsPerWarp / 2; delta > 0; delta /= 2) {
106.     float other_amax = __shfl_down_sync(0xFFFFFFFF, amax, delta);
107.     __builtin_assume(amax >= 0);
108.     __builtin_assume(other_amax >= 0);
109.     amax = fmaxf(amax, other_amax);
110.   }
111. 
112.   if (threadIdx.x % kThreadsPerWarp == 0) {
113.     smem[threadIdx.x / kThreadsPerWarp] = amax;
114.   }
115. 
116.   __syncthreads();
117. 
118.   if (threadIdx.x == 0) {
119.     for (int i = 0; i < kNumWarps; ++i) {
120.       float other_amax = smem[i];
121.       __builtin_assume(amax >= 0);
122.       __builtin_assume(other_amax >= 0);
123.       amax = fmaxf(amax, other_amax);
124.     }
125.     amax_ptr[tile_row * amax_stride_h + tile_col * amax_stride_w] = amax;
126.   }
127. }
