19. constexpr size_t GEMM_SWIZZLED_SCALE_TILE_DIM_X = 4;
20. constexpr size_t GEMM_SWIZZLED_SCALE_TILE_DIM_Y = 128;
21. 
22. /*! \brief Convert compact scale indices into GEMM swizzled scale index
23.  *
24.  *  MXFP8 GEMM expects scaling factors to be in a "swizzled" order
25.  *  (https://docs.nvidia.com/cuda/cublas/#d-block-scaling-factors-layout).
26.  *  This function converts indices from "compact" order (i.e. matching
27.  *  the FP8 data) to swizzled order.
28.  *
29.  */
30. __device__ __forceinline__ size_t gemm_swizzled_scale_idx(size_t i, size_t j, size_t num_tiles_X) {
31.   constexpr size_t TILE_DIM_X = GEMM_SWIZZLED_SCALE_TILE_DIM_X;
32.   constexpr size_t TILE_DIM_Y = GEMM_SWIZZLED_SCALE_TILE_DIM_Y;
33.   constexpr size_t TILE_SIZE = TILE_DIM_X * TILE_DIM_Y;
34.   const size_t tile_idx_X = j / TILE_DIM_X;
35.   const size_t tile_idx_Y = i / TILE_DIM_Y;
36.   const size_t idx_in_tile_X = j % TILE_DIM_X;
37.   const size_t idx_in_tile_Y = i % TILE_DIM_Y;
38.   size_t idx = (tile_idx_Y * num_tiles_X + tile_idx_X) * TILE_SIZE;
39.   idx += (idx_in_tile_Y % 32) * 16 + (idx_in_tile_Y / 32) * 4 + idx_in_tile_X;
40.   return idx;
41. }
