148. using TupleKeyType = std::tuple<uint64_t, uint64_t, uint64_t, bool>;
149. struct TupleHash {
150.   size_t operator()(const TupleKeyType& t) const {
151.     // Generate a hash for a tuple by combining the hashes of its entries
152.     // See: https://www.boost.org/doc/libs/1_55_0/doc/html/hash/reference.html#boost.hash_combine
153.     size_t seed = 0;
154.     std::hash<uint64_t> hasher;
155.     seed ^= hasher(std::get<0>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
156.     seed ^= hasher(std::get<1>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
157.     seed ^= hasher(std::get<2>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
158.     return seed;
159.   }
160. };
