337. template <>
338. __device__ __forceinline__ float exp2f_rcp<float>(e8m0_t biased_exp) {
339.   // Handle the special case of NaN.
340.   if (biased_exp == 255) return __int_as_float(0x7fffffff);
341.   // Handle the special case where the unbiased exponent is 127, so the reciprocal is 2^-127 which needs the first bit of
342.   // the mantissa to be 1, which can't be obtained by shifting `FP32_MANTISSA_BITS` bits to the left.
343.   if (biased_exp == 254) return __int_as_float(0x00400000);
344.   // Fast calculation when the unbiased exp is in [-126, 126], and only the exponent part is used to express the reciprocal.
345.   return __int_as_float((254 - biased_exp) << FP32_MANTISSA_BITS);
346. }
