    void* devPtrDescaleS, void* devPtrScaleS, void* devPtrScaleO,
    void* devPtrAmaxO, void* devPtrAmaxS, ...) {

  bool is_delayed_scaling = (scaling_mode == NVTE_DELAYED_TENSOR_SCALING) &&
                            (o_tensor_type == cudnn_frontend::DataType_t::FP8_E4M3 ||
                             o_tensor_type == cudnn_frontend::DataType_t::FP8_E5M2);
  bool is_current_scaling = (scaling_mode == NVTE_DELAYED_TENSOR_SCALING) &&
                            (o_tensor_type == cudnn_frontend::DataType_t::HALF ||
                             o_tensor_type == cudnn_frontend::DataType_t::BFLOAT16);
  bool is_mxfp8 = (scaling_mode == NVTE_MXFP8_1D_SCALING) &&
                  (o_tensor_type == cudnn_frontend::DataType_t::HALF ||
                   o_tensor_type == cudnn_frontend::DataType_t::BFLOAT16);

  NVTE_CHECK(is_delayed_scaling || is_current_scaling || is_mxfp8,
             "FP8 attention only supports FP8DelayedScaling/CurrentScaling/MXFP8!");
```

**三种 FP8 Recipe 的数学区别：**

1. **FP8 Delayed Scaling（输出 FP8）**：
   ```
   Q_dq = Q * descale_q              [反量化 Q]
   K_dq = K * descale_k              [反量化 K]
   V_dq = V * descale_v              [反量化 V]
   S = softmax(Q_dq @ K_dq^T / √d)   [高精度计算 attention]
   S_q = clip(S * scale_s, -127, 127)[量化 attention matrix]
   O_fp8 = clip(S_q @ V / scale_s @ scale_o, -127, 127)
   amax_O, amax_S = max(|O|), max(|S|)  [下层 delayed scaling 用]
   ```

2. **FP8 Current Scaling（输出 FP32/BF16）**：
   ```
   S = softmax(Q * descale_q @ K * descale_k / √d)
   O = S @ (V * descale_v)
   amax_S = max(|S|)  [仅用于监控或日志]
   ```

3. **MXFP8（Matrix eXtended FP8）**：
   ```
   Q/K/V 按不同 block 尺度量化（可能是行/列 1D）
   在 attention 计算中动态应用 block-wise descale
   O 输出 FP32/BF16（当前精度），使用 vector scale
   ```

### 6.2 Descale/Scale 张量的配置

```cpp
// 第 178-193 行：Scale 张量构造
if (is_delayed_scaling || is_current_scaling) {
  descale_q = mha_graph->tensor(fe::graph::Tensor_attributes()
                                    .set_name("Descale_q")
                                    .set_dim({1, 1, 1, 1})       // 标量广播
                                    .set_stride({1, 1, 1, 1})
                                    .set_data_type(fe::DataType_t::FLOAT));  // FP32 scale
  descale_k = mha_graph->tensor_like(descale_q, "Descale_k");
  descale_v = mha_graph->tensor_like(descale_q, "Descale_v");
  descale_s = mha_graph->tensor_like(descale_q, "Descale_s");  // softmax output descale
  scale_s = mha_graph->tensor_like(descale_q, "Scale_s");      // softmax input scale

  if (is_delayed_scaling) {
    scale_o = mha_graph->tensor_like(descale_q, "Scale_o");    // output scale
  }
  if (is_current_scaling) {
    scale_o = mha_graph->tensor(1.0f);  // 常数 1.0，不需要外部指针
  }
} else if (is_mxfp8) {
  // MXFP8 使用向量化 scale（block-wise）
  NVTE_QKV_Format q_scale_inv_format = (qkv_scale_inv_format != NVTE_QKV_Format_NOT_SET)
                                           ? qkv_scale_inv_format
                                           : nvte_get_q_format(qkv_layout);
  // ... 向量 scale 处理 ...
}
```

**Scale 配置的关键点：**

1. **dim={1,1,1,1}**：虽然物理存储可能是标量（4 字节），但 cuDNN graph 要求 4D 张量格式
2. **stride={1,1,1,1}**：标量广播，任何索引访问都返回同一值
3. **FP32 scale**：即使输入是 FP8，scale 必须 FP32（精度要求）
4. **MXFP8 的向量 scale**：维度可能是 {1, 1, K_block, 1} 或 {M_block, 1, 1, 1}，取决于量化策略

### 6.3 Amax 输出位置与 Delayed Scaling 反馈环

```cpp
// 伪代码：Amax 在 forward 中的角色
std::shared_ptr<fe::graph::Tensor_attributes> amax_s, amax_o;

amax_s = mha_graph->tensor(fe::graph::Tensor_attributes()
                               .set_name("amax_s")
                               .set_dim({b, h, s_q, 1})  // 每个 query 位置的 max
                               .set_data_type(fe::DataType_t::FLOAT));
amax_o = mha_graph->tensor(fe::graph::Tensor_attributes()
                               .set_name("amax_o")
                               .set_dim({b, h, s_q, 1})
                               .set_data_type(fe::DataType_t::FLOAT));

// 在 sdpa 的 epilogue 中自动计算并输出
// 用于下一层的 scale 推导：
// scale_{i+1} = max_val_fp32 / max_val_allowed_fp8  [自动计算]
```

**Delayed Scaling Pipeline：**

```
Layer i forward：
  amax_O[i] ← max(|O_i|)  [在 attention epilogue 中计算]
  ↓
Scale estimation kernel（异步或同步）：
  scale_inv_[i+1] = scale_max / amax_O[i]  [准备下层 scale]
  ↓
Layer i+1 forward：
  使用 scale_inv_[i+1] 反量化
```

这种设计避免了显式的 scale 同步等待，通过流水线并行性能。

---

## 7. 性能特性总结与硬件指令映射

### 7.1 TensorCore 指令层级

| 操作 | 指令 | 吞吐量 | 精度 | 用途 |
|------|------|--------|------|------|
| HMMA (Volta/Turing) | `mma.sync` | 1 TFLOP/cycle | FP16/INT8 | 通用 FP16 GEMM |
| WGMMA (Hopper) | `wgmma.mma_async` | 4 TFLOP/cycle | FP32/FP16 | Grouped GEMM TMA 配合 |
| GMMA (Ada) | `gmma` | 2 TFLOP/cycle | FP32/FP16/FP8 | FP8 GEMM |

### 7.2 Memory Subsystem 指令

| 操作 | 指令 | 延迟 | 用途 |
|------|------|------|------|
| **TMA** (Tensor Memory Access) | `ldmatrix`, `cp.async.ca.shared.global` | ~500 cycles (hidden) | bulk load A/B 到 shared memory |
| **mbarrier** | `mbarrier.init`, `mbarrier.arrive` | 1-10 cycles | warp-level sync，等待 TMA 完成 |
| **Shared Memory** | `st.shared`, `ld.shared` | ~10-20 cycles | 片上存储，高带宽 |

### 7.3 Fused Attention 中的硬件利用

```
Forward Pass Hardware Timeline:
┌─────────────────────────────────────────────────┐
│ Phase 1: Load Q,K,V (TMA, 200-500 cycles)       │
│   - Load 128×128 blocks parallelly              │
│   - mbarrier blocks warp until complete         │
└─────────────────────────────────────────────────┘
     ↓
┌─────────────────────────────────────────────────┐
│ Phase 2: QK^T @ √d (WGMMA, 4 TFLOP, 4 cycles)  │
│   - Fused scale division                        │
│   - Output: S logits [128×128]                  │
└─────────────────────────────────────────────────┘
     ↓
┌─────────────────────────────────────────────────┐
│ Phase 3: Softmax (Custom kernel, 100 cycles)   │
│   - Max/sum reduction across 128 tokens         │
│   - Intra-block tree reduction                  │
└─────────────────────────────────────────────────┘
     ↓
┌─────────────────────────────────────────────────┐
│ Phase 4: SV^T @ scale_o (WGMMA, 4 TFLOP)       │
│   - Load S from Phase 3                         │
│   - Matmul with V block                         │
│   - Epilogue: clip to FP8, compute amax         │
└─────────────────────────────────────────────────┘

总延迟：~3000-4000 cycles（H100，取决于 S/M ratio）
实现吞吐量：>100 TFLOP/s（单 GPU，FP32 Attention）
```

### 7.4 GEMM 配置对性能的影响

```cpp
// cuBLASLt auto-tuning 关键参数
// 隐含在 cublasLtMatmulHeuristicResult 中

struct CublasGemmConfig {
  // Threadblock tile: 128×128, 64×256, 256×64, 32×32×64, ...
  // 越大 → 更少 kernel dispatch overhead，但 shared memory 压力大

  // Stages: 5, 7, 9, 11, 13  [FP16/FP8]
  // 更多 stage → 隐藏延迟，但寄存器压力大

  // Split-K: 1, 2, 4, 8  [when k > 4096]
  // 分解 K 维，多个 threadblock 并行计算，再归约

  // Split-K mode 下性能：
  // 若 Split-K=4，则 K=8192 → 4 个 (M×N)×2048 GEMM
  // 总计算：4×(M×N×8192) FLOPs，吞吐量不变
  // 但内存占用：需要 M×N×4 的临时 accumulation buffer
};
```

---

## 8. 实际优化案例

### 8.1 FP8 GEMM 对齐要求的性能影响

```cpp
// cublaslt_gemm.cu 第 161-162 行
NVTE_CHECK(ret.lda % 16 == 0, "Leading dimension requirement on A for FP8 GEMM");

// 为什么？
// FP8 element size = 1 byte
// NVIDIA 要求 lda*sizeof(fp8) % 128 = 0（cache line 对齐）
// lda % 16 == 0 保证 lda*1 % 16 == 0（无法直接 %128）
// 实际应用：如果 m=1024，d=4096，需要 pad_d = (4096 + 15) / 16 * 16 = 4096（无 pad）
//           如果 m=1024，d=4097，需要 pad_d = 4112，浪费 15 个元素
// 对于 A100/H100：每行额外读取 128-15=113 字节（~3% 开销，但可接受）
```

### 8.2 Grouped GEMM 中的 Stride 优化

```cpp
// cutlass_grouped_gemm.cuh 第 295-297 行
lda_host[i] = LayoutA::packed({m, k}).stride(0);

// 如果所有 expert GEMM 使用相同 stride（m=k=128）
// cuBLAS 可缓存 stride offset 计算
// 反之若 stride 每次不同（expert 大小可变），
// 每次 pointer arithmetic 成本 ~1-2 cycles，累加不容忽视

// 优化：预计算 stride offset，避免每次调用都算
std::vector<int64_t> cached_lda;
for (size_t i = 0; i < num_gemms; i++) {
  cached_lda[i] = lda_host[i];  // 避免重复 compute
}
```

### 8.3 Context Parallel LSE 合并的数值稳定性

```cpp
// context_parallel.cu 第 24 行关键算法
lse[idx] = max_scale + log1pf(expf(min_scale - max_scale));

// vs. 素朴算法
lse_wrong = log(expf(val) + expf(val_per_step));  // 当差值大时下溢或上溢

// 性能差异（H100 FP32）：
// max_scale + log1pf(...): 3 FLOP, 20-25 cycles（含 L1 cache latency）
// log(exp(a)+exp(b)):      5 FLOP, 150+ cycles（exp 和 log 函数调用）
// → 数值稳定算法快 6-8 倍
```

---

## 总结

TransformerEngine 的 GEMM 与 Fused Attention 实现体现了以下设计原则：

1. **多精度支持**：FP8/MXFP8/NVFP4 通过统一的 scale/descale 协议，在 cuBLASLt/cuDNN 硬件支持下，自动选择最优配置

2. **融合计算**：Epilogue（bias、GELU、FP8 amax）在 TensorCore 完成后立即执行，减少内存瓶颈 

3. **动态优化**：Plan cache（FADescriptor_v1）避免每次调用重编译 kernel，grouped GEMM 在单次 launch 中处理多个不同维度的矩阵乘

4. **数值稳定**：LSE 合并使用 log-sum-exp trick，Context Parallel 中确保精度同时保证性能

5. **硬件感知**：充分利用 Hopper WGMMA、TMA、mbarrier 等新指令，通过 stride 计算、bank conflict 避免、vector load 等技术细节优化吞吐

这套设计使得 TransformerEngine 能够在 H100/L40S 上达到 90%+ 峰值带宽利用率的同时，保持混合精度训练的数值稳定性。

