## 1. Comm+GEMM Overlap 用户缓冲环形通信

**文件**：`common/comm_gemm_overlap/userbuffers/userbuffers.cu`

### 代码段 1.1：环形 AllGather + Reduce-Scatter 信号协议

```cuda
// 行 67-100：AllReduce Reduce-Scatter 阶段（FP16 原地）
template <int RANKS>
__global__ void __launch_bounds__(MAX_THREADS)
    userbuffers_fp16_sum_inplace_gpu_rw(const int op, const int flagoffset, const int firstrank,
                                        const int myrank, const int gpustep, const int lineoffset,
                                        const int numlines, void **commbuff, const int handleridx,
                                        const uint64_t ub_timeout) {
  __shared__ int4 *userptr[RANKS];          // 共享内存：其他 GPU 的用户缓冲指针数组
  int *flagptr, physgpu, targetgpu, *myptr; // flag：GPU 间同步计数器
  int *reduceidptr, reduce_id;              // reduce_id：当前 reduce 操作的编号

  // 线程映射：threadIdx.x < RANKS，每个线程负责一个 GPU
  if (threadIdx.x < RANKS) {
    physgpu = myrank * gpustep + firstrank;           // 本 GPU 物理编号
    targetgpu = threadIdx.x * gpustep + firstrank;    // 目标 GPU 物理编号
    const int blockflagoffset = NVTE_MAX_NVLINK * 2 * blockIdx.x;  // block-level flag offset

    // 读取本 GPU 的 flag 指针（作为 producer）
    myptr = (reinterpret_cast<int *>(commbuff[physgpu])) + flagoffset;
    reduceidptr = myptr - NVTE_MAX_OPS;  // 指向 reduce_id 存储位置
    reduce_id = (*reduceidptr) + 1;      // 递增 reduce_id（自动化协议）

    // 读取目标 GPU 的 flag 指针（作为 consumer）
    flagptr = (reinterpret_cast<int *>(commbuff[targetgpu])) + flagoffset + blockflagoffset;
    myptr += blockflagoffset;

    // 发送本 GPU 的 reduce_id 到目标 GPU（原子操作，无锁）
    flagptr[physgpu] = reduce_id;
    volatile int *flag = (volatile int *)&(myptr[targetgpu]);  // 等待目标 GPU 的 flag

    // 加载目标 GPU 的用户缓冲地址
    userptr[threadIdx.x] = reinterpret_cast<int4 *>(commbuff[targetgpu + handleridx]);

    // Busy-wait：轮询检查 reduce-scatter 何时完成（check > 而非 ==，防止整数溢出）
    clock_t s = clock64();
    while (CHECK_IDS(*flag, reduce_id)) {  // CHECK_IDS：防止 flag 环绕
      if (CHECK_TIMEOUT(s, ub_timeout)) {  // 超时保护
        UB_PRINT("[%d] Allreduce reduce-scatter: SM %d [%d]: expecting %d got %d", myrank,
                 blockIdx.x, threadIdx.x, reduce_id, *flag);
        break;
      }
    }
    reduce_id++;  // 为下一次操作准备 id
  }
  __syncthreads();  // block 级同步，等待所有线程的 flag 设置完成
```

**关键要点**：
- **Flag/Counter 协议**：使用 `reduce_id` 自动递增编号，避免 ABA 问题；通过 `CHECK_IDS((unsigned)producer - (unsigned)consumer)` 的无符号减法防止整数溢出
- **跨 GPU 通信**：直接在 global memory 中通过指针数组 `userptr[RANKS]` 读取其他 GPU 的缓冲数据，利用 NVLink 的点对点访问
- **异步信号**：GPU 不阻塞，只在接收线程的 `volatile int *flag` 中轮询，编译器不会优化掉此读
- **SM 安全性**：`__threadfence_system()` 确保 GPU 间内存一致性

---

### 代码段 1.2：环形数据复制与归约

```cuda
// 行 100-151：实际的 AllReduce Gather 数据复制与加法归约
  int warp = blockIdx.x + (threadIdx.x >> 5);      // 每个 warp 负责不同的 ring 位置
  int dest[RANKS];
#pragma unroll
  for (int i = 0; i < RANKS; i++) 
    dest[i] = (i + myrank + warp) & (RANKS - 1);   // 环形相邻 GPU：(myrank + offset) mod RANKS

  __syncthreads();

  // 主计算循环：每个线程处理多行数据
  for (int line = threadIdx.x + blockDim.x * (myrank + RANKS * blockIdx.x); 
       line < numlines;
       line += blockDim.x * gridDim.x * RANKS) {   // 步长：全局线程数 × RANKS（环形）

    int4 val[RANKS];                                // 寄存器数组：加载所有 RANKS 个 GPU 的数据

#pragma unroll
    for (int i = 0; i < RANKS; i++) {
      // 跨 GPU 的全局内存读取：ld.global.nc（非缓存）
      val[i] = userptr[dest[i]][lineoffset + line];  // 从 dest[i] GPU 的缓冲读 line 处的数据
    }

    // FP16 向量加法（int4 = 8×FP16）
    int4 sum = val[0];
    half_dtype *s = reinterpret_cast<half_dtype *>(&sum);  // 转换为 8 个 FP16 指针

#pragma unroll
    for (int i = 1; i < RANKS; i++) {
      half_dtype *x = reinterpret_cast<half_dtype *>(&val[i]);
#pragma unroll
      for (int j = 0; j < 8; j++) 
        s[j] += x[j];  // 逐个 FP16 元素累加
    }

#pragma unroll
    // 将归约结果写回所有 RANKS 个 GPU（st.global.cs = cache-streaming）
    for (int i = 0; i < RANKS; i++) {
      userptr[dest[i]][lineoffset + line] = sum;    // 全局内存写：st.global.cs
    }
  }

  __syncthreads();
  if (threadIdx.x == 0) __threadfence_system();   // 全局 GPU 间 fence
  __syncthreads();

  // Reduce-Scatter 同步：通知 consumer GPU 此 block 完成
  if (threadIdx.x < RANKS) {
    flagptr[physgpu] = reduce_id;                    // 发送完成信号
    volatile int *flag = (volatile int *)&myptr[targetgpu];
    clock_t s = clock64();
    while (CHECK_IDS(*flag, reduce_id)) {           // 再次等待 consumer 的 flag
      if (CHECK_TIMEOUT(s, ub_timeout)) {
        UB_PRINT("[%d] Allreduce Gather: SM %d [%d]: expecting %d got %d", myrank, blockIdx.x,
                 threadIdx.x, reduce_id, *flag);
        break;
      }
    }
  }
  if (threadIdx.x == 0 && blockIdx.x == 0) 
    *reduceidptr = reduce_id;  // 全局 reduce_id 递增
```

**关键指令**：
- **ld.global.nc**：Load Global No Cache，避免污染 L2；跨 GPU 读取时使用
- **st.global.cs**：Store Global Cache-Streaming，旁路 L1，写入 L2；避免缓存行为影响通信时序
- **__threadfence_system()**：GPU 之间的全内存屏障，确保所有线程的写全局可见
- **环形拓扑**：通过 `dest[i] = (i + myrank + warp) % RANKS` 轮转，减少单一瓶颈

