void CommOverlapCore::initialize(int tp_size, int num_splits, int num_max_streams,
                                 int comm_cga_size, int gemm_priority, int comm_priority,
                                 int num_comm_sm, bool set_sm_margin, bool use_ce,
                                 bool atomic_gemm) {
  _use_ce = static_cast<int>(use_ce);            // Copy Engine 使用标志
  _num_comm_sm = num_comm_sm;                    // 保留给通信的 SM 数
  _cga_size = comm_cga_size;                     // 协作线程组大小（CTA Per SM）

  // 设置 GEMM 与通信的优先级（cuBLASLt 流优先级）
  if (gemm_priority == 0 && comm_priority == 0) {
    transformer_engine::cuda::stream_priority_range(&_gemm_priority, &_comm_priority);  // 自动查询
  } else {
    _gemm_priority = gemm_priority;
    _comm_priority = comm_priority;
  }

  // 创建 num_splits 个高优先级计算流（用于 GEMM split）
  for (int i = 0; i < std::min(num_max_streams, num_splits); i++) {
    cudaStream_t stream;
    NVTE_CHECK_CUDA(cudaStreamCreateWithPriority(&stream, cudaStreamNonBlocking, _gemm_priority));
    _stream_compute.push_back(std::move(stream));
  }

  _num_splits = num_splits;
  _rank = _ub_comm->myrank;
  _tp_size = tp_size;
  _tp_id = _rank % _tp_size;

  // 计算数学 SM（总 SM - 通信 SM）
  int sm_count = transformer_engine::cuda::sm_count();  // 查询 GPU SM 总数
  _math_sms = (set_sm_margin) ? sm_count - num_comm_sm : sm_count;  // 是否预留 SM
  _math_sms -= transformer_engine::getenv<int>("NVTE_EXT_MARGIN_SM", 0);  // 环境变量调整
```

**关键设计**：
- **SM Margin**：保留 `num_comm_sm` 个 SM 运行通信 kernel，其余运行 GEMM
- **流优先级**：通信流 `_comm_priority` > GEMM 流 `_gemm_priority`（Hopper 持久 CTA 调度）
- **TP 拓扑**：`_tp_id = _rank % _tp_size` 将全局 rank 映射到 TP 组
- **Atomic GEMM**：通过原子操作实现无锁同步，减少延迟

