// 行 102-134：Atomic GEMM 计数器与事件创建
  _atomic_gemm = atomic_gemm;
  if (_atomic_gemm) {
    // 分配原子计数器：num_splits × 2（ping-pong 缓冲）
    void *counter_ptr;
    size_t counter_bytes = _num_splits * 2 * sizeof(int32_t);
    NVTE_CHECK_CUDA(cudaMalloc(&counter_ptr, counter_bytes));
    NVTE_CHECK_CUDA(cudaMemset(counter_ptr, 0, counter_bytes));        // 初始化为 0
    NVTE_CHECK_CUDA(cudaMemset(counter_ptr, 1, counter_bytes / 2));    // 前半部分初始化为 1

    _counter = TensorWrapper(counter_ptr, 
                            std::vector<size_t>{static_cast<size_t>(_num_splits * 2)},
                            DType::kInt32);
  }

  // 创建事件用于流间同步（用于时间测量与调度）
  NVTE_CHECK_CUDA(cudaEventCreateWithFlags(&_start_compute, 0));
  NVTE_CHECK_CUDA(cudaEventCreateWithFlags(&_stop_compute, 0));
  NVTE_CHECK_CUDA(cudaEventCreateWithFlags(&_start_comm, 0));
  NVTE_CHECK_CUDA(cudaEventCreateWithFlags(&_stop_comm, 0));

  /*
    Hopper 持久 CTA 快速依赖启动：使用事件控制 kernel 启动顺序
    在 CUDA 12.3+ 与 CUDA_DEVICE_MAX_CONNECTIONS > 1 时启用
  */
  int max_connection = transformer_engine::getenv<int>("CUDA_DEVICE_MAX_CONNECTIONS", 8);
  int runtime_version = 0;
  NVTE_CHECK_CUDA(cudaRuntimeGetVersion(&runtime_version));
  cudaDeviceProp deviceProp;
  NVTE_CHECK_CUDA(cudaGetDeviceProperties(&deviceProp, 0));

  // 仅在 Hopper（SM 9.0）且支持快速启动时创建 event
  if (runtime_version >= 12030 && deviceProp.major == 9 && max_connection > 1) {
    NVTE_CHECK_CUDA(cudaEventCreateWithFlags(&_comm_launch_event, cudaEventDisableTiming));
  } else {
    _comm_launch_event = 0;
  }
}  // initialize() 结束
```

**Atomic GEMM 机制**：
- **Ping-Pong 缓冲**：前 `_num_splits` 个计数器初始为 1，后 `_num_splits` 个为 0
- **无锁协调**：GEMM kernel 通过 `atomicCAS(counter, 0, 1)` 等待通信完成，反之通信通过 `atomicExch(counter, 0)` 通知
- **Hopper 优化**：Fast Dependent Launch 使通信 kernel 能立即（无延迟）调度 GEMM kernel

