## 3. 融合 Router TopK + Score 函数

**文件**：`common/fused_router/fused_topk_with_score_function.cu`

### 代码段 3.1：TopK + Score 函数的完整管道

```cuda
// 行 18-150：融合 TopK with Score Function kernel（MoE routing）
template <typename DataType, typename BiasType, TopkFuncType TopkFunc = TopkFuncType::Naive>
__global__ void fused_topk_with_score_function_forward_kernel(
    const DataType *logits,           // [num_tokens, num_experts]
    int num_tokens, int num_experts, int topk, bool use_pre_softmax,
    int num_groups, int group_topk,   // group-limited top-k（先 group top-k1，再 top-k2）
    float scaling_factor,
    int score_function,               // 0=sigmoid, 1=softmax, 2=sqrtsoftplus
    const BiasType *expert_bias,
    DataType *probs,                  // [num_tokens, num_experts] routing 概率
    bool *routing_map,                // [num_tokens, num_experts] routing 掩码
    CompType *intermediate_output) {  // 保存 softmax/sigmoid 用于 backward

  // ====== 第 1 部分：初始化与共享内存分配 ======
  int num_token_per_block = blockDim.x / kThreadsPerWarp;  // 每 block 处理的 token 数
  int warp_id = threadIdx.x / kThreadsPerWarp;              // warp 在 block 内的编号
  int lane_id = threadIdx.x % kThreadsPerWarp;              // warp 内的线程编号

  extern __shared__ float shmem[];
  // 共享内存布局：
  // [scores: num_experts×num_token_per_block]
  // [topk_scores: topk×num_token_per_block]
  // [masked_scores: num_experts×num_token_per_block]（当 group_topk > 0）
  // [group_scores: num_groups×num_token_per_block]（当 group_topk > 0）
  // [topk_indices: topk×num_token_per_block]

  CompType *scores_buf = reinterpret_cast<CompType *>(shmem);
  CompType *topk_scores_buf = scores_buf + num_experts * num_token_per_block;
  CompType *group_scores_buf = nullptr, *masked_scores_buf = nullptr;
  int *topk_indices_buf = nullptr;

  if (group_topk > 0) {
    masked_scores_buf = topk_scores_buf + topk * num_token_per_block;
    group_scores_buf = masked_scores_buf + num_experts * num_token_per_block;
    topk_indices_buf = reinterpret_cast<int *>(group_scores_buf + num_groups * num_token_per_block);
  } else {
    topk_indices_buf = reinterpret_cast<int *>(topk_scores_buf + topk * num_token_per_block);
  }

  // 每个 warp 的本地缓冲指针
  CompType *scores = scores_buf + warp_id * num_experts;
  CompType *topk_scores = topk_scores_buf + warp_id * topk;
  CompType *masked_scores = (masked_scores_buf) ? masked_scores_buf + warp_id * num_experts : nullptr;
  CompType *group_scores = (group_scores_buf) ? group_scores_buf + warp_id * num_groups : nullptr;
  int *topk_indices = topk_indices_buf + warp_id * topk;

  // ====== 第 2 部分：主 token 处理循环 ======
  int total_round = (num_tokens + num_token_per_block - 1) / num_token_per_block;
  for (int round = blockIdx.x; round < total_round; round += gridDim.x) {
    int token_offset_cur_warp = round * num_token_per_block + warp_id;
    if (token_offset_cur_warp >= num_tokens) break;

    int pos_offset = token_offset_cur_warp * num_experts;

    // 清空输出缓冲：probs 和 routing_map
    for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
      probs[pos_offset + i] = 0.0;
      routing_map[pos_offset + i] = false;
      if (score_function == 1) {
        intermediate_output[pos_offset + i] = -std::numeric_limits<CompType>::infinity();
      }
    }

    // 加载 logits 到共享内存
    for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
      scores[i] = logits[pos_offset + i];  // 向量化访问，跨 warp 线程分散
    }

    // 如果启用 group-topk，初始化 masked_scores（用于掩盖已选中的 expert）
    if (group_topk > 0) {
      for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
        masked_scores[i] = -std::numeric_limits<CompType>::infinity();
      }
    }
    __threadfence_block();
    __syncwarp();

    // ====== 第 3 部分：Score 函数应用（softmax/sigmoid/sqrtsoftplus）======
    if (use_pre_softmax && score_function == 1) {
      // 应用 softmax（pre-softmax 在 routing 前）
      apply_softmax_on_float(scores, num_experts, lane_id);
      __syncwarp();
      // 保存 softmax 输出用于 backward
      for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
        intermediate_output[pos_offset + i] = scores[i];
      }
    } else if (score_function == 0) {
      // 应用 sigmoid
      apply_sigmoid_on_float(scores, num_experts, lane_id);
      __syncwarp();
      for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
        intermediate_output[pos_offset + i] = scores[i];
      }
    } else if (score_function == 2) {
      // 应用 sqrtsoftplus：sqrt(softplus(x)) = sqrt(log(1 + exp(x)))
      for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
        intermediate_output[pos_offset + i] = scores[i];  // 保存原始 logits
      }
      __syncwarp();
      apply_sqrtsoftplus_on_float(scores, num_experts, lane_id);
    }

    __syncwarp();

    // Expert bias（仅用于 sigmoid/sqrtsoftplus）
    if (expert_bias && (score_function == 0 || score_function == 2)) {
      for (int i = lane_id; i < num_experts; i += kThreadsPerWarp) {
        scores[i] += static_cast<CompType>(expert_bias[i]);
      }
      __syncwarp();
    }

    // ====== 第 4 部分：Group-Limited TopK（可选）======
    if (group_topk > 0) {
      int group_size = num_experts / num_groups;

      // 第 1 阶段：每个 group 内独立 top-k
      for (int i = 0; i < num_groups; i++) {
        topk_and_mask<TopkFunc>(
            /*scores ptr = */ scores + i * group_size,
            /*data size = */ group_size,
            /*topk = */ group_topk,
            /*indices = */ topk_indices,
            /*top_scores = */ group_scores + i,
            /*lane_id = */ lane_id
        );
      }
      __syncwarp();

      // 第 2 阶段：所有 group scores 中选全局 top-k
      for (int i = lane_id; i < num_groups; i += kThreadsPerWarp) {
        masked_scores[i] = group_scores[i];  // 复制 group max score
      }
      __syncwarp();

      // 全局 topk
      topk_and_mask<TopkFunc>(
          /*scores ptr = */ masked_scores,
          /*data size = */ num_groups,
          /*topk = */ topk,
          /*indices = */ topk_indices,
          /*top_scores = */ topk_scores,
          /*lane_id = */ lane_id
      );
    } else {
      // 标准 TopK（无 group 限制）
      topk_and_mask<TopkFunc>(
          /*scores ptr = */ scores,
          /*data size = */ num_experts,
          /*topk = */ topk,
          /*indices = */ topk_indices,
          /*top_scores = */ topk_scores,
          /*lane_id = */ lane_id
      );
    }

    __syncwarp();

    // ====== 第 5 部分：输出 routing_map 与 probs ======
    // 将 topk 结果写入 global memory：routing_map 与 probs
    for (int i = lane_id; i < topk; i += kThreadsPerWarp) {
      int expert_id = topk_indices[i];
      routing_map[pos_offset + expert_id] = true;       // 标记该 expert 被选中
      probs[pos_offset + expert_id] = topk_scores[i];   // 写入 routing 概率
    }
  }
}
```

**关键算法**：
1. **Score 函数**：`softmax(x) = exp(x) / Σexp(x)`，`sigmoid(x) = 1/(1+exp(-x))`，`sqrtsoftplus(x) = sqrt(log(1+exp(x)))`
2. **Group-Limited TopK**：先在每个 expert group 内找 top-k1，再在 k1 结果中找全局 top-k2，减少分散
3. **Capacity Drop**：可选的负载均衡，丢弃超出容量的 token-expert 对
4. **Warp 并行**：每个 warp 处理一个 token，共享内存 shmem 按 warp 分块

