// mbarrier: multi-barrier 同步机制，支持异步 TMA 等待
__shared__ alignas(8) uint64_t mbar[FP8_ITERATIONS];
initialize_barriers<FP8_ITERATIONS, FP8_THREADS_PER_CHUNK>(mbar, is_master_thread);

// Prefetch first buffer using TMA
for (int prefetch_buff = 0; prefetch_buff < FP8_PREFETCH_BUFFERS_NUM; ++prefetch_buff) {
    const size_t chunk_stage_offset_Y = chunk_offset_Y + prefetch_buff * FP8_BUFFER_DIM_Y;
    const size_t chunk_stage_offset_X = chunk_offset_X;
    if constexpr (IS_DACT) {
      // 同时加载 input 和 activation 两张张量
      copy_2d_to_sharedx2(&in_sh[prefetch_buff], &tensor_map_input, chunk_stage_offset_X,
                          chunk_stage_offset_Y, &act_in_sh[prefetch_buff], &tensor_map_act_input,
                          chunk_stage_offset_X, chunk_stage_offset_Y, shmem_buff_size,
                          &mbar[prefetch_buff], is_master_thread);
    } else {
      copy_2d_to_shared(&in_sh[prefetch_buff], &tensor_map_input, chunk_stage_offset_X,
                        chunk_stage_offset_Y, shmem_buff_size, &mbar[prefetch_buff],
                        is_master_thread);
    }
}
```

**核心机制**：
- **TMA (cp.async.bulk.tensor.2d)**：硬件异步加载，绕过 L1 缓存，减少 SM 阻塞
- **mbarrier**：轻量级栅栏，TMA 硬件自动通知完成，比 `__syncthreads()` 高效
- **双缓冲**：当前 warp 处理 buffer[0]，TMA 同时预取 buffer[1]，隐藏内存延迟

### 2.2 向量化 Warp-Reduce + GlobalAtomicMax

```cuda
// common/cast/fp8/quantize_fp8.cuh 中 cast_kernel 内核心循环逻辑
// (虚拟代码示意，基于实际实现逻辑)
float amax = 0;  // 线程-局部 amax 累积

// ===== 步骤 1: Warp-level 化简 =====
// 32线程内的32x32 tile 各线程扫描 4 个元素
for (int i = 0; i < 4; i++) {
    float val = fabs(static_cast<float>(data[i]));
    amax = fmaxf(amax, val);
}

// Warp-shuffle 树状化简: 32 -> 16 -> 8 -> 4 -> 2 -> 1
#pragma unroll
for (int delta = 16; delta > 0; delta /= 2) {
    float other = __shfl_down_sync(0xFFFFFFFF, amax, delta);
    amax = fmaxf(amax, other);  // 树状化简：对数复杂度
}

// ===== 步骤 2: block-level 化简到单线程（threadIdx.x == 0） =====
if (threadIdx.x == 0) {
    // thread0 拥有该 warp 的 amax，通过 atomicMax 全局更新
    atomicMaxFloat(amax_ptr, amax);  
    // 防止 NaN 和 inf 传播
    if (!isfinite(amax)) amax = 0;
}
```

**优化亮点**：
- **Warp-shuffle**：无 shared memory 访问，超低延迟（单周期指令）
- **AtomicMax**：多个线程块的 amax 并行更新到全局 `amax_ptr`
- **FP8 缩放**：`scale = FP8_MAX / amax`，通过倒数避免除法

