## 3. MXFP8 块量化：32×32 块，E8M0 缩放因子

### 3.1 MXFP8 kernel 的块结构与缩放维度

```cuda
// common/cast/mxfp8/quantize_mxfp8.cuh (行49-100)
__global__ void __launch_bounds__(THREADS_PER_CHUNK)
    quantize_mxfp8_kernel(const __grid_constant__ CUtensorMap tensor_map_input,
                          const __grid_constant__ CUtensorMap tensor_map_act_input,
                          const __grid_constant__ CUtensorMap tensor_map_output_rowwise,
                          const __grid_constant__ CUtensorMap tensor_map_output_colwise,
                          e8m0_t *const scales_rowwise, e8m0_t *const scales_colwise,
                          const float *noop, float *const dbias_workspace, float *const amax_ptr,
                          const size_t rows, const size_t cols, const size_t scale_stride_rowwise,
                          const size_t scale_stride_colwise) {
  // ===== 块参数 =====
  constexpr size_t CHUNK_DIM_Y = 128;  // 块高
  constexpr size_t CHUNK_DIM_X = 128;  // 块宽
  constexpr size_t SCALE_DIM_Y = 32;   // rowwise 缩放块高
  constexpr size_t SCALE_DIM_X = 32;   // colwise 缩放块宽

  // MXFP8: 每个 32x32 tile 有独立的 E8M0 缩放因子
  constexpr size_t THREADS_X = CHUNK_DIM_X / SCALE_DIM_X;  // 4 个 tile 横向
  constexpr size_t THREADS_Y = THREADS_PER_CHUNK / THREADS_X;  // 32 个线程纵向

  // ===== 缓冲维度 =====
  constexpr size_t BUFF_DIM_Y = THREADS_Y;  // 32 行
  constexpr size_t BUFF_DIM_X = CHUNK_DIM_X;  // 128 列（全宽）
  constexpr size_t STAGES = CHUNK_DIM_Y / BUFF_DIM_Y;  // 4 个 stage （128 / 32）

  const size_t block_offset_Y = blockIdx.y * CHUNK_DIM_Y;
  const size_t block_offset_X = blockIdx.x * CHUNK_DIM_X;

  // rowwise scaling: (row_block_idx, col_scale_block_idx)
  // 例：blockIdx.x = 2, CHUNK_DIM_X=128, SCALE_DIM_X=32 => col_scale_block = 2*4 = 8
  const size_t scales_block_offset_Y_rowwise = blockIdx.y * CHUNK_DIM_Y;
  const size_t scales_block_offset_X_rowwise = blockIdx.x * CHUNK_DIM_X / SCALE_DIM_X;

  // colwise scaling: (row_scale_block_idx, col_block_idx)
  const size_t scales_block_offset_Y_colwise = blockIdx.y * CHUNK_DIM_Y / SCALE_DIM_Y;
  const size_t scales_block_offset_X_colwise = blockIdx.x * CHUNK_DIM_X;
}
```

**块映射逻辑**：
- 计算块读取 128×128 数据
- 分为 4×4 个 32×32 缩放块
- Rowwise scales: 按行倍增（每 32 行换一个 E8M0），列跨步 = 4 blocks
- Colwise scales: 按列倍增（每 32 列换一个 E8M0），行跨步 = 4 blocks

### 3.2 E8M0 缩放因子与 GEMM-Swizzled 重排

```cuda
// common/cast/mxfp8/swizzle.cuh (行30-41)
__device__ __forceinline__ size_t gemm_swizzled_scale_idx(size_t i, size_t j, 
                                                           size_t num_tiles_X) {
  // cuBLASLt block-scaling layout: 缩放张量按 4x128 块重排
  constexpr size_t TILE_DIM_X = 4;       // 4 个缩放值为一个水平单元
  constexpr size_t TILE_DIM_Y = 128;     // 128 个缩放值为一个竖向单元
  constexpr size_t TILE_SIZE = TILE_DIM_X * TILE_DIM_Y;  // 512 values/block

  const size_t tile_idx_X = j / TILE_DIM_X;   // 水平块索引
  const size_t tile_idx_Y = i / TILE_DIM_Y;   // 竖向块索引
  const size_t idx_in_tile_X = j % TILE_DIM_X;  // 块内列偏移
  const size_t idx_in_tile_Y = i % TILE_DIM_Y;  // 块内行偏移

  // 全局线性索引 = 块序列号 * 块大小 + 块内分层索引
  size_t idx = (tile_idx_Y * num_tiles_X + tile_idx_X) * TILE_SIZE;
  // 块内：每 32 行交错 4 列（内存局部性优化）
  idx += (idx_in_tile_Y % 32) * 16 + (idx_in_tile_Y / 32) * 4 + idx_in_tile_X;
  return idx;
}
```

**含义**：
- MXFP8 缩放张量（E8M0）需按 cuBLASLt 期望的 4×128 块布局重排
- `(i % 32) * 16 + (i / 32) * 4`：行的前 32 个与后面的分别映射到 16 和 4 列起点
- 这种交错布局使 GEMM 在访问缩放因子时具有 128B 对齐的内存访问

