## 4. NVFP4 Cast+Transpose 融合：PTX 层级 FP4 转换

### 4.1 mul_cvt_fp32_to_fp4_4x PTX 实现（CUDA Hopper+）

```cuda
// common/util/ptx.cuh (行760-768)
__device__ __forceinline__ fp4e2m1x4 mul_cvt_fp32_to_fp4_4x(
    const float2 in01,      // float 对 (in0, in1)
    const float2 in23,      // float 对 (in2, in3)
    const float2 scale,     // (scale_val, scale_val) 对
    const uint32_t rbits) { // 随机舍入位（stochastic rounding）

  // 根据编译条件选择舍入模式
  if constexpr (USE_STOCHASTIC_ROUNDING) {
    // 随机舍入：给定 rbits，在低位添加随机扰动
    // 能减少 FP4 量化的系统性偏差，适用于训练
    return mul_cvt_fp32_to_fp4_4x_with_stochastic_rounding(in01, in23, scale, rbits);
  } else {
    // 四舍五入（round-to-nearest）：标准 FP 舍入，推理友好
    return mul_cvt_fp32_to_fp4_4x_with_rn(in01, in23, scale, rbits);
  }
}
```

### 4.2 四舍五入变体（使用 PTX cvt 指令）

```cuda
// common/util/ptx.cuh (行717-759) 简化示意
__device__ __forceinline__ fp4e2m1x4 mul_cvt_fp32_to_fp4_4x_with_rn(
    const float2 in01, const float2 in23, const float2 scale, const uint32_t rbits) {
#if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)  // Hopper+
  // ===== 步骤 1: 乘以缩放因子（FMA: Fused Multiply-Add） =====
  float scaled_0 = __fmul_rn(in01.x, scale.x);  // in0 * scale
  float scaled_1 = __fmul_rn(in01.y, scale.x);  // in1 * scale
  float scaled_2 = __fmul_rn(in23.x, scale.y);  // in2 * scale
  float scaled_3 = __fmul_rn(in23.y, scale.y);  // in3 * scale

  // ===== 步骤 2: 转换为 E2M1 FP4 格式（3-bit sign + 2-bit exp + 1-bit mant） =====
  // PTX cvt.rn.satfinite.e2m1x2.f32: 将两个 F32 转为一个 byte (2 nibble)
  // 支持饱和处理 (saturate finite) 和舍入模式 (round-to-nearest)
  fp4e2m1x2 out01, out23;
  asm volatile(
      "cvt.rn.satfinite.e2m1x2.f32 %0, %2, %1;"
      : "=h"(reinterpret_cast<uint16_t&>(out01))
      : "f"(scaled_0), "f"(scaled_1)
  );
  asm volatile(
      "cvt.rn.satfinite.e2m1x2.f32 %0, %2, %1;"
      : "=h"(reinterpret_cast<uint16_t&>(out23))
      : "f"(scaled_2), "f"(scaled_3)
  );

  // ===== 步骤 3: 打包为 4 nibble (2 bytes) =====
  // out01 和 out23 各占 1 byte，合并为 e2m1x4
  return make_fp4x4(out01, out23);
#else
  NVTE_DEVICE_ERROR("mul_cvt_fp32_to_fp4_4x_with_rn requires CUDA Arch >= 1000");
#endif
}
```

**PTX 指令详解**：
- `cvt.rn.satfinite.e2m1x2.f32`: 
  - `rn` = round-to-nearest
  - `satfinite` = 饱和处理有限数值（超出范围映射到 E2M1 极值）
  - `.e2m1x2` = 目标格式：两个 E2M1 值（4 bits 每个，共 1 byte）
  - `.f32` = 源格式：两个 FP32 值

