## 5. NVFP4 Nibble RMW（读-修改-写）与 Partial-Shard 协议

### 5.1 部分最大值计算：nvfp4_2d_compute_partial_amax_kernel

```cuda
// common/recipe/nvfp4.cu (行81-127)
template <typename IType>
__global__ void __launch_bounds__(kThreadsPerBlock)
    nvfp4_2d_compute_partial_amax_kernel(
        const IType *input,           // 输入张量
        float *amax_ptr,              // 输出：amax 值数组
        const size_t amax_stride_h,   // amax 行跨度
        const size_t amax_stride_w,   // amax 列跨度
        const size_t h, const size_t w,  // 输入维度
        const size_t start_offset,    // 当前 shard 起始偏移
        const size_t len) {           // 当前 shard 长度

  constexpr int kThreadsPerWarp = 32;
  constexpr int kNumWarps = kThreadsPerBlock / kThreadsPerWarp;  // 8 warps
  static_assert(kTileDim * kTileDim == kThreadsPerBlock);  // 16x16 tile

  const size_t tile_col = blockIdx.x;
  const size_t tile_row = blockIdx.y;
  const size_t end_offset = start_offset + len;
  const IType *input_minus_offset = input - start_offset;

  __shared__ float smem[kNumWarps];  // 8 个 warp 的最大值
  float amax = 0.0f;

  // ===== 步骤 1: 线程映射到 16x16 tile 内，初始化线程局部 amax =====
  size_t r = tile_row * kTileDim + threadIdx.x / kTileDim;   // 行索引
  size_t c = tile_col * kTileDim + threadIdx.x % kTileDim;   // 列索引
  size_t idx = r * w + c;

  // 仅当索引落在 [start_offset, end_offset) 时有效
  if (r < h && c < w && idx >= start_offset && idx < end_offset) {
    amax = fabs(static_cast<float>(input_minus_offset[idx]));
  }

  // ===== 步骤 2: Warp-level 化简（32 线程 -> 1 线程） =====
  for (int delta = kThreadsPerWarp / 2; delta > 0; delta /= 2) {
    float other_amax = __shfl_down_sync(0xFFFFFFFF, amax, delta);
    amax = fmaxf(amax, other_amax);  // 树状化简
  }

  // ===== 步骤 3: 每 warp 的 lane-0 线程将结果写入共享内存 =====
  if (threadIdx.x % kThreadsPerWarp == 0) {
    smem[threadIdx.x / kThreadsPerWarp] = amax;  // 8 个位置
  }
  __syncthreads();

  // ===== 步骤 4: Block-level 化简（8 个 warp amax -> 1） =====
  if (threadIdx.x == 0) {
    for (int i = 0; i < kNumWarps; ++i) {
      amax = fmaxf(amax, smem[i]);
    }
    // 全局写：该 tile 的 amax
    amax_ptr[tile_row * amax_stride_h + tile_col * amax_stride_w] = amax;
  }
}
```

### 5.2 部分 Cast + Nibble-Pack：nvfp4_2d_partial_cast_kernel

```cuda
// common/recipe/nvfp4.cu (行129-160) 简化版
template <typename IType, bool kWidthAligned>
__global__ void __launch_bounds__(kThreadsPerBlock)
    nvfp4_2d_partial_cast_kernel(
        const IType *input, uint8_t *output,
        const float *decode_scale_ptr, const size_t scale_stride_h,
        const size_t scale_stride_w, const float *global_scale_ptr,
        const size_t h, const size_t w,
        const size_t start_offset, const size_t len) {

  constexpr int kNumOutputElemsPerBank = 4;
  constexpr int kThreadsPerWarp = 32;
  constexpr int kLoopsPerRow = (kTileDim + kThreadsPerWarp - 1) / kThreadsPerWarp;
  constexpr int kNumWarps = kThreadsPerBlock / kThreadsPerWarp;
  constexpr int kRowsPerWarp = (kTileDim + kNumWarps - 1) / kNumWarps;

  // ===== 共享内存：16x16 tile（每 4B 一列，避免 bank conflict） =====
  __shared__ float smem[kTileDim][kTileDim + kNumOutputElemsPerBank];

  const int tile_w = blockIdx.x;
  const int tile_h = blockIdx.y;
  const size_t shard_end = start_offset + len;
  const IType *input_minus_offset = input - start_offset;

  float global_encode_scale = global_scale_ptr[0];
  if (global_encode_scale <= 0.f) {
    global_encode_scale = 1.f;
  }

  // ===== 步骤 1: 将 tile 从全局加载到共享内存（循环分块） =====
  // 256 线程覆盖 16x16 tile，分 kLoopsPerRow 轮
  for (int loop = 0; loop < kLoopsPerRow; loop++) {
    size_t col = loop * kThreadsPerWarp + threadIdx.x % kThreadsPerWarp;
    size_t row = tile_h * kTileDim + threadIdx.x / kThreadsPerWarp;
    size_t idx = row * w + col;

    if (col < kTileDim && row < h && idx >= start_offset && idx < shard_end) {
      smem[row % kTileDim][col] = static_cast<float>(input_minus_offset[idx]);
    } else {
      smem[row % kTileDim][col] = 0.f;  // 填充
    }
  }
  __syncthreads();

  // ===== 步骤 2: Cast + Nibble Pack（每线程处理 4 值 -> 1 byte） =====
  // 每线程对 (v0, v1, v2, v3) 调用 mul_cvt_fp32_to_fp4_4x
  float2 scale_pair = make_float2(global_encode_scale, global_encode_scale);
  uint32_t rbits = curand_next();  // 随机舍入位（可选）

  for (int row = threadIdx.x / kTileDim; row < kTileDim; row += kRowsPerWarp) {
    size_t col = (threadIdx.x % kTileDim) * 4;  // 每线程处理 4 列

    if (col + 3 < kTileDim) {
      float2 in01 = make_float2(smem[row][col], smem[row][col+1]);
      float2 in23 = make_float2(smem[row][col+2], smem[row][col+3]);

      // PTX 指令：4 x F32 -> 1 x 8-bit (4 nibble)
      auto packed = ptx::mul_cvt_fp32_to_fp4_4x(in01, in23, scale_pair, rbits);

      // ===== 步骤 3: 计算目标地址并 RMW 更新 =====
      size_t global_row = tile_h * kTileDim + row;
      size_t global_col = tile_w * kTileDim + col;
      size_t global_idx = global_row * w + global_col;

      if (global_idx >= start_offset && global_idx + 3 < shard_end) {
        size_t byte_idx = (global_idx - start_offset) >> 1;  // 每 byte 2 nibble
        uint8_t byte_val = output[byte_idx];

        // 根据奇偶性更新低/高 4 位
        if (global_idx % 2 == 0) {
          // 低 nibble
          byte_val = (byte_val & 0xF0) | (packed & 0x0F);
        } else {
          // 高 nibble
          byte_val = (byte_val & 0x0F) | ((packed & 0x0F) << 4);
        }
        output[byte_idx] = byte_val;
      }
    }
  }
}
```

**Nibble RMW 逻辑**：
- 每个 FP4 值占 4 bits（nibble）
- 两个 nibble

```cuda
// 继续 nibble RMW 逻辑

打包在 1 byte 中
- 元素索引 i: byte_idx = i/2, nibble_in_byte = i%2
- 低 nibble (i%2==0): byte = (byte & 0xF0) | (nibble & 0x0F)
- 高 nibble (i%2==1): byte = (byte & 0x0F) | ((nibble & 0x0F) << 4)
```

**Partial-Shard 协议**：
- 每个 CUDA block 覆盖一个 16×16 tile（256 线程）
- `start_offset` 和 `len` 定义该 shard 的有效范围
- 线程检查 `idx >= start_offset && idx < end_offset`，仅处理有效数据
- 支持分布式 sharded 张量计算，多 GPU 协调梯度更新

