## 6. Cast+Transpose 标准 Tile-Based Kernel

### 6.1 KernelConfig 性能模型（启发式选择）

```cuda
// common/transpose/cast_transpose.cu (行31-100)
struct KernelConfig {
  size_t load_size = 0;      // 向量化加载大小（字节）
  size_t store_size = 0;     // 向量化存储大小（字节）
  bool valid = false;        // 配置有效性标志
  size_t num_blocks = 0;     // 所需 CUDA block 数

  size_t active_sm_count = 0;      // 激活的 SM 数
  size_t elements_per_load = 0;    // L1 缓存加载的元素数
  size_t elements_per_store_c = 0; // 到 cast 输出的存储元素数
  size_t elements_per_store_t = 0; // 到转置输出的存储元素数

  KernelConfig(size_t row_length, size_t num_rows, size_t itype_size, 
               size_t otype_size, size_t load_size_, size_t store_size_, 
               size_t sm_count)
      : load_size{load_size_}, store_size{store_size_} {
    // ===== 步骤 1: 验证字节对齐到 L1 缓存线（128B） =====
    constexpr size_t cache_line_size = 128;
    if (load_size % itype_size != 0 || store_size % otype_size != 0 ||
        cache_line_size % itype_size != 0 || cache_line_size % otype_size != 0) {
      return;  // 无效配置
    }

    // ===== 步骤 2: 计算 tile 大小（每个 warp 处理的元素数） =====
    const size_t row_tile_elements = load_size * THREADS_PER_WARP / itype_size;
    const size_t col_tile_elements = store_size * THREADS_PER_WARP / otype_size;
    // 检查 tile 整除性
    valid = (row_length % row_tile_elements == 0 && 
             num_rows % col_tile_elements == 0);
    if (!valid) {
      return;
    }

    // ===== 步骤 3: 计算块网格大小与 SM 占有率 =====
    // 总块数 = (row tile 数) × (col tile 数)
    num_blocks = (row_length / row_tile_elements) * (num_rows / col_tile_elements);

    // ===== 步骤 4: 性能模型（基于 L1 缓存吞吐量） =====
    constexpr size_t warps_per_sm = 16;  // 粗估每个饱和 SM 有 16 个 warp
    // 活跃 SM 数 = min(总 warp 数 / warps_per_sm, 物理 SM 总数)
    active_sm_count = std::min(DIVUP(num_blocks * warps_per_tile, warps_per_sm), sm_count);

    // 估算 L1 缓存加载/存储的颗粒度（每次 128B）
    elements_per_load = (std::min(cache_line_size, row_tile_elements * itype_size) / itype_size);
    elements_per_store_c = (std::min(cache_line_size, row_tile_elements * otype_size) / otype_size);
    elements_per_store_t = (std::min(cache_line_size, col_tile_elements * otype_size) / otype_size);
  }

  // ===== 步骤 5: 基于成本模型的配置比较 =====
  bool operator<(const KernelConfig &other) const {
    if (this->valid && other.valid) {
      // 成本估计：cost ~ (1/load_bw + 1/store_c_bw + 1/store_t_bw) / active_sms
      // 使用整数运算避免浮点舍入差异
      const auto &l1 = this->elements_per_load;
      const auto &sc1 = this->elements_per_store_c;
      const auto &st1 = this->elements_per_store_t;
      const auto &p1 = this->active_sm_count;
      const auto &l2 = other.elements_per_load;
      const auto &sc2 = other.elements_per_store_c;
      const auto &st2 = other.elements_per_store_t;
      const auto &p2 = other.active_sm_count;

      // 避免除法：scale = lcm(l1, sc1, st1, l2, sc2, st2)
      const auto scale = l1 * sc1 * st1 * l2 * sc2 * st2;
      const auto cost1 = (scale / l1 + scale / sc1 + scale / st1) / p1;
      const auto cost2 = (scale / l2 + scale / sc2 + scale / st2) / p2;
      return cost1 < cost2;
    } else {
      return this->valid && !other.valid;
    }
  }
};
```

**启发式含义**：
- 选择使得 L1 缓存吞吐量最大化的配置
- 加载、转置输出存储、cast 输出存储三者的成本加权
- 考虑 SM 占有率：块多但每 block 占用少的配置反而不高效

### 6.2 Cast+Transpose 主循环（Tile-Based）

```cuda
// common/transpose/cast_transpose.cu 中虚拟主循环示意
// (实际代码含 RTC 编译，这里给出逻辑结构)

// 配置选择后，launch kernel
// 块维度：warps_per_tile * 32 线程/块
// 网格维度：(row_tiles, col_tiles, 1)

const size_t row_tile_size = load_size * THREADS_PER_WARP / itype_size;
const size_t col_tile_size = store_size * THREADS_PER_WARP / otype_size;
const size_t row_tiles = row_length / row_tile_size;
const size_t col_tiles = num_rows / col_tile_size;
const dim3 grid_dim(row_tiles, col_tiles, 1);
const dim3 block_dim(warps_per_tile * THREADS_PER_WARP, 1, 1);

// ===== Kernel 内核心循环 =====
// 每个 warp 处理一个 row_tile_size x col_tile_size 的数据块

__shared__ float cache[col_tile_size][row_tile_size + 1];  // +1 避免 bank conflict

// 第 1 阶段：向量化加载到共享内存
// 每 warp (32 线程) 按行优先加载 row_tile_size 字节
for (int k = 0; k < col_tile_size; k += THREADS_PER_WARP / warps_per_tile) {
    // 块内 warp 索引和线程内索引
    size_t warp_idx = threadIdx.x / THREADS_PER_WARP;
    size_t lane_idx = threadIdx.x % THREADS_PER_WARP;

    // 全局行/列索引
    size_t global_row = blockIdx.y * col_tile_size + k;
    size_t global_col_base = blockIdx.x * row_tile_size;

    // 向量化加载（每线程加载 load_size 字节 = load_size/itype_size 个元素）
    const IType *src = input + global_row * num_cols + global_col_base;

    // 假设 load_size=8, itype_size=4 (float) => 2 个元素/线程
    if (load_size == 8) {
      float2 *src_v2 = (float2*)src;
      float2 val = src_v2[lane_idx];
      // Cast: multiply by scale + convert to output type
      OType2 casted = cast_scale_v2(val, scale);
      cache[k][lane_idx * 2] = static_cast<float>(casted.x);
      cache[k][lane_idx * 2 + 1] = static_cast<float>(casted.y);
    }
}
__syncthreads();

// 第 2 阶段：从共享内存转置加载到寄存器，列优先写回
// warp 按列优先读取（转置），避免 shared memory bank conflict
for (int k = 0; k < row_tile_size; k += THREADS_PER_WARP / warps_per_tile) {
    size_t global_row_base = blockIdx.y * col_tile_size;
    size_t global_col = blockIdx.x * row_tile_size + k;

    // 列优先：warp 内 32 线程扫描一列（连续读共享内存的同一列）
    size_t lane_idx = threadIdx.x % THREADS_PER_WARP;
    size_t col_in_cache = k + lane_idx;

    if (col_in_cache < row_tile_size) {
      // 读取共享内存列向量（与加载时行优先互补）
      float val = cache[0][col_in_cache];  // 第一行

      // 写到转置输出：(col, row) 顺序
      OType *dst_t = output_transposed + 
          global_col * num_rows + global_row_base + 0;
      *dst_t = static_cast<OType>(val);
    }
}
__syncthreads();

// 第 3 阶段：Cast 输出（行优先，与输入相同）
// 直接从共享内存按行优先写到 output_cast
for (int row = threadIdx.x / THREADS_PER_WARP; row < col_tile_size; row += 1) {
    for (int col = (threadIdx.x % THREADS_PER_WARP) * 2; col < row_tile_size; col += 32 * 2) {
      OType *dst_c = output_cast + 
          (blockIdx.y * col_tile_size + row) * num_cols + 
          (blockIdx.x * row_tile_size + col);

      float2 val2 = make_float2(cache[row][col], cache[row][col+1]);
      OType2 out2 = float2_to_otype2(val2);
      ((OType2*)dst_c)[0] = out2;
    }
}
```

**关键设计**：
1. **向量化 I/O**：减少内存访问指令数，提高吞吐
2. **共享内存作为寄存器文件**：Cache 局部数据，避免全局内存重复访问
3. **转置时列优先读**：通过 bank conflict 避免（+1 padding）
4. **双输出路径**：同时写 cast_output（行主）和 transposed_output（列主）

