## 7. Cast+Transpose Fusion + dAct 激活导数融合

### 7.1 KernelConfig 与 dAct 性能差异

```cuda
// common/transpose/cast_transpose_fusion.cu (行58-100)
struct KernelConfig {
  size_t load_size = 0;
  size_t store_size = 0;
  bool valid = false;
  bool is_dact = false;   // dAct 融合标志
  size_t num_blocks = 0;

  size_t active_sm_count = 0;
  size_t elements_per_load = 0;
  size_t elements_per_load_dact = 0;  // dAct 路径额外开销
  size_t elements_per_store_c = 0;
  size_t elements_per_store_t = 0;

  KernelConfig(size_t row_length, size_t num_rows, size_t itype_size, 
               size_t itype2_size, size_t otype_size, 
               size_t load_size_, size_t store_size_, size_t sm_count,
               bool is_dact_)
      : load_size{load_size_}, store_size{store_size_}, is_dact{is_dact_} {

    // ===== dAct 融合时降低向量化大小（寄存器压力） =====
    // dAct kernel 计算 activation(x) 导数，需要额外寄存器存储中间值
    if (is_dact) {
      constexpr size_t desired_load_size_dact = 4;      // FP32 往往 <= 4 bytes/thread
      constexpr size_t desired_store_size_dact = 4;
      if (load_size > desired_load_size_dact || 
          store_size > desired_store_size_dact) {
        return;  // 配置过激进，对于 dAct 不可行
      }
    }

    // ===== 标准对齐检查 =====
    constexpr size_t cache_line_size = 128;
    if (load_size % itype_size != 0 || store_size % otype_size != 0 ||
        cache_line_size % itype_size != 0 || cache_line_size % otype_size != 0) {
      return;
    }

    const size_t tile_size_x = (load_size * THREADS_PER_WARP) / itype_size;
    const size_t tile_size_y = (store_size * THREADS_PER_WARP) / otype_size;
    const size_t num_tiles_x = row_length / tile_size_x;
    const size_t num_tiles_y = num_rows / tile_size_y;

    valid = (row_length % tile_size_x == 0 && num_rows % tile_size_y == 0);
    if (!valid) return;

    num_blocks = num_tiles_x * num_tiles_y;
    constexpr size_t warps_per_sm = 8;  // dAct kernel 占用更多寄存器，warps/SM 降低
    active_sm_count = std::min(DIVUP(num_blocks * n_warps_per_tile, warps_per_sm), sm_count);

    elements_per_load = std::min(cache_line_size, tile_size_x * itype_size) / itype_size;
    // dAct 额外加载：激活输入张量 (itype2_size)
    elements_per_load_dact = std::min(cache_line_size, tile_size_x * itype2_size) / itype2_size;
    elements_per_store_c = std::min(cache_line_size, tile_size_x * otype_size) / otype_size;
    elements_per_store_t = std::min(cache_line_size, tile_size_y * otype_size) / otype_size;
  }
};
```

### 7.2 Reduce DBias 两阶段化简（Cooperative Grid）

```cuda
// common/transpose/cast_transpose_fusion.cu 中虚拟代码
// 当 IS_DBIAS=true 时，需要按列化简梯度偏差

// ===== 第 1 阶段：每个 block 计算局部 dbias，写到 workspace =====
__shared__ float dbias_shared[256];  // 共享内存化简缓冲

// 每线程处理 1-2 列，累加行向量
float local_sum = 0.f;
for (int row = 0; row < num_rows; row += block_rows) {
    float val = input[row * num_cols + col_idx];
    // 应用 activation 导数（若 IS_DACT）
    if constexpr (IS_DACT) {
      float act_input = activation_input[row * num_cols + col_idx];
      val *= compute_dact(act_input);  // dGeLU/dReLU/dSiLU
    }
    local_sum += val;
}

// Warp-level 化简
for (int delta = 16; delta > 0; delta /= 2) {
    local_sum += __shfl_down_sync(0xFFFFFFFF, local_sum, delta);
}

// Block-level 化简到 shared memory
if (threadIdx.x % 32 == 0) {
    dbias_shared[threadIdx.x / 32] = local_sum;
}
__syncthreads();

// 单线程线性化简
if (threadIdx.x == 0) {
    float final_sum = 0.f;
    for (int i = 0; i < block_rows / 32; i++) {
      final_sum += dbias_shared[i];
    }
    // 原子加到 workspace
    atomicAdd(dbias_workspace + col_idx, final_sum);
}

// ===== 第 2 阶段：全局同步后，reduce workspace 到 dbias =====
// 需要额外的 reduce kernel（或使用 CUDA 12+ NVIDIA Graphs 的 cooperative grid）
__global__ void reduce_dbias_kernel(float *dbias_workspace, float *dbias, 
                                    size_t num_cols, size_t grid_size) {
  size_t col = blockIdx.x * blockDim.x + threadIdx.x;
  if (col < num_cols) {
    float sum = 0.f;
    // 累加 workspace 中所有 block 的局部贡献
    for (int i = 0; i < grid_size; i++) {
      sum += dbias_workspace[i * num_cols + col];
    }
    dbias[col] = sum;
  }
}
```

**两阶段设计**：
1. **局部化简**：每 block 内并行累加，写到 workspace（使用 atomicAdd）
2. **全局化简**：单独 kernel 汇总 workspace 结果到最终 dbias，减少 atomicAdd 竞争

### 7.3 RTC (Runtime Compilation) 何时启用

```cuda
// common/transpose/cast_transpose_fusion.cu 包含处
#include "string_code_transpose_rtc_cast_transpose_fusion_cu.h"

// RTC 决策逻辑
if (/* tensor shape 不在编译时已知 */ shape_is_dynamic ||
    /* 需要激活导数融合 */ is_dact ||
    /* 自定义激活函数 */ custom_activation_op) {

  // ===== 启用 RTC：动态生成 CUDA 代码 =====
  // 优势：完全展开 loop，激活函数内联，无分支
  std::string code = string_code_transpose_rtc_cast_transpose_fusion_cu;

  // 替换模板参数
  code = replace_template(code, "{{LOAD_SIZE}}", std::to_string(selected_config.load_size));
  code = replace_template(code, "{{STORE_SIZE}}", std::to_string(selected_config.store_size));
  code = replace_template(code, "{{ACTIVATION_OP}}", activation_op_code);

  // 编译 CUDA 源代码为 PTX，再加载为 cubin
  nvrtcProgram prog;
  nvrtcCreateProgram(&prog, code.c_str(), "cast_transpose_fusion.cu", ...);
  nvrtcCompileProgram(prog, ...);

  // 获取 PTX，加载到 CUDA context
  size_t ptx_size;
  nvrtcGetPTXSize(prog, &ptx_size);
  char *ptx = new char[ptx_size];
  nvrtcGetPTX(prog, ptx);

  CUmodule module;
  cuModuleLoadDataEx(&module, ptx, ...);

  CUfunction kernel;
  cuModuleGetFunction(&kernel, module, "cast_transpose_fusion_kernel");

  // Launch kernel
  cuLaunchKernel(kernel, grid.x, grid.y, grid.z, block.x, block.y, block.z,
                 0, stream, args, nullptr);
} else {
  // ===== 静态编译：预编译多个配置版本 =====
  // 根据 load_size, store_size, is_dact 选择预编译 kernel
  switch (selected_config.load_size) {
    case 4:
      if (selected_config.store_size == 4) {
        if (is_dact) {
          kernel_cast_transpose_dact_load4_store4<<<grid, block, 0, stream>>>(args);
        } else {
          kernel_cast_transpose_load4_store4<<<grid, block, 0, stream>>>(args);
        }
      }
      break;
    case 8:
      // ... 其他配置
      break;
  }
}
```

**RTC 时机**：
- **动态 shape**：编译时无法决定 tile 大小
- **自定义激活函数**：无法预编译所有组合
- **性能关键路径**：少数 critical path 可接受 RTC 编译延迟
- **预计收益**：loop unroll + 激活内联 = 5-15% 性能提升

