## 8. NVFP4 Vector-Blockwise Cast+Transpose

### 8.1 FP4 Vector-Blockwise 架构

```cuda
// common/transpose/quantize_transpose_vector_blockwise_fp4.cu 关键部分
// FP4 量化与转置同时进行：输出同时包含 row-major 和 col-major 布局

__global__ void quantize_transpose_vector_blockwise_fp4_kernel(
    const float *__restrict__ input,          // 行主输入
    uint8_t *__restrict__ output_rowwise,     // 行主 FP4（nibble packed）
    uint8_t *__restrict__ output_colwise,     // 列主 FP4（nibble packed）
    const float *__restrict__ scale,          // per-block 缩放因子
    size_t num_rows, size_t num_cols) {

  // ===== 块配置：每块处理 32x32 FP4 值 (16x16 bytes) =====
  constexpr int BLOCK_DIM = 32;
  constexpr int BLOCK_SIZE = 256;  // 8 warps
  static_assert(BLOCK_DIM * BLOCK_DIM / 2 == BLOCK_SIZE);

  int tile_row = blockIdx.y;
  int tile_col = blockIdx.x;

  // ===== 步骤 1: 加载 32x32 tile 到共享内存 =====
  __shared__ float sh_input[BLOCK_DIM][BLOCK_DIM + 1];  // +1 padding
  __shared__ uint8_t sh_output_rowwise[BLOCK_DIM][BLOCK_DIM / 2];
  __shared__ uint8_t sh_output_colwise[BLOCK_DIM][BLOCK_DIM / 2];

  // 32x32 tile = 1024 元素，256 线程，每线程 4 个 F32
  for (int i = 0; i < 4; i++) {
    int global_row = tile_row * BLOCK_DIM + (threadIdx.x / 32);
    int global_col = tile_col * BLOCK_DIM + (threadIdx.x % 32) + i * 8;

    if (global_row < num_rows && global_col < num_cols) {
      sh_input[threadIdx.x / 32][threadIdx.x % 32 + i * 8] = 
          input[global_row * num_cols + global_col];
    } else {
      sh_input[threadIdx.x / 32][threadIdx.x % 32 + i * 8] = 0.f;
    }
  }
  __syncthreads();

  // ===== 步骤 2: Cast 到 FP4 + Pack 成 nibble =====
  // 缩放因子：per-block E8M0 值
  float block_scale = scale[tile_row * ((num_cols + BLOCK_DIM - 1) / BLOCK_DIM) + tile_col];
  float2 scale_pair = make_float2(block_scale, block_scale);

  // 每线程处理 4 个 FP32 -> 1 个 byte (2 nibble)
  for (int row = threadIdx.x / BLOCK_DIM; row < BLOCK_DIM; row += 8) {
    for (int col = (threadIdx.x % BLOCK_DIM) * 4; col < BLOCK_DIM; col += 256 * 4) {
      // 4 个 F32 值
      float2 in01 = make_float2(sh_input[row][col], sh_input[row][col+1]);
      float2 in23 = make_float2(sh_input[row][col+2], sh_input[row][col+3]);
      uint32_t rbits = 0;  // 无随机舍入

      // PTX mul_cvt: 4 x F32 * scale -> 4 x 4-bit (1 byte)
      auto packed = ptx::mul_cvt_fp32_to_fp4_4x(in01, in23, scale_pair, rbits);

      // 行主布局存储
      sh_output_rowwise[row][col / 2] = packed;
    }
  }
  __syncthreads();

  // ===== 步骤 3: 转置存储到列主输出 =====
  // 从 sh_output_rowwise（行主）转置读，写到全局列主
  // 为避免 bank conflict，使用 warp-shuffle 或 tile-transpose 技巧

  // 方法 1: 线程循环化简（简单但缓慢）
  for (int row = 0; row < BLOCK_DIM; row++) {
    for (int col = threadIdx.x; col < BLOCK_DIM / 2; col += blockDim.x) {
      uint8_t val = sh_output_rowwise[row][col];

      // 转置：写到 (col*2, row) 和 (col*2+1, row)
      int global_row_t = tile_col * BLOCK_DIM + row;
      int global_col_t = tile_row * BLOCK_DIM + col * 2;

      if (global_row_t < num_rows && global_col_t < num_cols) {
        int byte_idx_colwise = (global_col_t / 2) * num_rows + global_row_t;
        output_colwise[byte_idx_colwise] = val;
      }
    }
  }
  __syncthreads();

  // ===== 步骤 4: 行主输出（直接写） =====
  for (int row = threadIdx.x / (BLOCK_DIM / 2); row < BLOCK_DIM; row += 8) {
    for (int col_byte = threadIdx.x % (BLOCK_DIM / 2); col_byte < BLOCK_DIM / 2; 
         col_byte += (BLOCK_DIM / 2)) {
      uint8_t val = sh_output_rowwise[row][col_byte];

      int global_row = tile_row * BLOCK_DIM + row;
      int global_col_byte = tile_col * (BLOCK_DIM / 2) + col_byte;

      if (global_row < num_rows && global_col_byte * 2 < num_cols) {
        int byte_idx_rowwise = global_row * ((num_cols + 1) / 2) + global_col_byte;
        output_rowwise[byte_idx_rowwise] = val;
      }
    }
  }
}
```

**双输出路径**：
- **Row-Major** (`output_rowwise`): GEMM A 矩阵左操作数，读取效率高
- **Col-Major** (`output_colwise`): GEMM B 矩阵左操作数，转置后的数据排布
- **同时生成**：避免二次转置 kernel 调用

