## 2. LayerNorm Forward Kernel - 逐行解析

### 2.1 Tuned Forward Kernel - 矢量化 + Welford 统计

```cuda
// 文件: /root/TransformerEngine/transformer_engine/common/normalization/layernorm/ln_fwd_kernels.cuh
// 行 20-100: ln_fwd_tuned_kernel 主体逻辑

template <typename Ktraits>
__global__ __launch_bounds__(Ktraits::THREADS_PER_CTA) void ln_fwd_tuned_kernel(
    ForwardKernelParams params) {
  enum { ROWS_PER_CTA = Ktraits::ROWS_PER_CTA };      // 行数/CTA
  enum { WARPS_N = Ktraits::WARPS_N };                // 列 WARP 数
  enum { WARPS_M = Ktraits::WARPS_M };                // 行 WARP 数
  enum { THREADS_PER_ROW = Ktraits::THREADS_PER_ROW };// 行方向线程
  enum { VEC_COLS_PER_LDG = Ktraits::VEC_COLS_PER_LDG };// 矢量列数
  enum { BYTES_PER_ROW = Ktraits::BYTES_PER_ROW };    // 行字节数
  enum { LDGS = Ktraits::LDGS };                      // 每线程加载数
  enum { NUM_ELTS = Ktraits::NUM_ELTS };              // 矢量元素数
  enum { CTAS_PER_ROW = Ktraits::CTAS_PER_ROW };      // 行 CTA 数

  using output_t = typename Ktraits::output_t;        // 输出类型（可能 fp8）
  using index_t = typename Ktraits::index_t;
  using compute_t = typename Ktraits::compute_t;      // 计算精度（float32）
  using Ivec = typename Ktraits::Ivec;                // 输入矢量类型
  using Ovec = typename Ktraits::Ovec;                // 输出矢量类型
  using Wvec = typename Ktraits::Wvec;                // 权重矢量类型
  using Stats = typename Ktraits::Stats;              // 统计聚合器
  using stats_t = typename Stats::stats_t;            // 统计数据结构

  extern __shared__ char smem_[];                     // 动态共享内存

  // ============ 线程 ID 映射 ============
  const index_t tidx = threadIdx.x;                   // 线程在 CTA 内的全局 ID
  const index_t bidn = blockIdx.x % CTAS_PER_ROW;    // 行内 CTA 索引
  const index_t bidm = blockIdx.x / CTAS_PER_ROW;    // 行索引
  const index_t lane = tidx % THREADS_PER_WARP;      // WARP 内线程 ID (0-31)
  const index_t warp = tidx / THREADS_PER_WARP;      // CTA 内 WARP 索引
  const index_t warp_m = warp / WARPS_N;             // 行 WARP 索引
  const index_t warp_n = warp % WARPS_N;             // 列 WARP 索引

  // 全局行号 = CTA 行号 × 行数/CTA + WARP 行号
  const index_t r = bidm * ROWS_PER_CTA + warp_m;
  // 全局列号 = CTA 列号 × 列线程数 + WARP 列号 × 32 + Lane ID
  const index_t c = bidn * THREADS_PER_ROW + warp_n * THREADS_PER_WARP + lane;

  // ============ 共享内存中的统计对象 ============
  Stats stats(params, bidm, bidn, warp_m, warp_n, lane, smem_);
  // Stats 对象处理 mean/variance 的跨线程汇总

  compute_t *mu_ptr = static_cast<compute_t *>(params.mu);      // 输出均值指针
  compute_t *rs_ptr = static_cast<compute_t *>(params.rs);      // 输出 1/sqrt(var)

  // ============ 加载 gamma 和 beta（权重）============
  Wvec gamma[LDGS];    // gamma[LDGS] 存储每个线程的权重 γ
  Wvec beta[LDGS];     // beta[LDGS] 存储每个线程的偏置 β
  index_t idx = c;
#pragma unroll
  for (int it = 0; it < LDGS; ++it) {
    gamma[it].load_from(params.gamma, idx);  // 从全局内存 coalesced 加载
    beta[it].load_from(params.beta, idx);
    idx += VEC_COLS_PER_LDG;  // 跳过其他 CTA 的列范围
  }

  constexpr compute_t rn = 1.f / compute_t(Ktraits::COLS);  // 1 / HIDDEN_SIZE

  compute_t scale = 1.f;
  if (params.fp8_out) {
    scale = *reinterpret_cast<compute_t *>(params.scale);  // FP8 缩放因子
  }
  compute_t amax = 0;                                        // FP8 绝对值最大值
  const bool requires_amax = params.amax != nullptr;         // 是否计算 amax

  // ============ 主循环：遍历行 (Grid stride loop) ============
  for (int row = r; row < params.rows; row += params.ctas_per_col * ROWS_PER_CTA) {
    // row 跨越的距离 = CTA 网格的行覆盖数 × 每 CTA 行数
    // 这样多个网格可以分担所有行

    // ============ 阶段 1: 加载输入、FP16→FP32 转换 ============
    Ivec x[LDGS];                        // 输入矢量缓存
    index_t idx = row * Ktraits::VEC_COLS + c;
    compute_t xf[LDGS * NUM_ELTS];      // 转换后的 FP32 值
#pragma unroll
    for (int it = 0; it < LDGS; it++) {
      x[it].load_from(params.x, idx);   // 矢量化 LDG（通常 128 位对齐）
#pragma unroll
      for (int jt = 0; jt < NUM_ELTS; jt++) {
        compute_t x_ij = compute_t(x[it].data.elt[jt]);  // FP16/BF16 → FP32
        xf[it * NUM_ELTS + jt] = x_ij;
      }
      idx += VEC_COLS_PER_LDG;
    }

    // ============ 阶段 2: Welford 在线均值方差计算 ============
    // stats.compute() 内部使用 Welford 算法：
    // M_k = M_{k-1} + (x_k - M_{k-1}) / k
    // M2_k = M2_{k-1} + (x_k - M_{k-1}) * (x_k - M_k)
    // variance = M2 / n
    stats_t s = stats.compute(xf, rn);  // rn = 1/HIDDEN_SIZE

    compute_t mu = Get<0>::of<stats_t, compute_t>(s);  // 提取 mean
    compute_t m2 = Get<1>::of<stats_t, compute_t>(s);  // 提取 sum((x-mu)^2)

    // ============ 阶段 3: 将统计值存入全局内存（仅 lane 0）============
    if (bidn == 0 && warp_n == 0 && lane == 0) {
      mu_ptr[row] = mu;                 // 同步点：不同 CTA 可能重写，需 atomicAdd
    }

    // ============ 阶段 4: 计算标准化因子 rs = 1/sqrt(var + eps) ============
    compute_t rs = rsqrtf(rn * m2 + params.epsilon);
    // 使用 rsqrtf() 得到高精度的倒数平方根

    if (bidn == 0 && warp_n == 0 && lane == 0) {
      rs_ptr[row] = rs;
    }
```

**关键算法细节**：

1. **矢量化加载 (Vectorized LDG)**
   - 使用 `Ivec::load_from()` 进行 128 位对齐加载，减少指令数和延迟
   - 每次加载 `NUM_ELTS` 个元素（通常 8 个 FP16）

2. **Welford 在线统计**
   - `stats.compute(xf, rn)` 在一个 WARP 内计算均值和方差
   - 使用 shuffle 操作进行 intra-warp reduce，避免 shared memory bank conflict

3. **多 CTA 同步**
   - `bidn == 0 && warp_n == 0 && lane == 0` 保证只有一个线程写入 mu/rs
   - 当 `CTAS_PER_ROW > 1` 时，需要使用 cooperative barrier 同步多个 CTA

