### 2.2 Forward Kernel 的 Normalization 和 Output 阶段

```cuda
// 行 110-160: 规范化输出 + FP8 转换 + amax 计算

    Ovec z[LDGS];                       // 输出矢量缓存
    idx = row * Ktraits::VEC_COLS + c;
#pragma unroll
    for (int it = 0; it < LDGS; it++) {
#pragma unroll
      for (int jt = 0; jt < NUM_ELTS; jt++) {
        // ============ LN 公式: y = (x - mu) / sqrt(var + eps) ============
        compute_t y_ij = rs * (xf[it * NUM_ELTS + jt] - mu);

        // ============ Scale + Shift: output = gamma * y + beta ============
        compute_t g_ij = gamma[it].data.elt[jt];
        if (params.zero_centered_gamma) {
          g_ij += 1;  // gamma 可以被 init 为 0，此时实际 γ = 1 + 0 = 1
        }
        compute_t b_ij = beta[it].data.elt[jt];
        compute_t temp_output = g_ij * y_ij + b_ij;

        // ============ 计算 amax（用于 FP8 动态范围） ============
        if (requires_amax) {
          __builtin_assume(amax >= 0);  // 编译器提示 amax 非负
          if (params.fp8_out) {
            // FP8 输出：在缩放前计算 amax（高精度）
            amax = fmaxf(amax, fabsf(temp_output));
          } else {
            // BF16/FP16 输出：先转换再计算 amax（考虑精度损失）
            output_t out_t_val = output_t(temp_output);
            amax = fmaxf(amax, fabsf(compute_t(out_t_val)));
          }
        }

        // ============ FP8 缩放 ============
        if (params.fp8_out) {
          temp_output = temp_output * scale;  // scale = 1 / max_abs_val
        }

        z[it].data.elt[jt] = output_t(temp_output);  // FP32 → FP8/BF16
      }
      z[it].store_to(params.z, idx);     // 矢量化 STG
      idx += VEC_COLS_PER_LDG;
    }
  }

  // ============ 块级 amax 归并 + atomicMax ============
  if (requires_amax) {
    // 使用 shfl_down 在 block 内进行 reduction（类似 warp reduce）
    amax = reduce_max<WARPS_M * WARPS_N>(amax, warp);
    if (threadIdx.x == 0) {
      static_assert(std::is_same<compute_t, float>::value);
      // atomicMaxFloat 原子操作更新全局 amax（多 CTA 安全）
      atomicMaxFloat(reinterpret_cast<compute_t *>(params.amax), amax);
    }
  }

  // ============ 计算 scale_inv = 1 / scale（仅一次，block(0,0) 的 thread(0)） ============
  if (params.fp8_out) {
    if (blockIdx.x == 0 && threadIdx.x == 0 && params.scale_inv != nullptr) {
      reciprocal<compute_t>(reinterpret_cast<compute_t *>(params.scale_inv), scale);
    }
  }
}
```

**关键点**：
- `amax` 归并使用 `reduce_max`，必须先从 float 转换为输出类型再反转
- `atomicMaxFloat` 允许多个 block 竞争更新全局 amax
- `scale_inv` 仅由单个线程计算一次，用于 backward

