20. template <typename Ktraits>
21. __global__ __launch_bounds__(Ktraits::THREADS_PER_CTA) void ln_fwd_tuned_kernel(
22.     ForwardKernelParams params) {
23.   enum { ROWS_PER_CTA = Ktraits::ROWS_PER_CTA };
24.   enum { WARPS_N = Ktraits::WARPS_N };
25.   enum { WARPS_M = Ktraits::WARPS_M };
26.   enum { THREADS_PER_ROW = Ktraits::THREADS_PER_ROW };
27.   enum { VEC_COLS_PER_LDG = Ktraits::VEC_COLS_PER_LDG };
28.   enum { BYTES_PER_ROW = Ktraits::BYTES_PER_ROW };
29.   enum { LDGS = Ktraits::LDGS };
30.   enum { NUM_ELTS = Ktraits::NUM_ELTS };
31.   enum { CTAS_PER_ROW = Ktraits::CTAS_PER_ROW };
32. 
33.   using output_t = typename Ktraits::output_t;
34.   using index_t = typename Ktraits::index_t;
35.   using compute_t = typename Ktraits::compute_t;
36.   using Ivec = typename Ktraits::Ivec;
37.   using Ovec = typename Ktraits::Ovec;
38.   using Wvec = typename Ktraits::Wvec;
39. 
40.   using Stats = typename Ktraits::Stats;
41.   using stats_t = typename Stats::stats_t;
42. 
43.   extern __shared__ char smem_[];
44. 
45.   const index_t tidx = threadIdx.x;
46.   const index_t bidn = blockIdx.x % CTAS_PER_ROW;
47.   const index_t bidm = blockIdx.x / CTAS_PER_ROW;
48.   const index_t lane = tidx % THREADS_PER_WARP;
49.   const index_t warp = tidx / THREADS_PER_WARP;
50.   const index_t warp_m = warp / WARPS_N;
51.   const index_t warp_n = warp % WARPS_N;
52. 
53.   const index_t r = bidm * ROWS_PER_CTA + warp_m;
54.   const index_t c = bidn * THREADS_PER_ROW + warp_n * THREADS_PER_WARP + lane;
55. 
56.   Stats stats(params, bidm, bidn, warp_m, warp_n, lane, smem_);
57. 
58.   compute_t *mu_ptr = static_cast<compute_t *>(params.mu);
59.   compute_t *rs_ptr = static_cast<compute_t *>(params.rs);
60. 
61.   Wvec gamma[LDGS];
62.   Wvec beta[LDGS];
63.   index_t idx = c;
64. #pragma unroll
65.   for (int it = 0; it < LDGS; ++it) {
66.     gamma[it].load_from(params.gamma, idx);
67.     beta[it].load_from(params.beta, idx);
68.     idx += VEC_COLS_PER_LDG;
69.   }
70. 
71.   constexpr compute_t rn = 1.f / compute_t(Ktraits::COLS);
72. 
73.   compute_t scale = 1.f;
74.   if (params.fp8_out) {
75.     scale = *reinterpret_cast<compute_t *>(params.scale);
76.   }
77.   compute_t amax = 0;
78.   const bool requires_amax = params.amax != nullptr;
79. 
80.   for (int row = r; row < params.rows; row += params.ctas_per_col * ROWS_PER_CTA) {
81.     Ivec x[LDGS];
82.     index_t idx = row * Ktraits::VEC_COLS + c;
83.     compute_t xf[LDGS * NUM_ELTS];
84. #pragma unroll
85.     for (int it = 0; it < LDGS; it++) {
86.       x[it].load_from(params.x, idx);
87. #pragma unroll
88.       for (int jt = 0; jt < NUM_ELTS; jt++) {
89.         compute_t x_ij = compute_t(x[it].data.elt[jt]);
90.         xf[it * NUM_ELTS + jt] = x_ij;
91.       }
92.       idx += VEC_COLS_PER_LDG;
93.     }
94. 
95.     stats_t s = stats.compute(xf, rn);
96. 
97.     compute_t mu = Get<0>::of<stats_t, compute_t>(s);
98.     compute_t m2 = Get<1>::of<stats_t, compute_t>(s);
99. 
100.     if (bidn == 0 && warp_n == 0 && lane == 0) {
101.       mu_ptr[row] = mu;
102.     }
103. 
104.     compute_t rs = rsqrtf(rn * m2 + params.epsilon);
105. 
106.     if (bidn == 0 && warp_n == 0 && lane == 0) {
107.       rs_ptr[row] = rs;
108.     }
109. 
110.     Ovec z[LDGS];
111.     idx = row * Ktraits::VEC_COLS + c;
112. #pragma unroll
113.     for (int it = 0; it < LDGS; it++) {
114. #pragma unroll
115.       for (int jt = 0; jt < NUM_ELTS; jt++) {
116.         compute_t y_ij = rs * (xf[it * NUM_ELTS + jt] - mu);
117.         compute_t g_ij = gamma[it].data.elt[jt];
118.         if (params.zero_centered_gamma) {
119.           g_ij += 1;
120.         }

80.  * Block dims: bsize x 1 x 1
81.  *
82.  * Grid dims: num_scales x 1 x 1
83.  */
84. __global__ void __launch_bounds__(bsize)
85.     kernel(const float* amax_history_ptr, const float* scale_ptr, float* updated_amax_history_ptr,
86.            float* updated_scale_ptr, size_t amax_history_length, size_t amax_history_stride,
87.            AmaxComputeAlgo amax_compute_algo, float scaled_max) {
88.   const size_t tid = threadIdx.x;
89.   const size_t bid = blockIdx.x;
90. 
91.   // Update amax
92.   float amax = 0;
93.   {
94.     // Roll amax history
95.     const auto* amax_history = amax_history_ptr + bid;
96.     auto* updated_amax_history = updated_amax_history_ptr + bid;
97.     const auto last_amax = amax_history[0];
98.     const auto& length = amax_history_length;
99.     const auto& stride = amax_history_stride;
100.     for (size_t off = 0; off < length; off += bsize) {
101.       const size_t i = off + tid;
102.       float a = 0;
103.       if (i < length) {
104.         a = (i < length - 1) ? amax_history[(i + 1) * stride] : last_amax;
105.         amax = fmaxf(amax, a);
106.       }
107.       __syncthreads();  // In case roll is in-place
108.       if (i < length) {
109.         updated_amax_history[i * stride] = (i > 0) ? a : 0;
110.       }
111.     }
112. 
113.     // Compute amax to use for scaling factor
114.     switch (amax_compute_algo) {
115.       case AmaxComputeAlgo::MOST_RECENT:
116.         amax = last_amax;
117.         break;
118.       case AmaxComputeAlgo::MAX: {
119.         __shared__ float shared_amax[bsize];
120.         shared_amax[tid] = amax;
121.         __syncthreads();
122. #pragma unroll
123.         for (size_t off = bsize / 2; off > 0; off /= 2) {
124.           if (tid < off) {
125.             shared_amax[tid] = fmaxf(shared_amax[tid], shared_amax[tid + off]);
126.           }
127.           __syncthreads();
128.         }
129.         amax = shared_amax[tid];
130.       } break;
131.       default:
132.         amax = 0;
133.     }
134.   }
135. 
136.   // Update scale
137.   if (tid == 0) {
138.     // Update scale
139.     float scale;
140.     if (isfinite(amax) && amax > 0) {
141.       scale = scaled_max / amax;
142.     } else {
143.       scale = scale_ptr[bid];
144.     }
145.     // When the amax is too tiny that the scale becoming infinite in FP32,
146.     // we set the scale to the max value of FP32. In this case, the tensor’s
147.     // amax won't get mapped to the FP8 max representable, but rather
148.     // something below that, but this is the best thing we can do.
149.     if (isinf(scale)) {
150.       scale = std::numeric_limits<float>::max();
151.     }
152.     updated_scale_ptr[bid] = scale;
153.   }
154. }
