156. /* CUDA kernel to bulk-update amax history and FP8 scaling factors
157.  *
158.  * Block dims: bsize x 1 x 1
159.  *
160.  * Grid dims: num_tensors x 1 x 1
161.  */
162. __global__ void __launch_bounds__(bsize)
163.     kernel_bulk(float* amax_reduction_buffer, AmaxParams p, size_t amax_history_length,
164.                 AmaxComputeAlgo amax_compute_algo, float scaled_max) {
165.   const size_t bid = blockIdx.x;
166.   const size_t tid = threadIdx.x;
167.   const int num_scale = p.param[bid].num_scale;
168. 
169.   int offset_in_buffer = 0;
170.   for (int j = 0; j < bid; j++) {
171.     offset_in_buffer += p.param[j].num_scale;
172.   }
173. 
174.   for (int count = 0; count < num_scale; count++) {
175.     // Update amax
176.     float amax = 0;
177.     {
178.       // Roll amax history
179.       const auto& length = amax_history_length;
180.       const auto& stride = p.param[bid].num_scale;
181.       auto* amax_history = p.param[bid].amax_history + count;
182.       const auto last_amax = ((amax_reduction_buffer != nullptr) &&
183.                               (amax_reduction_buffer[offset_in_buffer + count] != 0.0f))
184.                                  ? amax_reduction_buffer[offset_in_buffer + count]
185.                                  : amax_history[0];
186.       if (last_amax != 0.0f) {
187.         for (size_t off = 0; off < length; off += bsize) {
188.           const size_t i = off + tid;
189.           float a = 0;
190.           if (i < length) {
191.             a = (i < length - 1) ? amax_history[(i + 1) * stride] : last_amax;
192.             amax = fmaxf(amax, a);
193.           }
194.           __syncthreads();  // Inplace roll
195.           if (i < length) {
196.             amax_history[i * stride] = (i > 0) ? a : 0;
197.           }
198.         }
199.       }
