30. /* Performance heuristics for optimized kernel parameters */
31. struct KernelConfig {
32.   /** Vector load size */
33.   size_t load_size = 0;
34.   /** Vector store size to transposed output */
35.   size_t store_size = 0;
36. 
37.   /* Whether config is valid */
38.   bool valid = false;
39.   /* Number of CUDA blocks */
40.   size_t num_blocks = 0;
41. 
42.   /* Number of active SMs */
43.   size_t active_sm_count = 0;
44.   /* Elements per L1 cache load */
45.   size_t elements_per_load = 0;
46.   /* Elements per L1 cache store to cast output*/
47.   size_t elements_per_store_c = 0;
48.   /* Elements per L1 cache store to transposed output */
49.   size_t elements_per_store_t = 0;
50. 
51.   KernelConfig(size_t row_length, size_t num_rows, size_t itype_size, size_t otype_size,
52.                size_t load_size_, size_t store_size_, size_t sm_count)
53.       : load_size{load_size_}, store_size{store_size_} {
54.     // Check that tiles are correctly aligned
55.     constexpr size_t cache_line_size = 128;
56.     if (load_size % itype_size != 0 || store_size % otype_size != 0 ||
57.         cache_line_size % itype_size != 0 || cache_line_size % otype_size != 0) {
58.       return;
59.     }
60.     const size_t row_tile_elements = load_size * THREADS_PER_WARP / itype_size;
61.     const size_t col_tile_elements = store_size * THREADS_PER_WARP / otype_size;
62.     valid = (row_length % row_tile_elements == 0 && num_rows % col_tile_elements == 0);
63.     if (!valid) {
64.       return;
65.     }
66. 
67.     // Number of CUDA blocks
68.     num_blocks = (row_length / row_tile_elements) * (num_rows / col_tile_elements);
69. 
70.     // Parameters for performance model
71.     constexpr size_t warps_per_sm = 16;  // Rough estimate for saturated SMs
72.     active_sm_count = std::min(DIVUP(num_blocks * warps_per_tile, warps_per_sm), sm_count);
73.     elements_per_load = (std::min(cache_line_size, row_tile_elements * itype_size) / itype_size);
74.     elements_per_store_c = (std::min(cache_line_size, row_tile_elements * otype_size) / otype_size);
75.     elements_per_store_t = (std::min(cache_line_size, col_tile_elements * otype_size) / otype_size);
76.   }
77. 
78.   /* Compare by estimated cost */
79.   bool operator<(const KernelConfig &other) const {
80.     if (this->valid && other.valid) {
81.       // cost ~ (1/elements_per_load
82.       //         + 1/elements_per_store_c
83.       //         + 1/elements_per_store_t) / active_sms
84.       // Note: Integer arithmetic ensures stable ordering
85.       const auto &l1 = this->elements_per_load;
86.       const auto &sc1 = this->elements_per_store_c;
87.       const auto &st1 = this->elements_per_store_t;
88.       const auto &p1 = this->active_sm_count;
89.       const auto &l2 = other.elements_per_load;
90.       const auto &sc2 = other.elements_per_store_c;
91.       const auto &st2 = other.elements_per_store_t;
92.       const auto &p2 = other.active_sm_count;
93.       const auto scale = l1 * sc1 * st1 * p1 * l2 * sc2 * st2 * p2;
94.       const auto cost1 = (scale / l1 + scale / sc1 + scale / st1) / p1;
95.       const auto cost2 = (scale / l2 + scale / sc2 + scale / st2) / p2;
96.       return cost1 < cost2;
97.     } else {
98.       return this->valid && !other.valid;
99.     }
100.   }

