77. template <typename acc_t, int WARP_BATCH, int WARP_SIZE, template <typename> class ReduceOp>
78. __device__ __forceinline__ void warp_reduce(acc_t *sum) {
79.   ReduceOp<acc_t> r;
80. #pragma unroll
81.   for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
82. #pragma unroll
83.     for (int i = 0; i < WARP_BATCH; ++i) {
84.       acc_t b = WARP_SHFL_XOR_NATIVE(sum[i], offset, WARP_SIZE);
85.       sum[i] = r(sum[i], b);
86.     }
87.   }
