94. template <typename input_t, typename output_t, typename acc_t, int log2_elements>
95. __global__ void scaled_softmax_warp_forward(output_t *dst, const input_t *src, const acc_t scale,
96.                                             int micro_batch_size, int element_count) {
97.   // WARP_SIZE and WARP_BATCH must match the return values batches_per_warp and
98.   // warp_size of method warp_softmax_forward_kernel.
99.   constexpr int next_power_of_two = 1 << log2_elements;
100.   constexpr int WARP_SIZE =

100.   constexpr int WARP_SIZE =
101.       (next_power_of_two < THREADS_PER_WARP) ? next_power_of_two : THREADS_PER_WARP;
102.   constexpr int WARP_ITERATIONS = next_power_of_two / WARP_SIZE;
103.   constexpr int WARP_BATCH = (next_power_of_two <= 128) ? 2 : 1;
104.   constexpr int ELEMENTS_PER_LDG_STG = (WARP_ITERATIONS < 4) ? 1 : 4;
105. 
106.   // blockDim/threadIdx = (WARP_SIZE, WARPS_PER_BLOCK, )
107.   // gridDim/blockIdx = (seq_len, attn_heads, batches)
108.   size_t first_batch =
109.       (blockDim.y * (blockIdx.x + gridDim.x * (blockIdx.y + gridDim.y * blockIdx.z)) +
110.        threadIdx.y) *
111.       WARP_BATCH;
112. 
113.   // micro_batch_size might not be a multiple of WARP_BATCH. Check how
114.   // many batches have to computed within this WARP.
115.   int local_batches = micro_batch_size - first_batch;
116.   if (local_batches > WARP_BATCH) local_batches = WARP_BATCH;
117. 
118.   // there might be multiple batches per warp. compute the index within the batch
119.   int local_idx = threadIdx.x;
120. 
121.   size_t thread_offset = first_batch * element_count + ELEMENTS_PER_LDG_STG * local_idx;
122.   src += thread_offset;
123.   dst += thread_offset;
124. 
125.   // load data from global memory
126.   acc_t elements[WARP_BATCH][WARP_ITERATIONS];
127.   input_t temp_data[ELEMENTS_PER_LDG_STG];
128. #pragma unroll
129.   for (int i = 0; i < WARP_BATCH; ++i) {
130.     int batch_element_count = (i >= local_batches) ? 0 : element_count;
131. 
132. #pragma unroll
133.     for (int it = 0; it < WARP_ITERATIONS; it += ELEMENTS_PER_LDG_STG) {
134.       int element_index = ELEMENTS_PER_LDG_STG * local_idx + it * WARP_SIZE;
135. 
136.       if (element_index < batch_element_count) {
137.         int itr_idx = i * element_count + it * WARP_SIZE;
138.         copy_vector<input_t, ELEMENTS_PER_LDG_STG>(temp_data, src + itr_idx);
139. 
140. #pragma unroll
141.         for (int element = 0; element < ELEMENTS_PER_LDG_STG; ++element) {
142.           elements[i][it + element] = (acc_t)temp_data[element] * scale;
143.         }
144.       } else {
145. #pragma unroll
146.         for (int element = 0; element < ELEMENTS_PER_LDG_STG; ++element) {
147.           elements[i][it + element] = -std::numeric_limits<acc_t>::infinity();
148.         }
149.       }
150.     }
151.   }
152. 
153.   // compute max_value
154.   acc_t max_value[WARP_BATCH];
155. #pragma unroll
156.   for (int i = 0; i < WARP_BATCH; ++i) {
157.     max_value[i] = elements[i][0];
158. #pragma unroll
159.     for (int it = 1; it < WARP_ITERATIONS; ++it) {
160.       max_value[i] = (max_value[i] > elements[i][it]) ? max_value[i] : elements[i][it];
161.     }
162.   }
163.   warp_reduce<acc_t, WARP_BATCH, WARP_SIZE, Max>(max_value);
164. 
165.   acc_t sum[WARP_BATCH]{0.0f};
166. #pragma unroll
167.   for (int i = 0; i < WARP_BATCH; ++i) {
168. #pragma unroll
169.     for (int it = 0; it < WARP_ITERATIONS; ++it) {
170.       elements[i][it] = std::exp((elements[i][it] - max_value[i]));
171.       sum[i] += elements[i][it];
172.     }
173.   }
174.   warp_reduce<acc_t, WARP_BATCH, WARP_SIZE, Add>(sum);
175. 
176.   // store result
177.   output_t out[ELEMENTS_PER_LDG_STG];
178. #pragma unroll
179.   for (int i = 0; i < WARP_BATCH; ++i) {
180.     if (i >= local_batches) break;
181. #pragma unroll
182.     for (int it = 0; it < WARP_ITERATIONS; it += ELEMENTS_PER_LDG_STG) {
183.       int element_index = ELEMENTS_PER_LDG_STG * local_idx + it * WARP_SIZE;
184.       if (element_index < element_count) {
