25.      * Section: Global Variables/Addresses init
26.      * - Each warp is responsible for one token, and has own shared memory buffer.
27.      *   Then __syncwarp() is used instead of __syncthreads()
28.      */
29.   // Used variables/addresses init
30.   int num_token_per_block = blockDim.x / kThreadsPerWarp;
31.   int warp_id = threadIdx.x / kThreadsPerWarp;
32.   int lane_id = threadIdx.x % kThreadsPerWarp;
33.   extern __shared__ float shmem[];
