35.   CompType *topk_scores_buf = scores_buf + num_experts * num_token_per_block;
36.   CompType *group_scores_buf = nullptr, *masked_scores_buf = nullptr;
37.   int *topk_indices_buf = nullptr;
38.   if (group_topk > 0) {
39.     masked_scores_buf = topk_scores_buf + topk * num_token_per_block;
40.     group_scores_buf = masked_scores_buf + num_experts * num_token_per_block;
41.     topk_indices_buf = reinterpret_cast<int *>(group_scores_buf + num_groups * num_token_per_block);
42.   } else {
43.     topk_indices_buf = reinterpret_cast<int *>(topk_scores_buf + topk * num_token_per_block);
44.   }
45.   // The address of buffers on the current warp
46.   CompType *scores = scores_buf + warp_id * num_experts;
47.   CompType *topk_scores = topk_scores_buf + warp_id * topk;
48.   CompType *masked_scores = masked_scores_buf + warp_id * num_experts;
49.   CompType *group_scores = group_scores_buf + warp_id * num_groups;
50.   int *topk_indices = topk_indices_buf + warp_id * topk;
51. 
52.   /***
53.      * Section: Main Loop
54.      * - Each warp is responsible for one token
55.      */
