667.         operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_DATA_TYPE, &aux_type, sizeof(aux_type)));
668.   } else if (bias) {
669.     if (grad) {
670.       // grad output is always input B
671.       epilogue = CUBLASLT_EPILOGUE_BGRADB;
672.     } else {
673.       epilogue = CUBLASLT_EPILOGUE_BIAS;
674.     }
675.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
676.         operationDesc, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias_ptr, sizeof(bias_ptr)));
677.   } else if (gelu) {
678.     if (grad) {
679.       epilogue = CUBLASLT_EPILOGUE_DGELU;
680.     } else {
681.       epilogue = CUBLASLT_EPILOGUE_GELU_AUX;
682.     }
683.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc,
684.                                                      CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_POINTER,
685.                                                      &pre_gelu_out, sizeof(pre_gelu_out)));
686.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
687.         operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_LD, &ld_gelumat, sizeof(ld_gelumat)));
688.     const cudaDataType_t aux_type = get_cuda_dtype(outputPreGelu->data.dtype);
689.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
690.         operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_DATA_TYPE, &aux_type, sizeof(aux_type)));
691.   }
692. 
693.   if ((inputA->scaling_mode == NVTE_BLOCK_SCALING_1D) ||
694.       (inputA->scaling_mode == NVTE_BLOCK_SCALING_2D)) {
695.     NVTE_CHECK((epilogue == CUBLASLT_EPILOGUE_DEFAULT || epilogue == CUBLASLT_EPILOGUE_BIAS ||
696.                 epilogue == CUBLASLT_EPILOGUE_DGELU),
697.                "Epilogue requested outside of the available and tested cuBLAS functionality for "
698.                "float8 block scaled GEMM");
699.   }
700. 
701.   NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_EPILOGUE,
702.                                                    &epilogue, sizeof(epilogue)));
703. 
704.   if (counter != nullptr) {
705. #if !(CUDA_VERSION >= 12020 && CUDA_VERSION < 13000)
706.     NVTE_ERROR("Atomic GEMM requires CUDA >=12.2.0 and <13.0.0, but compile-time CUDA version is ",
707.                CUDA_VERSION);
708. #elif !(CUBLAS_VERSION >= 120205 && CUBLAS_VERSION < 130000)
709.     NVTE_ERROR(
710.         "Atomic GEMM requires cuBLAS >=12.2.5 and <13.0.0, but compile-time cuBLAS version is ",
711.         CUBLAS_VERSION);
712. #else
713.     NVTE_CHECK(transformer_engine::cuda::cudart_version() >= 12020 &&
714.                    transformer_engine::cuda::cudart_version() < 13000,
715.                "Atomic GEMM requires CUDA >=12.2.0 and <13.0.0, but run-time CUDA version is ",
716.                transformer_engine::cuda::cudart_version());
717.     NVTE_CHECK(transformer_engine::cuda::cublas_version() >= 120205 &&
718.                    transformer_engine::cuda::cublas_version() < 130000,
719.                "Atomic GEMM requires cuBLAS >=12.2.5 and <13.0.0, but run-time cuBLAS version is ",
720.                transformer_engine::cuda::cublas_version());
