722.     if (n_split == 0) n_split = 1;
723.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
724.         operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_ROWS, &m_split,
725.         sizeof(m_split)));
726.     NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
727.         operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_COLS, &n_split,
728.         sizeof(n_split)));
729.     if (gemm_producer) {
730.       NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
731.           operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_OUT_COUNTERS_POINTER, &counter,
732.           sizeof(counter)));
733.     } else {
734.       NVTE_CHECK_CUBLAS(cublasLtMatmulDescSetAttribute(
735.           operationDesc, CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_IN_COUNTERS_POINTER, &counter,
736.           sizeof(counter)));
737.     }
738. #endif
739.   }
740. 
741.   // align the workspace to 256 B
742.   const int required_alignment = 256;
743.   const auto original_workspace_alignment = _getAlignment(reinterpret_cast<uintptr_t>(workspace));
744.   uint8_t *aligned_workspace_ptr =
745.       reinterpret_cast<uint8_t *>(workspace) + required_alignment - original_workspace_alignment;
746.   workspaceSize = workspaceSize - required_alignment + original_workspace_alignment;
747.   const auto new_workspace_alignment =
748.       _getAlignment(reinterpret_cast<uintptr_t>(aligned_workspace_ptr));
749.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceCreate(&preference));
750.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
751.       preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &workspaceSize, sizeof(workspaceSize)));
752.   const auto A_alignment = _getAlignment(reinterpret_cast<uintptr_t>(param.A));
753.   const auto B_alignment = _getAlignment(reinterpret_cast<uintptr_t>(param.B));
754.   const auto C_alignment = _getAlignment(reinterpret_cast<uintptr_t>(C));
755.   const auto D_alignment = _getAlignment(reinterpret_cast<uintptr_t>(D));
756.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
757.       preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_A_BYTES, &A_alignment, sizeof(A_alignment)));
758.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
759.       preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_B_BYTES, &B_alignment, sizeof(B_alignment)));
760.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
761.       preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_C_BYTES, &C_alignment, sizeof(C_alignment)));
762.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceSetAttribute(
763.       preference, CUBLASLT_MATMUL_PREF_MIN_ALIGNMENT_D_BYTES, &D_alignment, sizeof(D_alignment)));
764.   NVTE_CHECK(new_workspace_alignment % 256 == 0,
765.              "cuBLAS workspace pointer must be aligned to 256 bytes, got ",
766.              new_workspace_alignment);
767. 
768.   const auto status =
769.       cublasLtMatmulAlgoGetHeuristic(handle, operationDesc, Adesc, Bdesc, Cdesc, Ddesc, preference,
770.                                      1, &heuristicResult, &returnedResults);
771.   NVTE_CHECK(status != CUBLAS_STATUS_NOT_SUPPORTED,
772.              "Unable to find suitable cuBLAS GEMM algorithm");
773.   NVTE_CHECK_CUBLAS(status);
774.   if (returnedResults == 0) NVTE_ERROR("Unable to find any suitable algorithms");
775. 
776.   // D = alpha * (A * B) + beta * C
777.   NVTE_CHECK_CUBLAS(cublasLtMatmul(handle, operationDesc, alpha, /* alpha */
778.                                    param.A,                      /* A */
779.                                    Adesc, param.B,               /* B */
780.                                    Bdesc, beta,                  /* beta */
781.                                    C,                            /* C */
782.                                    Cdesc, D,                     /* D */
783.                                    Ddesc, &heuristicResult.algo, /* algo */
784.                                    aligned_workspace_ptr,        /* workspace */
785.                                    workspaceSize, stream));      /* stream */
786. 
787.   // Update FP8 scale-inv in output tensor
788.   // Note: This is a WAR for the case when we have fp8 output but D->scale_inv is not allocated.
789.   // TODO: Changing gemm interface so that D->scale_inv is allocated and the scale_inv can be
790.   // calculated here.
791.   if (is_fp8_dtype(outputD->data.dtype) && outputD->scale_inv.dptr) {
792.     update_tensor_scale_inv(outputD, stream);
793.   }
794. 
795.   NVTE_CHECK_CUBLAS(cublasLtMatmulPreferenceDestroy(preference));
796.   NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Ddesc));
797.   NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Cdesc));
798.   NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Bdesc));
799.   NVTE_CHECK_CUBLAS(cublasLtMatrixLayoutDestroy(Adesc));
800.   NVTE_CHECK_CUBLAS(cublasLtMatmulDescDestroy(operationDesc));
801. }
