201.   asm volatile(
202.       "cp.async.bulk.shared::cta.global"
203.       ".mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];" ::"r"(dst_shmem_ptr),
204.       "l"(src_global_ptr), "r"(size), "r"(mbar_ptr)
205.       : "memory");
