235.   uint32_t waitComplete;
236.   asm volatile(
237.       "{\n\t .reg .pred P_OUT; \n\t"
238.       "mbarrier.try_wait.parity.shared::cta.b64  P_OUT, [%1], %2; \n\t"
239.       "selp.b32 %0, 1, 0, P_OUT; \n"
240.       "}"
241.       : "=r"(waitComplete)
242.       : "r"(mbar_ptr), "r"(parity)
243.       : "memory");
244.   return static_cast<bool>(waitComplete);
245. #else
246.   NVTE_DEVICE_ERROR("mbarrier_try_wait_parity is only supported on SM 10.0+.");
247. #endif  // #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
248.   return true;
249. }
250. 
251. __device__ __forceinline__ void mbarrier_wait_parity(uint64_t *mbar, const uint32_t parity) {
252. #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
253.   uint32_t mbar_ptr = __cvta_generic_to_shared(mbar);
254.   while (!mbarrier_try_wait_parity(mbar_ptr, parity)) {
255.   }
256. #else
257.   NVTE_DEVICE_ERROR("mbarrier_wait_parity is only supported on SM 10.0+.");
258. #endif  // #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
259. }
260. 
261. __device__ __forceinline__ void mbarrier_wait_parity_acquire_cta_shared_cta(uint64_t *mbar,
262.                                                                             uint32_t phase_parity) {
263. #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
264.   uint32_t mbar_ptr = __cvta_generic_to_shared(mbar);
265.   asm volatile(
266.       "{\n\t"
267.       ".reg .b64 r1; \n\t"
268.       ".reg .pred waitComplete; \n\t"  // predicate representing if barrier condition is met
269.       "WAIT: \n\t"                     // loop around barrier wait
270.       "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64  waitComplete, [%0], %1; \n\t"
271.       "@waitComplete bra DONE; \n\t"  // mbarrier conditions are met
272.       "bra WAIT; \n\t"                // just a time-out, try again
273.       "DONE: \n\t"
274.       "}\n\t"
275.       :
276.       : "r"(mbar_ptr), "r"(phase_parity)
277.       : "memory");
278. #else
279.   NVTE_DEVICE_ERROR("mbarrier_wait_parity_acquire_cta_shared_cta is only supported on SM 10.0+.");
280. #endif  // #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)

