## §H Scaled Softmax warp forward 完整算法

`fused_softmax/scaled_masked_softmax.cu` 里 `scaled_softmax_warp_forward`：

```cpp
template <typename input_t, typename output_t, typename acc_t,
          int log2_elements>
__global__ void scaled_softmax_warp_forward(
    output_t* dst, const input_t* src,
    const acc_t scale,
    int micro_batch_size, int element_count) {
  constexpr int next_power_of_two = 1 << log2_elements;       // pad 到 2^k
  constexpr int WARP_SIZE         = (next_power_of_two < 32) ? next_power_of_two : 32;
  constexpr int WARP_ITERATIONS   = next_power_of_two / WARP_SIZE;
  constexpr int WARP_BATCH        = (next_power_of_two <= 128) ? 2 : 1;

  int local_idx = threadIdx.x;
  int first_batch = (blockDim.y * blockIdx.x + threadIdx.y) * WARP_BATCH;
  int local_batches = min(micro_batch_size - first_batch, WARP_BATCH);

  // 1) Load + scale
  acc_t elements[WARP_BATCH][WARP_ITERATIONS];
  #pragma unroll
  for (int i = 0; i < WARP_BATCH; ++i) {
    int batch_element_count = (i >= local_batches) ? 0 : element_count;
    #pragma unroll
    for (int it = 0; it < WARP_ITERATIONS; ++it) {
      int element_index = local_idx + it * WARP_SIZE;
      if (element_index < batch_element_count)
        elements[i][it] = static_cast<acc_t>(src[(first_batch+i)*element_count + element_index]) * scale;
      else
        elements[i][it] = -std::numeric_limits<acc_t>::infinity();
    }
  }

  // 2) Warp reduce max
  acc_t max_value[WARP_BATCH];
  #pragma unroll
  for (int i = 0; i < WARP_BATCH; ++i) {
    max_value[i] = elements[i][0];
    #pragma unroll
    for (int it = 1; it < WARP_ITERATIONS; ++it)
      max_value[i] = max(max_value[i], elements[i][it]);
  }
  warp_reduce<acc_t, WARP_BATCH, WARP_SIZE, Max>(max_value);

  // 3) exp + 累 sum
  acc_t sum[WARP_BATCH] = {0};
  #pragma unroll
  for (int i = 0; i < WARP_BATCH; ++i) {
    #pragma unroll
    for (int it = 0; it < WARP_ITERATIONS; ++it) {
      elements[i][it] = std::exp(elements[i][it] - max_value[i]);
      sum[i] += elements[i][it];
    }
  }
  warp_reduce<acc_t, WARP_BATCH, WARP_SIZE, Add>(sum);

  // 4) 归一化输出
  #pragma unroll
  for (int i = 0; i < WARP_BATCH; ++i) {
    if (i >= local_batches) break;
    acc_t inv = acc_t(1.0) / sum[i];
    #pragma unroll
    for (int it = 0; it < WARP_ITERATIONS; ++it) {
      int element_index = local_idx + it*WARP_SIZE;
      if (element_index < element_count)
        dst[(first_batch+i)*element_count + element_index] =
            static_cast<output_t>(elements[i][it] * inv);
    }
  }
}
```

要点：
- 整行的 softmax 完全在 **一个 warp 内**完成，避免 shared memory + block-level sync
- 用模板 `log2_elements` 编译期决定 WARP_ITERATIONS，编出大约十几个变种覆盖 d∈[1, 16384]
- `WARP_BATCH=2` 在小 d 时让一个 warp 同时处理两行，提升 occupancy
- `masked_softmax` / `upper_tri_softmax` 只是在第 1 步 load 时把被 mask 位置置 -inf

反向 `scaled_softmax_warp_backward` 是 `dx = y * (dy - sum(dy * y))`，同样 1 warp 1 行。

