## §I Fused RoPE：`fused_rope/fused_rope.cu`

```cpp
template <typename scalar_t>
__device__ void fused_rope_block_forward(
    const scalar_t* src,
    const float*    freqs,    // [s, 1, 1, d2]
    scalar_t*       dst,
    int s_id, int b_id, int h_id, int hidden_d, int rotary_d,
    int stride_s, int stride_b, int stride_h, int stride_d,
    bool interleaved) {
  // 把 sin/cos 缓存到 shared memory：每行的 d2 = rotary_d
  extern __shared__ float smem[];
  float* sin_buf = smem;
  float* cos_buf = smem + rotary_d / 2;

  for (int d = threadIdx.x; d < rotary_d / 2; d += blockDim.x) {
    float f = freqs[s_id * rotary_d + d];   // 已是 cos(θ) / sin(θ) 拼好的
    cos_buf[d] = cosf(f);
    sin_buf[d] = sinf(f);
  }
  __syncthreads();

  // 旋转
  for (int d = threadIdx.x; d < rotary_d / 2; d += blockDim.x) {
    int idx0, idx1;
    if (interleaved) {
      // pair = (2d, 2d+1)
      idx0 = 2*d;     idx1 = 2*d + 1;
    } else {
      // pair = (d, d + rotary_d/2)
      idx0 = d;       idx1 = d + rotary_d/2;
    }
    float x0 = static_cast<float>(src[s_id*stride_s + b_id*stride_b + h_id*stride_h + idx0*stride_d]);
    float x1 = static_cast<float>(src[s_id*stride_s + b_id*stride_b + h_id*stride_h + idx1*stride_d]);
    float c  = cos_buf[d], si = sin_buf[d];
    dst[... idx0 ...] = static_cast<scalar_t>(x0 * c - x1 * si);
    dst[... idx1 ...] = static_cast<scalar_t>(x0 * si + x1 * c);
  }
  // hidden_d > rotary_d 的部分原样拷
  for (int d = rotary_d + threadIdx.x; d < hidden_d; d += blockDim.x)
    dst[... d ...] = src[... d ...];
}
```

**反向** `fused_rope_block_backward` 用同一组 (cos, sin) 反向旋转 `dy`：
```
dx0 =  dy0 * cos + dy1 * sin
dx1 = -dy0 * sin + dy1 * cos
```

`fused_rope_block_thd` 处理 THD 变长 layout：`s_id` 来自 `cu_seqlens` 查表的"本 seq 内位置"，从而不同样本可用不同位置编码。

