## §K UserBuffers：原子 producer-consumer + NVLink/IB

`comm_gemm_overlap/userbuffers/userbuffers.cu` 实现 TP 通信和 GEMM overlap 的核心。一个简化版 reduce-scatter 内核：

```cpp
#define ATOMIC_CONSUMER(chunk)                                       \
  if (counters && threadIdx.x == 0 && blockIdx.x == 0) {             \
    /* 自旋等待 producer 把 counter[chunk] 置 1 */                    \
    while (atomicCAS(&counters[chunk], 1, 0) != 1) { /* spin */ }     \
    __threadfence_system();                                          \
  }                                                                  \
  __syncthreads();

#define ATOMIC_PRODUCER(chunk)                                       \
  if (counters && threadIdx.x == 0 && blockIdx.x == 0) {             \
    __threadfence_system();                                          \
    counters[chunk] = 1;                                             \
  }

template <int RANKS, typename fp_t>
__global__ void userbuffers_fp16_sum_inplace_gpu_rw(
    fp_t* __restrict__ rs_recv, fp_t* const* __restrict__ peer_ptrs,
    const int my_rank, const int chunks, const size_t elems_per_chunk,
    int* counters /*device-side*/) {
  for (int chunk = blockIdx.y; chunk < chunks; chunk += gridDim.y) {
    ATOMIC_CONSUMER(chunk);    // 等 cuBLASLt atomic GEMM 把这块算完
    // 跨 RANKS 求和：从每个 peer 的同一 chunk load 并加到本地
    fp_t acc = 0;
    #pragma unroll
    for (int r = 0; r < RANKS; ++r)
      acc += peer_ptrs[r][chunk*elems_per_chunk + element_idx];
    rs_recv[chunk*elems_per_chunk + element_idx] = acc;
  }
}
```

关键点：
- `peer_ptrs[r]` 是通过 **CUDA IPC / fabric handle** 拿到的同节点其它 GPU 的设备指针，访存通过 NVLink 完成
- 跨节点用 NVSHMEM 或者 GDR-over-IB，wrapper 在同一份 userbuffers C++ 入口分发
- `atomicCAS(&counters[chunk], 1, 0)` 既等待又把 counter 清零（next iter 可以复用）
- `__threadfence_system()` 保证 NVLink 上 producer 的写对 consumer 可见

**Atomic GEMM × UserBuffers**：cuBLASLt 每完成 GEMM 的一个 chunk 就把 `atomic_out_counter[chunk] = 1`；userbuffers kernel 自旋等待该 counter 一翻转就立刻消费，于是 GEMM 仍在算最后几块时，前面已经在网络上飞了——这就是 TE 在 H100 8×8 上 GEMM/AllReduce overlap 能压到 ~95% 的根因。

---

## §L multi_tensor Adam FP8：`multi_tensor/adam.cu`

继承自 Apex `multi_tensor_apply`，但 master weight 可选 FP8 存储以节省显存。每个 chunk 256 elements 一组：

```cpp
struct FP8Data {
  __nv_fp8_e4m3* ptr;
  float* scale;       // tensor-wise scale
  float* amax_ptr;    // 每个 tensor 一个 amax
  float* scale_inv_ptr;
  float  max;         // E4M3 max = 448
  int    warp_id;
};

template <typename T_p, typename T_g, typename FP8Master /* = void or FP8Data */>
struct AdamFunctorMaster {
  __device__ __forceinline__ void operator()(
      int chunk_size, volatile int* noop_gmem,
      TensorListMetadata<n_tensors>& tl,
      const float beta1, const float beta2,
      const float beta1_correction, const float beta2_correction,
      const float epsilon, const float lr, adamMode_t mode,
      const float decay) {
    int tensor_loc = tl.block_to_tensor[blockIdx.x];
    int chunk_idx  = tl.block_to_chunk[blockIdx.x];
    int n = tl.sizes[tensor_loc];
    T_p* p = (T_p*)tl.addresses[0][tensor_loc] + chunk_idx*chunk_size;
    T_g* g = (T_g*)tl.addresses[1][tensor_loc] + chunk_idx*chunk_size;
    float* m = (float*)tl.addresses[2][tensor_loc] + chunk_idx*chunk_size;
    float* v = (float*)tl.addresses[3][tensor_loc] + chunk_idx*chunk_size;
    n = min(chunk_size, n - chunk_idx*chunk_size);

    // 向量化 load (LDG.128) — 4 个 float / 8 个 half / 16 个 fp8
    for (int i = threadIdx.x*ILP; i < n; i += blockDim.x*ILP) {
      ...
      float pi = master_to_fp32(p_master, i);   // FP32 / FP8→FP32
      float gi = static_cast<float>(g[i]) * grad_scale;
      float mi = beta1 * m[i] + (1.f - beta1) * gi;
      float vi = beta2 * v[i] + (1.f - beta2) * gi * gi;
      float m_hat = mi / beta1_correction;
      float v_hat = vi / beta2_correction;
      float upd   = m_hat / (sqrtf(v_hat) + epsilon);
      if (mode == ADAM_MODE_W) upd += decay * pi;
      else                     pi  *= (1.f - lr * decay);
      pi -= lr * upd;

      m[i] = mi; v[i] = vi;
      // 写回 master weight
      if constexpr (!std::is_same_v<FP8Master, void>) {
        amax = fmaxf(amax, fabsf(pi));
        p_master.ptr[i] = quantize_e4m3(pi, *p_master.scale);
      } else {
        p_master[i] = pi;
      }
      // 同时写"working copy"（FP16/BF16）给前向 GEMM 用
      p[i] = static_cast<T_p>(pi);
    }
    if constexpr (!std::is_same_v<FP8Master, void>) {
      block_amax_reduce_atomic(amax, p_master.amax_ptr);
    }
  }
};
```

特点：
- **TensorListMetadata** 把所有要更新的 tensor 打成一张表，单个 grid 完成几千个 tensor 的 Adam（避免 launch overhead）
- FP8 master 路径在 step 末尾顺手算 amax，给下一步 scale 更新（§G）做输入
- `noop_gmem`：全局 NaN/Inf 标志，loss scaler 检测到溢出时设置，kernel 内一旦发现非零就 skip 这一步更新

