## §N PTX 工具栈：`util/ptx.cuh`

TE 的 Hopper/Blackwell 加速大量依赖三组内联 PTX：

### N.1 `mbarrier`（细粒度异步 barrier）

```cpp
__device__ __forceinline__ void mbarrier_init(uint64_t* mbar, uint32_t count) {
  uint32_t mbar_ptr = __cvta_generic_to_shared(mbar);
  asm volatile("mbarrier.init.shared.b64 [%0], %1;" :: "r"(mbar_ptr), "r"(count) : "memory");
}
__device__ __forceinline__ void mbarrier_arrive_expect_tx(uint64_t* mbar, uint32_t tx_count) {
  asm volatile("mbarrier.arrive.expect_tx.shared.b64 _, [%0], %1;"
               :: "r"(__cvta_generic_to_shared(mbar)), "r"(tx_count) : "memory");
}
__device__ __forceinline__ void mbarrier_wait_parity(uint64_t* mbar, uint32_t parity) {
  uint32_t mbar_ptr = __cvta_generic_to_shared(mbar);
  while (!mbarrier_try_wait_parity(mbar_ptr, parity)) { }
}
```

`mbarrier` 比传统 `__syncthreads()` 强：可以"等若干 byte 被 TMA 搬过来"（`arrive.expect_tx`），不需要轮询全局 flag。两个相位 (parity 0/1) 交替使用，避免 reset 开销。

### N.2 TMA：`cp.async.bulk.tensor.2d`

```cpp
__device__ __forceinline__ void cp_async_bulk_tensor_2d_global_to_shared(
    uint64_t* dst_shmem, const uint64_t* tensor_map_ptr,
    uint32_t offset_x, uint32_t offset_y, uint64_t* mbar) {
  uint32_t dst   = __cvta_generic_to_shared(dst_shmem);
  uint32_t mbar_ = __cvta_generic_to_shared(mbar);
  asm volatile(
    "cp.async.bulk.tensor.2d.shared::cluster.global.tile"
    ".mbarrier::complete_tx::bytes [%0], [%1, {%2, %3}], [%4];"
    :: "r"(dst), "l"(tensor_map_ptr), "r"(offset_x), "r"(offset_y), "r"(mbar_)
    : "memory");
}
```

调用方式：
1. CPU 端 `cuTensorMapEncodeTiled` 把 (global ptr, shape, stride, swizzle) 编码成 128-byte `CUtensorMap`，传入 kernel
2. Kernel 内 `mbarrier_init` → `mbarrier_arrive_expect_tx(bytes)` → 上面这条 PTX 把 2D tile 整块异步搬到 shared
3. `mbarrier_wait_parity` 等 TMA 完成
4. 计算线程消费 shared

TE 用这套机制实现：
- MXFP8 cast 的 2D 瓦片输入
- NVFP4 cast 的 2D 瓦片输入
- cast_transpose_fusion 的 1D ldgsts 替换

### N.3 stochastic rounding（Blackwell）

```cpp
#define ARCH_HAS_STOCHASTIC_ROUNDING \
  NVTE_CUDA_ARCH_MATCHES(ptx::ArchSpecific<100>, ptx::ArchSpecific<103>)

__device__ __forceinline__ __nv_fp8_e4m3 cvt_fp32_to_e4m3_sr(float x, uint32_t rand_bits) {
  uint16_t out;
  asm volatile("cvt.rn.sr.satfinite.e4m3x2.f32 %0, %2, %1;"
               : "=h"(out) : "f"(x), "r"(rand_bits));
  return *reinterpret_cast<__nv_fp8_e4m3*>(&out);
}
```

把"舍入"中的随机比特喂给硬件，实现"无偏量化"——在 FP8 训练中比常规 RN 舍入收敛更稳，**只有 sm100a/sm103a 才有**，TE 通过 `ArchSpecific` 模板做编译期分发。

